INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C1','math',6,2,'u3',2,'두 수에 같은 수를 곱해도 몫은 그대로 — 단위를 바꾸거나(cm→mm, m→cm) 두 수를 똑같이 10배·100배 해서 나누는 수가 소수인 나눗셈을 자연수의 나눗셈으로 바꾸기',ARRAY['6수01-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C2','math',6,2,'u3',2,'소수를 분모가 같은 분수로 바꾸어 나누기 — 두 소수를 분모가 10(100)인 분수로 함께 바꾼 뒤 분자끼리 나누기',ARRAY['6수01-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C3','math',6,2,'u3',3,'(소수 한 자리)÷(소수 한 자리) 세로셈 — 나누는 수가 자연수가 되도록 두 수의 소수점을 똑같이 한 칸 옮기고, 몫의 소수점은 옮긴 자리에서 올려 찍기',ARRAY['6수01-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C4','math',6,2,'u3',4,'(소수 두 자리)÷(소수 두 자리) — 옮기는 칸수는 나누는 수의 소수 자리 수가 정함을 알고 두 수의 소수점을 두 칸씩 옮겨 계산하기',ARRAY['6수01-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C5','math',6,2,'u3',5,'자릿수가 다른 (소수)÷(소수) — 나누는 수가 자연수가 되는 만큼 두 수를 옮기고, 빈 자리는 0으로 채우며, 나누어지는 수에 소수점이 남아도 그대로 계산하기',ARRAY['6수01-11']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C6','math',6,2,'u3',6,'(자연수)÷(소수) — 자연수를 8 = 8.0처럼 보고 소수점을 함께 옮겨 빈 자리를 0으로 채우며, 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커짐을 알기',ARRAY['6수01-11']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C7','math',6,2,'u3',7,'몫을 반올림하여 나타내기 — 나누어떨어지지 않는 몫을 나타낼 자리의 한 자리 아래 숫자를 보고 반올림하여 일의 자리·소수 첫째·둘째 자리까지 나타내기',ARRAY['6수01-11']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C8','math',6,2,'u3',8,'나누어 주고 남는 양 — 나누어 줄 수 있는 수는 몫의 자연수 부분으로 정하고, 남는 양은 전체에서 (한 몫 × 나누어 준 수)를 빼서 구하기',ARRAY['6수01-11']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X01','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5']::text[],'두 수 가운데 한 수만 10배·100배 하거나 한 수의 소수점만 옮긴다(3.6 ÷ 0.5를 3.6 ÷ 5로)','두 수의 소수점은 똑같이 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X02','math',6,'u3',ARRAY['M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6']::text[],'옮기는 칸수를 잘못 정한다 — 나누어지는 수의 소수 자리 수에 맞추거나 더 많이·적게 옮긴다','칸수는 나누는 수가 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X03','math',6,'u3',ARRAY['M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6']::text[],'몫의 소수점을 옮기기 전 원래 자리에 찍어 몫을 10배·100배 작게 쓴다','몫의 소수점은 옮긴 자리에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X04','math',6,'u3',ARRAY['M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6']::text[],'몫의 소수점을 빠뜨리거나 한 자리 뒤에 찍어 몫을 10배·100배 크게 쓴다','어림한 값과 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X05','math',6,'u3',ARRAY['M6-2-u3-C2','M6-2-u3-C4']::text[],'소수를 분수로 바꿀 때 분모를 서로 다르게(10과 100을 섞어) 쓴다','두 수를 같은 분모로 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X06','math',6,'u3',ARRAY['M6-2-u3-C2']::text[],'한 수만 분수로 바꾸고 다른 수는 소수 그대로 둔다','둘 다 분수로 바꿔야 분자끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X07','math',6,'u3',ARRAY['M6-2-u3-C5','M6-2-u3-C6']::text[],'소수점을 옮길 때 빈 자리를 0으로 채우지 않는다(5.4를 두 칸 옮겨 54로)','빈 자리는 0으로 채워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X08','math',6,'u3',ARRAY['M6-2-u3-C6']::text[],'(자연수)÷(소수)에서 자연수 쪽 소수점은 옮기지 않는다(8 ÷ 1.6을 8 ÷ 16으로)','8은 8.0 — 함께 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X09','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C6']::text[],'「나누면 몫은 작아진다」고 여겨 1보다 작은 수로 나눌 때 몫이 커지는 것을 틀렸다고 본다','1보다 작은 수로 나누면 몫이 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X10','math',6,'u3',ARRAY['M6-2-u3-C7']::text[],'반올림할 때 나타낼 자리의 숫자를 보고 올리거나 버린다(한 자리 아래를 봐야 한다)','나타낼 자리 바로 아래 숫자를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X11','math',6,'u3',ARRAY['M6-2-u3-C7']::text[],'반올림하지 않고 아랫자리를 그냥 버린다','5 이상이면 올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X12','math',6,'u3',ARRAY['M6-2-u3-C7']::text[],'어느 자리까지 나타낼지 잘못 읽는다(일의 자리·소수 첫째·둘째 자리를 바꾼다)','「어느 자리까지」에 밑줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X13','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'나누어 줄 수 있는 사람(그릇) 수를 몫을 반올림해 정한다','모자라면 줄 수 없어요 — 자연수 부분만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X14','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'남는 양을 몫의 소수 부분으로 읽는다(4.33…에서 0.3 L가 남는다고 본다)','남는 양은 전체 − 나누어 준 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X15','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'남는 양 대신 전체 양이나 나누어 준 양을 답으로 쓴다','무엇을 묻는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X16','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C3','M6-2-u3-C5','M6-2-u3-C6']::text[],'몇 배·몇 번을 구하는데 나눗셈 대신 곱셈·뺄셈을 한다','몇 배인지는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X17','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C3','M6-2-u3-C6']::text[],'나누어지는 수와 나누는 수를 바꾸어 쓴다','「무엇을 얼마씩」 — 무엇이 앞') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X18','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C4']::text[],'단위를 바꿀 때 한쪽만 바꾸거나 배수를 잘못 쓴다(1 cm = 10 mm, 1 m = 100 cm)','두 수를 같은 단위로 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X19','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C2','M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6','M6-2-u3-C7','M6-2-u3-C8']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 큰↔작은, 같은↔다른','물음의 「잘못·가장·다른」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X20','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C2','M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6','M6-2-u3-C7','M6-2-u3-C8']::text[],'옮긴 뒤 자연수의 나눗셈·곱셈을 잘못 계산한다','곱셈으로 거꾸로 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#1','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',1,'sa','auto','12 ÷ 3의 몫은 4예요. 두 수에 똑같이 10을 곱한 120 ÷ 30의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"12 ÷ 3의 몫은 4예요. 두 수에 똑같이 10을 곱한 120 ÷ 30의 몫은 얼마인가요?","answer":["4"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","120 ÷ 30은 12 ÷ 3의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 4예요."],"variant_rule":{"alt":[{"stem":"18 ÷ 6의 몫은 3이에요. 두 수에 똑같이 10을 곱한 180 ÷ 60의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","180 ÷ 60은 18 ÷ 6의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 3이에요."]},{"stem":"24 ÷ 8의 몫은 3이에요. 두 수에 똑같이 100을 곱한 2400 ÷ 800의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","2400 ÷ 800은 24 ÷ 8의 두 수에 100을 곱한 식이에요.","그래서 몫은 그대로 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#2','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',1,'sa','auto','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 2.4 cm는 24 mm, 0.8 cm는 8 mm예요. 빨간 화분의 강낭콩 싹은 노란 화분의 강낭콩 싹의 몇 배인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 2.4 cm는 24 mm, 0.8 cm는 8 mm예요. 빨간 화분의 강낭콩 싹은 노란 화분의 강낭콩 싹의 몇 배인가요?","answer":["3"],"explanation":["몇 배인지는 나눗셈으로 구해요.","단위를 바꾸면 24 ÷ 8이 돼요.","24 ÷ 8 = 3 — 3배예요."],"variant_rule":{"alt":[{"stem":"빨간 화분의 강낭콩 싹은 3.6 cm, 노란 화분의 강낭콩 싹은 0.9 cm예요. 3.6 cm는 36 mm, 0.9 cm는 9 mm예요. 빨간 화분의 강낭콩 싹은 노란 화분의 강낭콩 싹의 몇 배인가요?","answer":["4"],"explanation":["몇 배인지는 나눗셈으로 구해요.","단위를 바꾸면 36 ÷ 9가 돼요.","36 ÷ 9 = 4 — 4배예요."]},{"stem":"빨간 화분의 강낭콩 싹은 4.2 cm, 노란 화분의 강낭콩 싹은 0.6 cm예요. 4.2 cm는 42 mm, 0.6 cm는 6 mm예요. 빨간 화분의 강낭콩 싹은 노란 화분의 강낭콩 싹의 몇 배인가요?","answer":["7"],"explanation":["몇 배인지는 나눗셈으로 구해요.","단위를 바꾸면 42 ÷ 6이 돼요.","42 ÷ 6 = 7 — 7배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#3','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',1,'mc','auto','8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":1,"kind":"mc","stem":"8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ ÷ ⟨21/10⟩","correct":true},{"t":"⟨84/10⟩ ÷ 2.1","mis":"M6-2-u3-X06"},{"t":"⟨84/10⟩ ÷ ⟨21/100⟩","mis":"M6-2-u3-X05"},{"t":"8.4 ÷ ⟨21/10⟩","mis":"M6-2-u3-X06"}],"explanation":["8.4는 ⟨84/10⟩, 2.1은 ⟨21/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨84/10⟩ ÷ ⟨21/10⟩이에요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨49/10⟩ ÷ ⟨7/10⟩","correct":true},{"t":"⟨49/10⟩ ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"⟨49/10⟩ ÷ ⟨7/100⟩","mis":"M6-2-u3-X05"},{"t":"4.9 ÷ ⟨7/10⟩","mis":"M6-2-u3-X06"}],"explanation":["4.9는 ⟨49/10⟩, 0.7은 ⟨7/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨49/10⟩ ÷ ⟨7/10⟩이에요."]},{"stem":"7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨72/10⟩ ÷ ⟨6/10⟩","correct":true},{"t":"⟨72/10⟩ ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"⟨72/10⟩ ÷ ⟨6/100⟩","mis":"M6-2-u3-X05"},{"t":"7.2 ÷ ⟨6/10⟩","mis":"M6-2-u3-X06"}],"explanation":["7.2는 ⟨72/10⟩, 0.6은 ⟨6/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨72/10⟩ ÷ ⟨6/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#4','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',1,'sa','auto','⟨84/10⟩ ÷ ⟨21/10⟩은 분자끼리 나누어 84 ÷ 21이 돼요. 8.4 ÷ 2.1의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C2","difficulty":1,"kind":"sa","stem":"⟨84/10⟩ ÷ ⟨21/10⟩은 분자끼리 나누어 84 ÷ 21이 돼요. 8.4 ÷ 2.1의 몫은 얼마인가요?","answer":["4"],"explanation":["8.4 ÷ 2.1은 ⟨84/10⟩ ÷ ⟨21/10⟩과 같아요.","분모가 같으니 분자끼리 84 ÷ 21이에요.","몫은 4예요."],"variant_rule":{"alt":[{"stem":"⟨96/10⟩ ÷ ⟨32/10⟩는 분자끼리 나누어 96 ÷ 32가 돼요. 9.6 ÷ 3.2의 몫은 얼마인가요?","answer":["3"],"explanation":["9.6 ÷ 3.2는 ⟨96/10⟩ ÷ ⟨32/10⟩와 같아요.","분모가 같으니 분자끼리 96 ÷ 32예요.","몫은 3이에요."]},{"stem":"⟨63/10⟩ ÷ ⟨9/10⟩는 분자끼리 나누어 63 ÷ 9가 돼요. 6.3 ÷ 0.9의 몫은 얼마인가요?","answer":["7"],"explanation":["6.3 ÷ 0.9는 ⟨63/10⟩ ÷ ⟨9/10⟩와 같아요.","분모가 같으니 분자끼리 63 ÷ 9예요.","몫은 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#5','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',2,'mc','auto','4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":5,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"49 ÷ 7","correct":true},{"t":"49 ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"4.9 ÷ 7","mis":"M6-2-u3-X01"},{"t":"49 ÷ 70","mis":"M6-2-u3-X05"}],"explanation":["4.9 = ⟨49/10⟩, 0.7 = ⟨7/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 49 ÷ 7이에요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"72 ÷ 6","correct":true},{"t":"72 ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"7.2 ÷ 6","mis":"M6-2-u3-X01"},{"t":"72 ÷ 60","mis":"M6-2-u3-X05"}],"explanation":["7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 72 ÷ 6이에요."]},{"stem":"5.6 ÷ 0.8을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"56 ÷ 8","correct":true},{"t":"56 ÷ 0.8","mis":"M6-2-u3-X06"},{"t":"5.6 ÷ 8","mis":"M6-2-u3-X01"},{"t":"56 ÷ 80","mis":"M6-2-u3-X05"}],"explanation":["5.6 = ⟨56/10⟩, 0.8 = ⟨8/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 56 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#6','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'mc','auto','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":6,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 8","correct":true},{"t":"24 ÷ 0.8","mis":"M6-2-u3-X18"},{"t":"2.4 ÷ 8","mis":"M6-2-u3-X18"},{"t":"8 ÷ 24","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","2.4 cm는 24 mm, 0.8 cm는 8 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 24 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"빨간 화분의 강낭콩 싹은 3.6 cm, 노란 화분의 강낭콩 싹은 1.2 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"36 ÷ 12","correct":true},{"t":"36 ÷ 1.2","mis":"M6-2-u3-X18"},{"t":"3.6 ÷ 12","mis":"M6-2-u3-X18"},{"t":"12 ÷ 36","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","3.6 cm는 36 mm, 1.2 cm는 12 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 36 ÷ 12예요."]},{"stem":"빨간 화분의 강낭콩 싹은 5.4 cm, 노란 화분의 강낭콩 싹은 0.9 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"54 ÷ 9","correct":true},{"t":"54 ÷ 0.9","mis":"M6-2-u3-X18"},{"t":"5.4 ÷ 9","mis":"M6-2-u3-X18"},{"t":"9 ÷ 54","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","5.4 cm는 54 mm, 0.9 cm는 9 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 54 ÷ 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#7','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'mc','auto','cm를 mm로 바꾸어 계산해도 몫이 같은 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X18']::text[],true,'{"seq":7,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"cm를 mm로 바꾸어 계산해도 몫이 같은 까닭은 무엇인가요?","options":[{"t":"두 수가 똑같이 10배가 되어서","correct":true},{"t":"나누어지는 수만 10배가 되어서","mis":"M6-2-u3-X01"},{"t":"나누는 수만 10배가 되어서","mis":"M6-2-u3-X01"},{"t":"두 수가 모두 작아져서","mis":"M6-2-u3-X18"}],"explanation":["1 cm는 10 mm라서 cm를 mm로 바꾸면 두 수가 모두 10배가 돼요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 단위를 바꾸어 계산해도 몫이 같아요."],"variant_rule":{"alt":[{"stem":"m를 cm로 바꾸어 계산해도 몫이 같은 까닭은 무엇인가요?","options":[{"t":"두 수가 똑같이 100배가 되어서","correct":true},{"t":"나누어지는 수만 100배가 되어서","mis":"M6-2-u3-X01"},{"t":"나누는 수만 100배가 되어서","mis":"M6-2-u3-X01"},{"t":"두 수가 모두 10배가 되어서","mis":"M6-2-u3-X18"}],"explanation":["1 m는 100 cm라서 두 수가 모두 100배가 돼요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 단위를 바꾸어 계산해도 몫이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#8','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'sa','auto','2.4 ÷ 0.8의 몫을 어림해요. 0.8을 몇 번 더하면 2.4가 되나요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u3-C1","difficulty":2,"kind":"sa","stem":"2.4 ÷ 0.8의 몫을 어림해요. 0.8을 몇 번 더하면 2.4가 되나요?","answer":["3"],"explanation":["0.8 + 0.8 = 1.6이에요.","1.6 + 0.8 = 2.4예요.","0.8을 3번 더하면 2.4 — 몫은 3쯤이에요."],"variant_rule":{"alt":[{"stem":"3.5 ÷ 0.7의 몫을 어림해요. 0.7을 몇 번 더하면 3.5가 되나요?","answer":["5"],"explanation":["0.7을 두 번 더하면 1.4, 네 번 더하면 2.8이에요.","2.8 + 0.7 = 3.5예요.","0.7을 5번 더하면 3.5 — 몫은 5쯤이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#9','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'ox','auto','1.5 ÷ 3의 몫은 0.5예요. 나누는 수만 0.3으로 바꾸면 1.5 ÷ 0.3의 몫은 0.5보다 작아져요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":9,"concept":"M6-2-u3-C1","difficulty":2,"kind":"ox","stem":"1.5 ÷ 3의 몫은 0.5예요. 나누는 수만 0.3으로 바꾸면 1.5 ÷ 0.3의 몫은 0.5보다 작아져요.","answer":"X","reason_options":[{"t":"나누는 수가 작아지면 더 여러 번 들어가서 몫이 커지기 때문에","correct":true},{"t":"나누는 수가 작아지면 몫도 따라 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["1.5 ÷ 0.3은 15 ÷ 3과 같아요.","15 ÷ 3 = 5예요.","몫은 0.5보다 커져요 — 작은 수로 나누면 더 여러 번 들어가요."],"variant_rule":{"alt":[{"stem":"2.4 ÷ 4의 몫은 0.6이에요. 나누는 수만 0.4로 바꾸면 2.4 ÷ 0.4의 몫은 0.6보다 작아져요.","answer":"X","reason_options":[{"t":"나누는 수가 작아지면 더 여러 번 들어가서 몫이 커지기 때문에","correct":true},{"t":"나누는 수가 작아지면 몫도 따라 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["2.4 ÷ 0.4는 24 ÷ 4와 같아요.","24 ÷ 4 = 6이에요.","몫은 0.6보다 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_basic#10','math',6,2,'u3','L02','g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',3,'ox','auto','8.4 ÷ 2.1을 계산할 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.',ARRAY['M6-2-u3-X06']::text[],true,'{"seq":10,"concept":"M6-2-u3-C2","difficulty":3,"kind":"ox","stem":"8.4 ÷ 2.1을 계산할 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"mis":"M6-2-u3-X06","explanation":["⟨84/10⟩ ÷ 2.1은 분자끼리 나눌 수 없어요.","2.1도 ⟨21/10⟩로 바꾸어야 해요.","⟨84/10⟩ ÷ ⟨21/10⟩ = 84 ÷ 21 = 4예요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 계산할 때 7.2는 ⟨72/10⟩로, 0.6은 ⟨6/100⟩으로 바꾸면 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수로 바꾸기만 하면 분모는 달라도 되기 때문에","mis":"M6-2-u3-X05"}],"explanation":["0.6은 ⟨6/10⟩이지 ⟨6/100⟩이 아니에요.","두 수를 분모가 10인 분수로 함께 바꿔요.","⟨72/10⟩ ÷ ⟨6/10⟩ = 72 ÷ 6 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#1','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',2,'mc','auto','1.5 ÷ 0.3과 몫이 같은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"1.5 ÷ 0.3과 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"15 ÷ 3","correct":true},{"t":"1.5 ÷ 3","mis":"M6-2-u3-X01"},{"t":"15 ÷ 0.3","mis":"M6-2-u3-X01"},{"t":"150 ÷ 3","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","1.5 ÷ 0.3의 두 수에 똑같이 10을 곱하면 15 ÷ 3이에요.","한 수만 바꾼 식은 몫이 달라요."],"variant_rule":{"alt":[{"stem":"2.8 ÷ 0.4와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"28 ÷ 4","correct":true},{"t":"2.8 ÷ 4","mis":"M6-2-u3-X01"},{"t":"28 ÷ 0.4","mis":"M6-2-u3-X01"},{"t":"280 ÷ 4","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","2.8 ÷ 0.4의 두 수에 똑같이 10을 곱하면 28 ÷ 4예요.","한 수만 바꾼 식은 몫이 달라요."]},{"stem":"0.36 ÷ 0.04와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"36 ÷ 4","correct":true},{"t":"0.36 ÷ 4","mis":"M6-2-u3-X01"},{"t":"36 ÷ 0.04","mis":"M6-2-u3-X01"},{"t":"360 ÷ 4","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","0.36 ÷ 0.04의 두 수에 똑같이 100을 곱하면 36 ÷ 4예요.","한 수만 바꾼 식은 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#2','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',2,'mc','auto','7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":2,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"72 ÷ 6","correct":true},{"t":"72 ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"7.2 ÷ 6","mis":"M6-2-u3-X01"},{"t":"72 ÷ 60","mis":"M6-2-u3-X05"}],"explanation":["7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 72 ÷ 6이에요."],"variant_rule":{"alt":[{"stem":"8.1 ÷ 0.9를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"81 ÷ 9","correct":true},{"t":"81 ÷ 0.9","mis":"M6-2-u3-X06"},{"t":"8.1 ÷ 9","mis":"M6-2-u3-X01"},{"t":"81 ÷ 90","mis":"M6-2-u3-X05"}],"explanation":["8.1 = ⟨81/10⟩, 0.9 = ⟨9/10⟩예요.","분모가 같으니 분자끼리 나눠요.","그래서 81 ÷ 9예요."]},{"stem":"9.6 ÷ 1.2를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"96 ÷ 12","correct":true},{"t":"96 ÷ 1.2","mis":"M6-2-u3-X06"},{"t":"9.6 ÷ 12","mis":"M6-2-u3-X01"},{"t":"96 ÷ 120","mis":"M6-2-u3-X05"}],"explanation":["9.6 = ⟨96/10⟩, 1.2 = ⟨12/10⟩예요.","분모가 같으니 분자끼리 나눠요.","그래서 96 ÷ 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#3','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',3,'error','auto','8.4 ÷ 2.1의 계산 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X19']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":3,"kind":"error","stem":"8.4 ÷ 2.1의 계산 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「8.4는 분수로 바꾸고 2.1은 소수 그대로 둬도 돼.」","correct":true,"mis_target":"M6-2-u3-X06"},{"t":"도윤 — 「두 수를 모두 분모가 10인 분수로 바꾸자.」","mis":"M6-2-u3-X19"},{"t":"수아 — 「두 수의 소수점을 똑같이 한 칸씩 옮겨도 돼.」","mis":"M6-2-u3-X19"},{"t":"지호 — 「두 수에 똑같이 10을 곱하면 84 ÷ 21이야.」","mis":"M6-2-u3-X19"}],"explanation":["분수로 바꾸든, 소수점을 옮기든, 10을 곱하든 두 수를 똑같이 바꾸는 방법이에요.","한 수만 분수로 바꾸면 분자끼리 나눌 수 없어요.","하린이는 한 수만 분수로 바꾸었어요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7의 계산 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「4.9는 ⟨49/10⟩, 0.7은 ⟨7/100⟩로 바꾸면 돼.」","correct":true,"mis_target":"M6-2-u3-X05"},{"t":"서아 — 「두 수를 분모가 10인 분수로 바꾸면 49 ÷ 7이야.」","mis":"M6-2-u3-X19"},{"t":"도윤 — 「두 수에 똑같이 10을 곱해도 돼.」","mis":"M6-2-u3-X19"},{"t":"하린 — 「몫은 7이 될 거야.」","mis":"M6-2-u3-X19"}],"explanation":["0.7은 ⟨7/10⟩이에요.","분모가 같아야 분자끼리 나눌 수 있어요.","민준이는 분모를 서로 다르게 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#4','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'sa','auto','15 ÷ 3 = 5예요. 이것을 이용하여 1.5 ÷ 0.3의 몫을 구하면 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C1","difficulty":3,"kind":"sa","stem":"15 ÷ 3 = 5예요. 이것을 이용하여 1.5 ÷ 0.3의 몫을 구하면 얼마인가요?","answer":["5"],"explanation":["1.5 ÷ 0.3은 15 ÷ 3의 두 수를 똑같이 10으로 나눈 식이에요.","두 수를 똑같이 바꾸면 몫은 그대로예요.","그래서 1.5 ÷ 0.3의 몫도 5예요."],"variant_rule":{"alt":[{"stem":"28 ÷ 7 = 4예요. 이것을 이용하여 2.8 ÷ 0.7의 몫을 구하면 얼마인가요?","answer":["4"],"explanation":["2.8 ÷ 0.7은 28 ÷ 7의 두 수를 똑같이 10으로 나눈 식이에요.","두 수를 똑같이 바꾸면 몫은 그대로예요.","그래서 2.8 ÷ 0.7의 몫도 4예요."]},{"stem":"48 ÷ 6 = 8이에요. 이것을 이용하여 0.48 ÷ 0.06의 몫을 구하면 얼마인가요?","answer":["8"],"explanation":["0.48 ÷ 0.06은 48 ÷ 6의 두 수를 똑같이 100으로 나눈 식이에요.","두 수를 똑같이 바꾸면 몫은 그대로예요.","그래서 0.48 ÷ 0.06의 몫도 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#5','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','다음 중 몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":5,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"다음 중 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 나누어지는 수만 바뀌어 몫이 8.1이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"7.2 ÷ 0.08","correct":true},{"t":"7.2 ÷ 0.8","mis":"M6-2-u3-X19"},{"t":"72 ÷ 8","mis":"M6-2-u3-X19"},{"t":"0.72 ÷ 0.08","mis":"M6-2-u3-X19"}],"explanation":["7.2 ÷ 0.8, 72 ÷ 8, 0.72 ÷ 0.08은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 9예요.","7.2 ÷ 0.08은 나누는 수만 작아져 몫이 90이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#6','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 빨간 화분의 싹이 노란 화분의 싹의 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":6,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 빨간 화분의 싹이 노란 화분의 싹의 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2.4에서 0.8을 한 번 빼 본다","correct":true},{"t":"cm를 mm로 바꾸어 24 ÷ 8을 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨24/10⟩ ÷ ⟨8/10⟩을 계산한다","mis":"M6-2-u3-X19"},{"t":"0.8을 몇 번 더하면 2.4가 되는지 센다","mis":"M6-2-u3-X19"}],"explanation":["몇 배인지는 2.4 ÷ 0.8로 구해요.","단위 바꾸기·분수로 바꾸기·몇 번 더하기는 모두 같은 생각이에요.","한 번 빼 보는 것은 차이를 구할 뿐 몇 배인지는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 엄마 범고래가 아기 범고래의 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"8.24에서 4.12를 한 번 빼 본다","correct":true},{"t":"m를 cm로 바꾸어 824 ÷ 412를 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨824/100⟩ ÷ ⟨412/100⟩를 계산한다","mis":"M6-2-u3-X19"},{"t":"4.12를 몇 번 더하면 8.24가 되는지 센다","mis":"M6-2-u3-X19"}],"explanation":["몇 배인지는 8.24 ÷ 4.12로 구해요.","단위 바꾸기·분수로 바꾸기·몇 번 더하기는 모두 같은 생각이에요.","한 번 빼 보는 것은 차이를 구할 뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#7','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',3,'sa','auto','⟨72/10⟩ ÷ ⟨6/10⟩은 분자끼리 나누어 72 ÷ 6이 돼요. 7.2 ÷ 0.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C2","difficulty":3,"kind":"sa","stem":"⟨72/10⟩ ÷ ⟨6/10⟩은 분자끼리 나누어 72 ÷ 6이 돼요. 7.2 ÷ 0.6의 몫은 얼마인가요?","answer":["12"],"explanation":["7.2 ÷ 0.6은 ⟨72/10⟩ ÷ ⟨6/10⟩과 같아요.","분모가 같으니 분자끼리 72 ÷ 6이에요.","몫은 12예요."],"variant_rule":{"alt":[{"stem":"⟨84/10⟩ ÷ ⟨7/10⟩은 분자끼리 나누어 84 ÷ 7이 돼요. 8.4 ÷ 0.7의 몫은 얼마인가요?","answer":["12"],"explanation":["8.4 ÷ 0.7은 ⟨84/10⟩ ÷ ⟨7/10⟩과 같아요.","분모가 같으니 분자끼리 84 ÷ 7이에요.","몫은 12예요."]},{"stem":"⟨91/10⟩ ÷ ⟨13/10⟩은 분자끼리 나누어 91 ÷ 13이 돼요. 9.1 ÷ 1.3의 몫은 얼마인가요?","answer":["7"],"explanation":["9.1 ÷ 1.3은 ⟨91/10⟩ ÷ ⟨13/10⟩과 같아요.","분모가 같으니 분자끼리 91 ÷ 13이에요.","몫은 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#8','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',4,'mc','auto','□ ÷ 0.4의 몫은 12 ÷ 4의 몫과 같아요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":8,"concept":"M6-2-u3-C1","difficulty":4,"kind":"mc","stem":"□ ÷ 0.4의 몫은 12 ÷ 4의 몫과 같아요. □에 알맞은 수는 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-2-u3-X01"},{"t":"0.12","mis":"M6-2-u3-X02"},{"t":"120","mis":"M6-2-u3-X02"}],"explanation":["12 ÷ 4의 두 수에 똑같이 0.1을 곱하면 1.2 ÷ 0.4예요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 □는 1.2예요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.07의 몫은 63 ÷ 7의 몫과 같아요. □에 알맞은 수는 얼마인가요?","options":[{"t":"0.63","correct":true},{"t":"63","mis":"M6-2-u3-X01"},{"t":"6.3","mis":"M6-2-u3-X02"},{"t":"0.063","mis":"M6-2-u3-X02"}],"explanation":["63 ÷ 7의 두 수에 똑같이 0.01을 곱하면 0.63 ÷ 0.07이에요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 □는 0.63이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#9','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',4,'essay','teacher','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 2.4 ÷ 0.8을 cm를 mm로 바꾸어 계산하고, 그렇게 바꾸어도 몫이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C1","difficulty":4,"kind":"essay","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. 2.4 ÷ 0.8을 cm를 mm로 바꾸어 계산하고, 그렇게 바꾸어도 몫이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 2.4 cm는 24 mm, 0.8 cm는 8 mm이므로 24 ÷ 8 = 3이다. 단위를 바꾸면 두 수가 똑같이 10배가 되는데, 두 수에 똑같은 수를 곱하면 몫은 그대로이므로 2.4 ÷ 0.8의 몫도 3이다.","scoring_points":["24 ÷ 8 = 3을 썼는가","두 수가 똑같이 10배가 되었음을 밝혔는가","두 수에 같은 수를 곱해도 몫은 그대로라는 까닭을 썼는가"]},"explanation":["2.4 cm는 24 mm, 0.8 cm는 8 mm예요.","두 수가 똑같이 10배가 되었어요.","그래서 몫은 그대로 — 24 ÷ 8 = 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L02_challenge#10','math',6,2,'u3','L02','g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',4,'essay','teacher','7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바꾸어 계산하고, 두 수를 왜 같은 분모로 바꾸어야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C2","difficulty":4,"kind":"essay","stem":"7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바꾸어 계산하고, 두 수를 왜 같은 분모로 바꾸어야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이므로 ⟨72/10⟩ ÷ ⟨6/10⟩ = 72 ÷ 6 = 12이다. 분모가 같아야 같은 크기의 조각 개수끼리 나눌 수 있어 분자끼리 나눌 수 있다.","scoring_points":["⟨72/10⟩ ÷ ⟨6/10⟩으로 바꾸었는가","72 ÷ 6 = 12를 구했는가","분모가 같아야 분자끼리 나눌 수 있다는 까닭을 썼는가"]},"explanation":["7.2는 ⟨72/10⟩, 0.6은 ⟨6/10⟩이에요.","분모가 같으면 분자끼리 72 ÷ 6이에요.","몫은 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#1','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.1이 정해요.","2.1이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.5가 정해요.","0.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"7.2 ÷ 0.6을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.6이 정해요.","0.6이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#2','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'mc','auto','8.4 ÷ 2.1에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":2,"concept":"M6-2-u3-C3","difficulty":1,"kind":"mc","stem":"8.4 ÷ 2.1에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"84 ÷ 21","correct":true},{"t":"8.4 ÷ 21","mis":"M6-2-u3-X01"},{"t":"84 ÷ 2.1","mis":"M6-2-u3-X01"},{"t":"840 ÷ 21","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.1이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 8.4도 똑같이 한 칸 옮겨요.","그래서 84 ÷ 21이 돼요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"36 ÷ 5","correct":true},{"t":"3.6 ÷ 5","mis":"M6-2-u3-X01"},{"t":"36 ÷ 0.5","mis":"M6-2-u3-X01"},{"t":"360 ÷ 5","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 0.5가 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 3.6도 똑같이 한 칸 옮겨요.","그래서 36 ÷ 5가 돼요."]},{"stem":"9.1 ÷ 1.3에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"91 ÷ 13","correct":true},{"t":"9.1 ÷ 13","mis":"M6-2-u3-X01"},{"t":"91 ÷ 1.3","mis":"M6-2-u3-X01"},{"t":"910 ÷ 13","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 1.3이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 9.1도 똑같이 한 칸 옮겨요.","그래서 91 ÷ 13이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#3','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','4.9 ÷ 0.7의 몫은 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"4.9 ÷ 0.7의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 0.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.9 ÷ 0.7은 49 ÷ 7이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","49 ÷ 7 = 7이에요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 2.1의 몫은 얼마인가요?","answer":["4"],"explanation":["나누는 수 2.1이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","8.4 ÷ 2.1은 84 ÷ 21이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","84 ÷ 21 = 4예요."]},{"stem":"5.6 ÷ 0.8의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 0.8이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.6 ÷ 0.8은 56 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","56 ÷ 8 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#4','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','7.2 ÷ 0.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"7.2 ÷ 0.6의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","7.2 ÷ 0.6은 72 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","72 ÷ 6 = 12예요."],"variant_rule":{"alt":[{"stem":"9.6 ÷ 0.8의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.8이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","9.6 ÷ 0.8은 96 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","96 ÷ 8 = 12예요."]},{"stem":"6.5 ÷ 0.5의 몫은 얼마인가요?","answer":["13"],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.5 ÷ 0.5는 65 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","65 ÷ 5 = 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#5','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5를 세로로 계산할 때 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":5,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5를 세로로 계산할 때 잘못된 것은 어느 것인가요?","options":[{"t":"3.6 ÷ 5로 바꾼다","correct":true},{"t":"36 ÷ 5로 바꾼다","mis":"M6-2-u3-X19"},{"t":"두 수의 소수점을 한 칸씩 옮긴다","mis":"M6-2-u3-X19"},{"t":"두 수에 똑같이 10을 곱한다","mis":"M6-2-u3-X19"}],"explanation":["나누는 수 0.5가 자연수가 되도록 한 칸 옮기면 5예요.","나누어지는 수 3.6도 똑같이 한 칸 옮겨 36이 돼요.","3.6 ÷ 5는 나누는 수만 옮긴 다른 나눗셈이에요."],"variant_rule":{"alt":[{"stem":"4.2 ÷ 0.6을 세로로 계산할 때 잘못된 것은 어느 것인가요?","options":[{"t":"4.2 ÷ 6으로 바꾼다","correct":true},{"t":"42 ÷ 6으로 바꾼다","mis":"M6-2-u3-X19"},{"t":"두 수의 소수점을 한 칸씩 옮긴다","mis":"M6-2-u3-X19"},{"t":"두 수에 똑같이 10을 곱한다","mis":"M6-2-u3-X19"}],"explanation":["0.6이 자연수가 되도록 한 칸 옮기면 6이에요.","4.2도 똑같이 한 칸 옮겨 42가 돼요.","4.2 ÷ 6은 나누는 수만 옮긴 다른 나눗셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#6','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5의 몫은 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"},{"t":"0.072","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.6 ÷ 0.5는 36 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."],"variant_rule":{"alt":[{"stem":"4.5 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.5 ÷ 0.6은 45 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]},{"stem":"6.3 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 1.4는 63 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#7','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','세로셈에서 몫의 소수점은 어디에서 위로 올려 찍나요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"세로셈에서 몫의 소수점은 어디에서 위로 올려 찍나요?","options":[{"t":"옮긴 소수점의 위치","correct":true},{"t":"나누어지는 수의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"나누는 수의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"몫의 맨 뒤","mis":"M6-2-u3-X04"}],"explanation":["두 수의 소수점을 옮기면 자연수의 나눗셈처럼 계산해요.","몫은 옮긴 나눗셈의 몫과 같아요.","그래서 몫의 소수점은 옮긴 소수점의 위치에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5를 36 ÷ 5로 바꾸어 세로로 계산했어요. 몫의 소수점은 어디에서 위로 올려 찍나요?","options":[{"t":"36의 소수점 자리(옮긴 자리)","correct":true},{"t":"3.6의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"0.5의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"몫의 맨 뒤","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5와 36 ÷ 5는 몫이 같아요.","그래서 옮긴 자리를 기준으로 계산해요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#8','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'ox','auto','8.4 ÷ 2.1과 84 ÷ 21의 몫은 같아요.',ARRAY['M6-2-u3-X01']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":2,"kind":"ox","stem":"8.4 ÷ 2.1과 84 ÷ 21의 몫은 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 10을 곱한 사이이기 때문에","correct":true},{"t":"나누어지는 수만 10배가 되었기 때문에","mis":"M6-2-u3-X01"}],"mis":"M6-2-u3-X01","explanation":["8.4와 2.1의 소수점을 똑같이 한 칸 옮기면 84와 21이에요.","두 수에 똑같이 10을 곱했어요.","그래서 몫은 4로 같아요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6과 72 ÷ 6의 몫은 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 10을 곱한 사이이기 때문에","correct":true},{"t":"나누는 수만 10배가 되었기 때문에","mis":"M6-2-u3-X01"}],"explanation":["7.2와 0.6의 소수점을 똑같이 한 칸 옮기면 72와 6이에요.","두 수에 똑같이 10을 곱했어요.","그래서 몫은 12로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#9','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'sa','auto','분홍색 리본 4.8 m를 0.6 m씩 잘라 축하 장식을 만들어요. 리본은 몇 도막이 되나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C3","difficulty":2,"kind":"sa","stem":"분홍색 리본 4.8 m를 0.6 m씩 잘라 축하 장식을 만들어요. 리본은 몇 도막이 되나요?","answer":["8"],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.8 ÷ 0.6은 48 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","48 ÷ 6 = 8이에요."],"variant_rule":{"alt":[{"stem":"분홍색 리본 6.3 m를 0.7 m씩 잘라 축하 장식을 만들어요. 리본은 몇 도막이 되나요?","answer":["9"],"explanation":["나누는 수 0.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 0.7은 63 ÷ 7이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","63 ÷ 7 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_basic#10','math',6,2,'u3','L03','g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4.9 ÷ 0.7","r":"7"},{"l":"3.6 ÷ 0.5","r":"7.2"},{"l":"19.2 ÷ 2.4","r":"8"}],"mis":"M6-2-u3-X03","explanation":["4.9 ÷ 0.7 = 49 ÷ 7 = 7이에요.","3.6 ÷ 0.5 = 36 ÷ 5 = 7.2예요.","19.2 ÷ 2.4 = 192 ÷ 24 = 8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"7.2 ÷ 0.6","r":"12"},{"l":"4.5 ÷ 0.6","r":"7.5"},{"l":"2.7 ÷ 0.9","r":"3"}],"explanation":["7.2 ÷ 0.6 = 72 ÷ 6 = 12예요.","4.5 ÷ 0.6 = 45 ÷ 6 = 7.5예요.","2.7 ÷ 0.9 = 27 ÷ 9 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#1','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',2,'sa','auto','24.5 ÷ 3.5의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C3","difficulty":2,"kind":"sa","stem":"24.5 ÷ 3.5의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 3.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","24.5 ÷ 3.5는 245 ÷ 35가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","245 ÷ 35 = 7이에요."],"variant_rule":{"alt":[{"stem":"19.2 ÷ 2.4의 몫은 얼마인가요?","answer":["8"],"explanation":["나누는 수 2.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","19.2 ÷ 2.4는 192 ÷ 24가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","192 ÷ 24 = 8이에요."]},{"stem":"28.8 ÷ 3.6의 몫은 얼마인가요?","answer":["8"],"explanation":["나누는 수 3.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","28.8 ÷ 3.6은 288 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","288 ÷ 36 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#2','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',2,'mc','auto','5.1 ÷ 0.6의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":2,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"5.1 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"8.5","correct":true},{"t":"0.85","mis":"M6-2-u3-X03"},{"t":"85","mis":"M6-2-u3-X04"},{"t":"0.085","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.1 ÷ 0.6은 51 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 8.5예요."],"variant_rule":{"alt":[{"stem":"6.3 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 1.4는 63 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]},{"stem":"2.7 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.7 ÷ 0.6은 27 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#3','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02','M6-2-u3-X04']::text[],true,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5는 36 ÷ 5 = 7.2예요.","0.72는 7.2보다 10배 작은 수예요.","몫의 소수점을 옮기기 전 자리에서 찍으면 이렇게 돼요."],"variant_rule":{"alt":[{"stem":"4.5 ÷ 0.6의 몫을 0.75라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["4.5 ÷ 0.6은 45 ÷ 6 = 7.5예요.","0.75는 7.5보다 10배 작은 수예요.","몫의 소수점을 옮기기 전 자리에서 찍으면 이렇게 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#4','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','몫을 먼저 어림해요. 8.4 ÷ 2.1의 몫과 가장 가까운 수는 어느 것인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":4,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"몫을 먼저 어림해요. 8.4 ÷ 2.1의 몫과 가장 가까운 수는 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"0.4","mis":"M6-2-u3-X03"},{"t":"40","mis":"M6-2-u3-X04"},{"t":"0.04","mis":"M6-2-u3-X03"}],"explanation":["2.1을 네 번 더하면 8.4예요.","그래서 몫은 4쯤이에요.","어림한 값과 계산 결과를 견주면 소수점 자리 실수를 잡을 수 있어요."],"variant_rule":{"alt":[{"stem":"몫을 먼저 어림해요. 6.3 ÷ 0.9의 몫과 가장 가까운 수는 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"0.7","mis":"M6-2-u3-X03"},{"t":"70","mis":"M6-2-u3-X04"},{"t":"0.07","mis":"M6-2-u3-X03"}],"explanation":["0.9를 일곱 번 더하면 6.3이에요.","그래서 몫은 7쯤이에요.","어림값과 견주어 자리 실수를 잡아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#5','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','4.9 ÷ 0.7과 몫이 같은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":5,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"4.9 ÷ 0.7과 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"49 ÷ 7","correct":true},{"t":"4.9 ÷ 7","mis":"M6-2-u3-X01"},{"t":"49 ÷ 0.7","mis":"M6-2-u3-X01"},{"t":"490 ÷ 7","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","4.9 ÷ 0.7의 두 수에 똑같이 10을 곱하면 49 ÷ 7이에요.","한 수만 바꾼 식은 몫이 달라요."],"variant_rule":{"alt":[{"stem":"6.3 ÷ 0.9와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"63 ÷ 9","correct":true},{"t":"6.3 ÷ 9","mis":"M6-2-u3-X01"},{"t":"63 ÷ 0.9","mis":"M6-2-u3-X01"},{"t":"630 ÷ 9","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","6.3 ÷ 0.9의 두 수에 똑같이 10을 곱하면 63 ÷ 9예요.","한 수만 바꾼 식은 몫이 달라요."]},{"stem":"7.2 ÷ 0.8과 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"72 ÷ 8","correct":true},{"t":"7.2 ÷ 8","mis":"M6-2-u3-X01"},{"t":"72 ÷ 0.8","mis":"M6-2-u3-X01"},{"t":"720 ÷ 8","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","7.2 ÷ 0.8의 두 수에 똑같이 10을 곱하면 72 ÷ 8이에요.","한 수만 바꾼 식은 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#6','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"4.8 ÷ 0.4","correct":true},{"t":"4.8 ÷ 0.8","mis":"M6-2-u3-X19"},{"t":"4.8 ÷ 1.2","mis":"M6-2-u3-X19"},{"t":"4.8 ÷ 1.6","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","4.8 ÷ 0.4 = 12, 4.8 ÷ 0.8 = 6, 4.8 ÷ 1.2 = 4, 4.8 ÷ 1.6 = 3이에요.","그래서 4.8 ÷ 0.4가 가장 커요."],"variant_rule":{"alt":[{"stem":"몫이 가장 작은 것은 어느 것인가요?","options":[{"t":"7.2 ÷ 2.4","correct":true},{"t":"7.2 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"7.2 ÷ 0.8","mis":"M6-2-u3-X19"},{"t":"7.2 ÷ 1.2","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","7.2 ÷ 0.6 = 12, 7.2 ÷ 0.8 = 9, 7.2 ÷ 1.2 = 6, 7.2 ÷ 2.4 = 3이에요.","그래서 7.2 ÷ 2.4가 가장 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#7','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','빨간 끈은 6.3 m, 파란 끈은 1.4 m예요. 빨간 끈의 길이는 파란 끈의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"빨간 끈은 6.3 m, 파란 끈은 1.4 m예요. 빨간 끈의 길이는 파란 끈의 몇 배인가요?","options":[{"t":"4.5배","correct":true},{"t":"0.45배","mis":"M6-2-u3-X03"},{"t":"45배","mis":"M6-2-u3-X04"},{"t":"4.9배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 6.3 ÷ 1.4로 구해요.","두 수의 소수점을 한 칸씩 옮기면 63 ÷ 14예요.","63 ÷ 14 = 4.5 — 4.5배예요."],"variant_rule":{"alt":[{"stem":"물통 ㉮에는 물이 8.1 L, 물통 ㉯에는 1.8 L 들어 있어요. ㉮의 물은 ㉯의 몇 배인가요?","options":[{"t":"4.5배","correct":true},{"t":"0.45배","mis":"M6-2-u3-X03"},{"t":"45배","mis":"M6-2-u3-X04"},{"t":"6.3배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 8.1 ÷ 1.8로 구해요.","81 ÷ 18로 바꾸어 계산해요.","81 ÷ 18 = 4.5 — 4.5배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#8','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',4,'mc','auto','□ ÷ 0.6 = 12예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X17']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":4,"kind":"mc","stem":"□ ÷ 0.6 = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"},{"t":"20","mis":"M6-2-u3-X17"}],"explanation":["□ ÷ 0.6 = 12이면 □ = 12 × 0.6이에요.","12 × 0.6 = 7.2예요.","7.2 ÷ 0.6 = 72 ÷ 6 = 12로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.5 = 7.2예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"0.36","mis":"M6-2-u3-X03"},{"t":"36","mis":"M6-2-u3-X04"},{"t":"14.4","mis":"M6-2-u3-X17"}],"explanation":["□ = 7.2 × 0.5예요.","7.2 × 0.5 = 3.6이에요.","3.6 ÷ 0.5 = 36 ÷ 5 = 7.2로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#9','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',4,'essay','teacher','3.6 ÷ 0.5를 세로로 계산하는 과정을 소수점 옮기기와 몫의 소수점 찍기를 넣어 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C3","difficulty":4,"kind":"essay","stem":"3.6 ÷ 0.5를 세로로 계산하는 과정을 소수점 옮기기와 몫의 소수점 찍기를 넣어 차례대로 설명해 보세요.","answer_guide":{"answer":"예: 나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨 36 ÷ 5로 만든다. 36 ÷ 5는 나누어떨어지지 않으므로 0을 내려 계산하면 72가 되고, 몫의 소수점은 옮긴 소수점의 위치에서 올려 찍어 7.2이다.","scoring_points":["두 수의 소수점을 똑같이 한 칸 옮겼는가","0을 내려 계산했는가","몫의 소수점을 옮긴 자리에서 찍어 7.2를 구했는가"]},"explanation":["두 수를 한 칸씩 옮기면 36 ÷ 5예요.","나누어떨어지지 않으면 0을 내려 계산해요.","몫의 소수점은 옮긴 자리에서 — 7.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L03_challenge#10','math',6,2,'u3','L03','g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',4,'essay','teacher','6.3 ÷ 1.4의 몫을 먼저 어림한 뒤 계산하고, 어림한 값과 계산 결과를 견주어 몫의 소수점이 바른지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":4,"kind":"essay","stem":"6.3 ÷ 1.4의 몫을 먼저 어림한 뒤 계산하고, 어림한 값과 계산 결과를 견주어 몫의 소수점이 바른지 설명해 보세요.","answer_guide":{"answer":"예: 1.4를 네 번 더하면 5.6, 다섯 번 더하면 7이므로 몫은 4와 5 사이로 어림한다. 63 ÷ 14 = 4.5이고 어림한 범위 안에 있으므로 소수점 자리가 바르다(0.45나 45였다면 어림과 맞지 않는다).","scoring_points":["몫을 4와 5 사이(또는 4쯤·5쯤)로 어림했는가","4.5를 바르게 구했는가","어림값과 견주어 소수점이 바름을 밝혔는가"]},"explanation":["1.4 × 4 = 5.6, 1.4 × 5 = 7이에요.","몫은 4와 5 사이 — 계산하면 4.5예요.","어림과 맞으니 소수점 자리가 바르게 찍혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#1','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'sa','auto','2.24 ÷ 0.08을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"2.24 ÷ 0.08을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.08이 정해요.","0.08이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.16을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.16이 정해요.","0.16이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]},{"stem":"6.54 ÷ 0.06을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.06이 정해요.","0.06이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#2','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'sa','auto','엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 8.24 m는 824 cm, 4.12 m는 412 cm예요. 엄마 범고래의 몸길이는 아기 범고래의 몇 배인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 8.24 m는 824 cm, 4.12 m는 412 cm예요. 엄마 범고래의 몸길이는 아기 범고래의 몇 배인가요?","answer":["2"],"explanation":["몇 배인지는 8.24 ÷ 4.12로 구해요.","m를 cm로 바꾸면 824 ÷ 412예요.","412를 두 번 더하면 824 — 2배예요."],"variant_rule":{"alt":[{"stem":"큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. 1.35 m는 135 cm, 0.45 m는 45 cm예요. 큰 상자의 높이는 작은 상자의 몇 배인가요?","answer":["3"],"explanation":["몇 배인지는 1.35 ÷ 0.45로 구해요.","m를 cm로 바꾸면 135 ÷ 45예요.","135 ÷ 45 = 3 — 3배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#3','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'mc','auto','2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C4","difficulty":1,"kind":"mc","stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨56/100⟩ ÷ ⟨16/100⟩","correct":true},{"t":"⟨56/100⟩ ÷ 0.16","mis":"M6-2-u3-X06"},{"t":"⟨56/100⟩ ÷ ⟨16/10⟩","mis":"M6-2-u3-X05"},{"t":"0.56 ÷ ⟨16/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.56은 ⟨56/100⟩, 0.16은 ⟨16/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨56/100⟩ ÷ ⟨16/100⟩이에요."]},{"stem":"1.92 ÷ 0.04를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨192/100⟩ ÷ ⟨4/100⟩","correct":true},{"t":"⟨192/100⟩ ÷ 0.04","mis":"M6-2-u3-X06"},{"t":"⟨192/100⟩ ÷ ⟨4/10⟩","mis":"M6-2-u3-X05"},{"t":"1.92 ÷ ⟨4/100⟩","mis":"M6-2-u3-X06"}],"explanation":["1.92는 ⟨192/100⟩, 0.04는 ⟨4/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨192/100⟩ ÷ ⟨4/100⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#4','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'sa','auto','2.24 ÷ 0.08의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"2.24 ÷ 0.08의 몫은 얼마인가요?","answer":["28"],"explanation":["나누는 수 0.08이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","2.24 ÷ 0.08은 224 ÷ 8이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","224 ÷ 8 = 28이에요."],"variant_rule":{"alt":[{"stem":"1.92 ÷ 0.04의 몫은 얼마인가요?","answer":["48"],"explanation":["나누는 수 0.04가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.92 ÷ 0.04는 192 ÷ 4가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","192 ÷ 4 = 48이에요."]},{"stem":"0.96 ÷ 0.32의 몫은 얼마인가요?","answer":["3"],"explanation":["나누는 수 0.32가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.96 ÷ 0.32는 96 ÷ 32가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","96 ÷ 32 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#5','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','0.56 ÷ 0.16의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":5,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"0.56 ÷ 0.16의 몫은 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"0.35","mis":"M6-2-u3-X03"},{"t":"35","mis":"M6-2-u3-X04"},{"t":"0.035","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.16이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.56 ÷ 0.16은 56 ÷ 16이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 3.5예요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14의 몫은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"0.55","mis":"M6-2-u3-X03"},{"t":"55","mis":"M6-2-u3-X04"},{"t":"0.055","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.14가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.77 ÷ 0.14는 77 ÷ 14가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 5.5예요."]},{"stem":"1.17 ÷ 0.26의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.26이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.17 ÷ 0.26은 117 ÷ 26이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#6','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','6.54 ÷ 0.06의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":6,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"6.54 ÷ 0.06의 몫은 얼마인가요?","options":[{"t":"109","correct":true},{"t":"10.9","mis":"M6-2-u3-X03"},{"t":"1090","mis":"M6-2-u3-X04"},{"t":"1.09","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.54 ÷ 0.06은 654 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","654 ÷ 6 = 109예요."],"variant_rule":{"alt":[{"stem":"3.15 ÷ 0.05의 몫은 얼마인가요?","options":[{"t":"63","correct":true},{"t":"6.3","mis":"M6-2-u3-X03"},{"t":"630","mis":"M6-2-u3-X04"},{"t":"0.63","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.05가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","3.15 ÷ 0.05는 315 ÷ 5가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","315 ÷ 5 = 63이에요."]},{"stem":"8.28 ÷ 0.04의 몫은 얼마인가요?","options":[{"t":"207","correct":true},{"t":"20.7","mis":"M6-2-u3-X03"},{"t":"2070","mis":"M6-2-u3-X04"},{"t":"2.07","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.04가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.28 ÷ 0.04는 828 ÷ 4가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","828 ÷ 4 = 207이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#7','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','소수의 나눗셈에서 소수점을 옮기는 칸수는 무엇이 정하나요?',ARRAY['M6-2-u3-X02']::text[],true,'{"seq":7,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"소수의 나눗셈에서 소수점을 옮기는 칸수는 무엇이 정하나요?","options":[{"t":"나누는 수의 소수 자리 수","correct":true},{"t":"나누어지는 수의 소수 자리 수","mis":"M6-2-u3-X02"},{"t":"몫의 자리 수","mis":"M6-2-u3-X02"},{"t":"언제나 한 칸","mis":"M6-2-u3-X02"}],"explanation":["나누는 수가 자연수가 되어야 자연수의 나눗셈처럼 계산할 수 있어요.","0.08이 자연수가 되려면 두 칸을 옮겨야 해요.","그래서 칸수는 나누는 수의 소수 자리 수가 정해요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08에서 두 칸씩 옮기는 까닭은 무엇인가요?","options":[{"t":"0.08이 자연수가 되려면 두 칸 옮겨야 해서","correct":true},{"t":"2.24가 소수 두 자리 수라서","mis":"M6-2-u3-X02"},{"t":"몫이 두 자리 수라서","mis":"M6-2-u3-X02"},{"t":"언제나 두 칸씩 옮기기 때문에","mis":"M6-2-u3-X02"}],"explanation":["옮기는 칸수는 나누는 수가 정해요.","0.08은 두 칸 옮겨야 8이 돼요.","그래서 2.24도 두 칸 옮겨 224 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#8','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":8,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"824 ÷ 412","correct":true},{"t":"824 ÷ 4.12","mis":"M6-2-u3-X18"},{"t":"8.24 ÷ 412","mis":"M6-2-u3-X18"},{"t":"412 ÷ 824","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","8.24 m는 824 cm, 4.12 m는 412 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 824 ÷ 412예요."],"variant_rule":{"alt":[{"stem":"큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"135 ÷ 45","correct":true},{"t":"135 ÷ 0.45","mis":"M6-2-u3-X18"},{"t":"1.35 ÷ 45","mis":"M6-2-u3-X18"},{"t":"45 ÷ 135","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","1.35 m는 135 cm, 0.45 m는 45 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 135 ÷ 45예요."]},{"stem":"긴 막대의 길이는 2.56 m, 짧은 막대의 길이는 0.32 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"256 ÷ 32","correct":true},{"t":"256 ÷ 0.32","mis":"M6-2-u3-X18"},{"t":"2.56 ÷ 32","mis":"M6-2-u3-X18"},{"t":"32 ÷ 256","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","2.56 m는 256 cm, 0.32 m는 32 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 256 ÷ 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_basic#9','math',6,2,'u3','L04','g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','2.24 ÷ 0.08을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":9,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"2.24 ÷ 0.08을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"224 ÷ 8","correct":true},{"t":"224 ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"2.24 ÷ 8","mis":"M6-2-u3-X01"},{"t":"224 ÷ 80","mis":"M6-2-u3-X05"}],"explanation":["2.24 = ⟨224/100⟩, 0.08 = ⟨8/100⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 224 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.14를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"56 ÷ 14","correct":true},{"t":"56 ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"0.56 ÷ 14","mis":"M6-2-u3-X01"},{"t":"56 ÷ 140","mis":"M6-2-u3-X05"}],"explanation":["0.56 = ⟨56/100⟩, 0.14 = ⟨14/100⟩예요.","분모가 같으니 분자끼리 나눠요.","그래서 56 ÷ 14예요."]},{"stem":"3.24 ÷ 0.36을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"324 ÷ 36","correct":true},{"t":"324 ÷ 0.36","mis":"M6-2-u3-X06"},{"t":"3.24 ÷ 36","mis":"M6-2-u3-X01"},{"t":"324 ÷ 360","mis":"M6-2-u3-X05"}],"explanation":["3.24 = ⟨324/100⟩, 0.36 = ⟨36/100⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 324 ÷ 36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
