INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#2','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',2,'sa','auto','6.3 ÷ 0.42의 몫은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":2,"kind":"sa","stem":"6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."]},{"stem":"7.2 ÷ 0.24의 몫은 얼마인가요?","answer":["30"],"explanation":["나누는 수 0.24가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","7.2 ÷ 0.24는 720 ÷ 24가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","720 ÷ 24 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#3','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','0.56 ÷ 0.16의 몫을 0.35라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X02','M6-2-u3-X01','M6-2-u3-X04']::text[],true,'{"seq":3,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.56 ÷ 0.16의 몫을 0.35라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 자리에서 찍어서","correct":true},{"t":"두 수를 한 칸씩만 옮겨서","mis":"M6-2-u3-X02"},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["0.56 ÷ 0.16 = 56 ÷ 16 = 3.5예요.","0.35는 3.5보다 10배 작아요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14의 몫을 55라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 빠뜨려서","correct":true},{"t":"두 수를 한 칸씩만 옮겨서","mis":"M6-2-u3-X02"},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 옮기기 전 자리에서 찍어서","mis":"M6-2-u3-X03"}],"explanation":["0.77 ÷ 0.14 = 77 ÷ 14 = 5.5예요.","55는 5.5보다 10배 커요.","몫의 소수점을 빠뜨리면 이렇게 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#4','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','몫이 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"몫이 다른 하나는 어느 것인가요?","options":[{"t":"2.24 ÷ 0.8","correct":true},{"t":"2.24 ÷ 0.08","mis":"M6-2-u3-X19"},{"t":"224 ÷ 8","mis":"M6-2-u3-X19"},{"t":"22.4 ÷ 0.8","mis":"M6-2-u3-X19"}],"explanation":["2.24 ÷ 0.08, 224 ÷ 8, 22.4 ÷ 0.8은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 28이에요.","2.24 ÷ 0.8은 몫이 2.8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 다른 하나는 어느 것인가요?","options":[{"t":"0.56 ÷ 1.6","correct":true},{"t":"0.56 ÷ 0.16","mis":"M6-2-u3-X19"},{"t":"56 ÷ 16","mis":"M6-2-u3-X19"},{"t":"5.6 ÷ 1.6","mis":"M6-2-u3-X19"}],"explanation":["0.56 ÷ 0.16, 56 ÷ 16, 5.6 ÷ 1.6은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.5예요.","0.56 ÷ 1.6은 몫이 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#5','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":5,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/100⟩ ÷ ⟨14/100⟩","correct":true},{"t":"⟨77/100⟩ ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"⟨77/100⟩ ÷ ⟨14/10⟩","mis":"M6-2-u3-X05"},{"t":"0.77 ÷ ⟨14/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.77은 ⟨77/100⟩, 0.14는 ⟨14/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/100⟩ ÷ ⟨14/100⟩예요."],"variant_rule":{"alt":[{"stem":"6.54 ÷ 0.06을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨654/100⟩ ÷ ⟨6/100⟩","correct":true},{"t":"⟨654/100⟩ ÷ 0.06","mis":"M6-2-u3-X06"},{"t":"⟨654/100⟩ ÷ ⟨6/10⟩","mis":"M6-2-u3-X05"},{"t":"6.54 ÷ ⟨6/100⟩","mis":"M6-2-u3-X06"}],"explanation":["6.54는 ⟨654/100⟩, 0.06은 ⟨6/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨654/100⟩ ÷ ⟨6/100⟩이에요."]},{"stem":"0.96 ÷ 0.24를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨96/100⟩ ÷ ⟨24/100⟩","correct":true},{"t":"⟨96/100⟩ ÷ 0.24","mis":"M6-2-u3-X06"},{"t":"⟨96/100⟩ ÷ ⟨24/10⟩","mis":"M6-2-u3-X05"},{"t":"0.96 ÷ ⟨24/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.96은 ⟨96/100⟩, 0.24는 ⟨24/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨96/100⟩ ÷ ⟨24/100⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#6','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 아기 범고래의 몸길이는 엄마 범고래의 몇 배인가요?',ARRAY['M6-2-u3-X17','M6-2-u3-X04','M6-2-u3-X03']::text[],true,'{"seq":6,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 아기 범고래의 몸길이는 엄마 범고래의 몇 배인가요?","options":[{"t":"0.5배","correct":true},{"t":"2배","mis":"M6-2-u3-X17"},{"t":"5배","mis":"M6-2-u3-X04"},{"t":"0.05배","mis":"M6-2-u3-X03"}],"explanation":["아기 범고래가 앞 — 4.12 ÷ 8.24로 구해요.","두 칸씩 옮기면 412 ÷ 824예요.","412 ÷ 824 = 0.5 — 0.5배예요."],"variant_rule":{"alt":[{"stem":"큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. 작은 상자의 높이는 큰 상자의 몇 배인가요?","options":[{"t":"⟨1/3⟩배","correct":true},{"t":"3배","mis":"M6-2-u3-X17"},{"t":"0.3배","mis":"M6-2-u3-X03"},{"t":"30배","mis":"M6-2-u3-X04"}],"explanation":["작은 상자가 앞 — 0.45 ÷ 1.35로 구해요.","두 칸씩 옮기면 45 ÷ 135예요.","45 ÷ 135 = ⟨1/3⟩ — ⟨1/3⟩배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#7','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','6.54 ÷ 0.06의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"6.54 ÷ 0.06의 몫은 얼마인가요?","options":[{"t":"109","correct":true},{"t":"10.9","mis":"M6-2-u3-X03"},{"t":"1.09","mis":"M6-2-u3-X03"},{"t":"1090","mis":"M6-2-u3-X04"}],"explanation":["0.06이 자연수가 되려면 두 칸 옮겨요.","6.54도 두 칸 옮기면 654 ÷ 6이에요.","654 ÷ 6 = 109예요 — 중간 자리의 0을 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"4.28 ÷ 0.04의 몫은 얼마인가요?","options":[{"t":"107","correct":true},{"t":"10.7","mis":"M6-2-u3-X03"},{"t":"17","mis":"M6-2-u3-X20"},{"t":"1070","mis":"M6-2-u3-X04"}],"explanation":["0.04가 자연수가 되려면 두 칸 옮겨요.","4.28도 두 칸 옮기면 428 ÷ 4예요.","428 ÷ 4 = 107이에요 — 중간 자리의 0을 빠뜨리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#8','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',4,'mc','auto','□ ÷ 0.08 = 28이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X04','M6-2-u3-X03','M6-2-u3-X17']::text[],true,'{"seq":8,"concept":"M6-2-u3-C4","difficulty":4,"kind":"mc","stem":"□ ÷ 0.08 = 28이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2.24","correct":true},{"t":"22.4","mis":"M6-2-u3-X04"},{"t":"0.224","mis":"M6-2-u3-X03"},{"t":"350","mis":"M6-2-u3-X17"}],"explanation":["□ = 28 × 0.08이에요.","28 × 0.08 = 2.24예요.","2.24 ÷ 0.08 = 224 ÷ 8 = 28로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.14 = 5.5예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"0.77","correct":true},{"t":"7.7","mis":"M6-2-u3-X04"},{"t":"0.077","mis":"M6-2-u3-X03"},{"t":"39.28…","mis":"M6-2-u3-X17"}],"explanation":["□ = 5.5 × 0.14예요.","5.5 × 0.14 = 0.77이에요.","0.77 ÷ 0.14 = 77 ÷ 14 = 5.5로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#9','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',4,'essay','teacher','2.24 ÷ 0.08을 계산할 때 소수점을 두 칸씩 옮기는 까닭을 설명하고 몫을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C4","difficulty":4,"kind":"essay","stem":"2.24 ÷ 0.08을 계산할 때 소수점을 두 칸씩 옮기는 까닭을 설명하고 몫을 구해 보세요.","answer_guide":{"answer":"예: 소수점을 옮기는 칸수는 나누는 수가 정한다. 나누는 수 0.08이 자연수 8이 되려면 두 칸 옮겨야 하므로 2.24도 똑같이 두 칸 옮겨 224 ÷ 8 = 28이다.","scoring_points":["칸수는 나누는 수가 정함을 밝혔는가","0.08이 자연수가 되려면 두 칸임을 썼는가","224 ÷ 8 = 28을 구했는가"]},"explanation":["칸수는 나누는 수 0.08이 정해요.","0.08 → 8은 두 칸이에요.","224 ÷ 8 = 28이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L04_challenge#10','math',6,2,'u3','L04','g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',4,'essay','teacher','8.24 ÷ 4.12를 m를 cm로 바꾸는 방법과 분수로 바꾸는 방법 두 가지로 계산하고, 두 방법의 같은 점을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C4","difficulty":4,"kind":"essay","stem":"8.24 ÷ 4.12를 m를 cm로 바꾸는 방법과 분수로 바꾸는 방법 두 가지로 계산하고, 두 방법의 같은 점을 써 보세요.","answer_guide":{"answer":"예: 8.24 m = 824 cm, 4.12 m = 412 cm이므로 824 ÷ 412 = 2. 분수로 바꾸면 ⟨824/100⟩ ÷ ⟨412/100⟩ = 824 ÷ 412 = 2. 두 방법 모두 두 수를 똑같이 100배 하여 자연수의 나눗셈 824 ÷ 412로 바꾼다.","scoring_points":["단위를 바꾸어 824 ÷ 412 = 2를 구했는가","⟨824/100⟩ ÷ ⟨412/100⟩로 바꾸었는가","두 수를 똑같이 100배 한다는 같은 점을 썼는가"]},"explanation":["m → cm는 두 수를 100배 해요.","분수로 바꾸면 분모 100, 분자끼리 824 ÷ 412예요.","두 방법 모두 몫은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#1','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'sa','auto','주말농장에서 딴 방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담으려고 해요. 상자는 몇 개 필요한가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"주말농장에서 딴 방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담으려고 해요. 상자는 몇 개 필요한가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."],"variant_rule":{"alt":[{"stem":"주말농장에서 딴 방울토마토 7.2 kg을 한 상자에 0.24 kg씩 담으려고 해요. 상자는 몇 개 필요한가요?","answer":["30"],"explanation":["나누는 수 0.24가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","7.2 ÷ 0.24는 720 ÷ 24가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","720 ÷ 24 = 30이에요."]},{"stem":"주말농장에서 딴 방울토마토 4.2 kg을 한 상자에 0.35 kg씩 담으려고 해요. 상자는 몇 개 필요한가요?","answer":["12"],"explanation":["나누는 수 0.35가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.2 ÷ 0.35는 420 ÷ 35가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","420 ÷ 35 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#2','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'sa','auto','5.4 ÷ 0.45를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"5.4 ÷ 0.45를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.45가 정해요.","0.45가 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"8.64 ÷ 2.4를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.4가 정해요.","2.4가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"18.3 ÷ 0.3을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.3이 정해요.","0.3이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#3','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'mc','auto','5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":3,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"540","correct":true},{"t":"54","mis":"M6-2-u3-X07"},{"t":"5.40","mis":"M6-2-u3-X07"},{"t":"5400","mis":"M6-2-u3-X02"}],"explanation":["5.4의 소수점을 한 칸 옮기면 54예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 540이 돼요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.21에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"840","correct":true},{"t":"84","mis":"M6-2-u3-X07"},{"t":"8.40","mis":"M6-2-u3-X07"},{"t":"8400","mis":"M6-2-u3-X02"}],"explanation":["8.4의 소수점을 한 칸 옮기면 84예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 840이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#4','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'sa','auto','18.3 ÷ 0.3의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"18.3 ÷ 0.3의 몫은 얼마인가요?","answer":["61"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","18.3 ÷ 0.3은 183 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","183 ÷ 3 = 61이에요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."]},{"stem":"6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#5','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','8.64 ÷ 2.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"8.64 ÷ 2.4의 몫은 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"0.36","mis":"M6-2-u3-X03"},{"t":"36","mis":"M6-2-u3-X04"},{"t":"0.036","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 2.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","8.64 ÷ 2.4는 86.4 ÷ 24가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 3.6이에요."],"variant_rule":{"alt":[{"stem":"5.76 ÷ 3.2의 몫은 얼마인가요?","options":[{"t":"1.8","correct":true},{"t":"0.18","mis":"M6-2-u3-X03"},{"t":"18","mis":"M6-2-u3-X04"},{"t":"0.018","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 3.2가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.76 ÷ 3.2는 57.6 ÷ 32가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 1.8이에요."]},{"stem":"2.88 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"2.4","correct":true},{"t":"0.24","mis":"M6-2-u3-X03"},{"t":"24","mis":"M6-2-u3-X04"},{"t":"0.024","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.2가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.88 ÷ 1.2는 28.8 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#6','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','2.55 ÷ 1.5의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":6,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"2.55 ÷ 1.5의 몫은 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"0.17","mis":"M6-2-u3-X03"},{"t":"17","mis":"M6-2-u3-X04"},{"t":"0.017","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.55 ÷ 1.5는 25.5 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 1.7이에요."],"variant_rule":{"alt":[{"stem":"3.08 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"2.2","correct":true},{"t":"0.22","mis":"M6-2-u3-X03"},{"t":"22","mis":"M6-2-u3-X04"},{"t":"0.022","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.08 ÷ 1.4는 30.8 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.2예요."]},{"stem":"9.45 ÷ 2.7의 몫은 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"0.35","mis":"M6-2-u3-X03"},{"t":"35","mis":"M6-2-u3-X04"},{"t":"0.035","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 2.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","9.45 ÷ 2.7은 94.5 ÷ 27이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 3.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#7','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','8.64 ÷ 2.4에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":7,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"8.64 ÷ 2.4에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"86.4 ÷ 24","correct":true},{"t":"8.64 ÷ 24","mis":"M6-2-u3-X01"},{"t":"86.4 ÷ 2.4","mis":"M6-2-u3-X01"},{"t":"864 ÷ 24","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.4가 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 8.64도 똑같이 한 칸 옮겨요.","그래서 86.4 ÷ 24가 돼요."],"variant_rule":{"alt":[{"stem":"5.76 ÷ 3.2에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"57.6 ÷ 32","correct":true},{"t":"5.76 ÷ 32","mis":"M6-2-u3-X01"},{"t":"57.6 ÷ 3.2","mis":"M6-2-u3-X01"},{"t":"576 ÷ 32","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 3.2가 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 5.76도 똑같이 한 칸 옮겨요.","그래서 57.6 ÷ 32가 돼요."]},{"stem":"9.45 ÷ 2.7에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"94.5 ÷ 27","correct":true},{"t":"9.45 ÷ 27","mis":"M6-2-u3-X01"},{"t":"94.5 ÷ 2.7","mis":"M6-2-u3-X01"},{"t":"945 ÷ 27","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.7이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 9.45도 똑같이 한 칸 옮겨요.","그래서 94.5 ÷ 27이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#8','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','빵을 만드는 데 밀가루 1.18 kg과 설탕 0.2 kg이 필요해요. 밀가루의 무게는 설탕의 무게의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X20']::text[],true,'{"seq":8,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"빵을 만드는 데 밀가루 1.18 kg과 설탕 0.2 kg이 필요해요. 밀가루의 무게는 설탕의 무게의 몇 배인가요?","options":[{"t":"5.9배","correct":true},{"t":"0.59배","mis":"M6-2-u3-X03"},{"t":"59배","mis":"M6-2-u3-X04"},{"t":"5.09배","mis":"M6-2-u3-X20"}],"explanation":["몇 배인지는 1.18 ÷ 0.2로 구해요.","0.2가 자연수가 되도록 한 칸 옮기면 11.8 ÷ 2예요.","11.8 ÷ 2 = 5.9 — 5.9배예요."],"variant_rule":{"alt":[{"stem":"떡을 만드는 데 쌀가루 2.34 kg과 설탕 0.6 kg이 필요해요. 쌀가루의 무게는 설탕의 무게의 몇 배인가요?","options":[{"t":"3.9배","correct":true},{"t":"0.39배","mis":"M6-2-u3-X03"},{"t":"39배","mis":"M6-2-u3-X04"},{"t":"3.09배","mis":"M6-2-u3-X20"}],"explanation":["몇 배인지는 2.34 ÷ 0.6으로 구해요.","한 칸 옮기면 23.4 ÷ 6이에요.","23.4 ÷ 6 = 3.9 — 3.9배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#9','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'ox','auto','8.64 ÷ 2.4는 86.4 ÷ 24로 계산해도, 864 ÷ 240으로 계산해도 몫이 같아요.',ARRAY['M6-2-u3-X02']::text[],true,'{"seq":9,"concept":"M6-2-u3-C5","difficulty":2,"kind":"ox","stem":"8.64 ÷ 2.4는 86.4 ÷ 24로 계산해도, 864 ÷ 240으로 계산해도 몫이 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 10이나 100을 곱한 사이이기 때문에","correct":true},{"t":"옮긴 칸수가 다르면 몫도 달라지기 때문에","mis":"M6-2-u3-X02"}],"mis":"M6-2-u3-X02","explanation":["86.4 ÷ 24는 두 수에 10을, 864 ÷ 240은 100을 곱한 식이에요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","두 식의 몫은 모두 3.6이에요."],"variant_rule":{"alt":[{"stem":"5.76 ÷ 3.2는 57.6 ÷ 32로 계산해도, 576 ÷ 320으로 계산해도 몫이 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 10이나 100을 곱한 사이이기 때문에","correct":true},{"t":"옮긴 칸수가 다르면 몫도 달라지기 때문에","mis":"M6-2-u3-X02"}],"explanation":["57.6 ÷ 32는 두 수에 10을, 576 ÷ 320은 100을 곱한 식이에요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","두 식의 몫은 모두 1.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_basic#10','math',6,2,'u3','L05','g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',3,'mc','auto','5.4 ÷ 0.45를 54 ÷ 45로 바꾸어 계산한 친구가 있어요. 무엇을 잘못했나요?',ARRAY['M6-2-u3-X02','M6-2-u3-X01','M6-2-u3-X03']::text[],true,'{"seq":10,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"5.4 ÷ 0.45를 54 ÷ 45로 바꾸어 계산한 친구가 있어요. 무엇을 잘못했나요?","options":[{"t":"5.4를 두 칸 옮기면서 빈 자리를 0으로 채우지 않았다","correct":true},{"t":"0.45를 한 칸만 옮겼다","mis":"M6-2-u3-X02"},{"t":"5.4만 옮기고 0.45는 그대로 두었다","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 잘못 찍었다","mis":"M6-2-u3-X03"}],"explanation":["0.45를 두 칸 옮기면 45예요.","5.4도 두 칸 옮겨야 하는데 한 칸 옮기면 54, 두 칸이면 540이에요.","빈 자리 0을 채우지 않아 54 ÷ 45가 되었어요 — 바른 식은 540 ÷ 45 = 12예요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.21을 84 ÷ 21로 바꾸어 계산한 친구가 있어요. 무엇을 잘못했나요?","options":[{"t":"8.4를 두 칸 옮기면서 빈 자리를 0으로 채우지 않았다","correct":true},{"t":"0.21을 한 칸만 옮겼다","mis":"M6-2-u3-X02"},{"t":"8.4만 옮기고 0.21은 그대로 두었다","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 잘못 찍었다","mis":"M6-2-u3-X03"}],"explanation":["0.21을 두 칸 옮기면 21이에요.","8.4도 두 칸 옮기면 840이에요.","빈 자리 0을 채우지 않아 84 ÷ 21이 되었어요 — 바른 식은 840 ÷ 21 = 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#1','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',2,'sa','auto','8.4 ÷ 0.21의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."],"variant_rule":{"alt":[{"stem":"9.6 ÷ 0.32의 몫은 얼마인가요?","answer":["30"],"explanation":["나누는 수 0.32가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","9.6 ÷ 0.32는 960 ÷ 32가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","960 ÷ 32 = 30이에요."]},{"stem":"7.5 ÷ 0.25의 몫은 얼마인가요?","answer":["30"],"explanation":["나누는 수 0.25가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","7.5 ÷ 0.25는 750 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","750 ÷ 25 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#2','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',2,'mc','auto','3.08 ÷ 1.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":2,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"3.08 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"2.2","correct":true},{"t":"0.22","mis":"M6-2-u3-X03"},{"t":"22","mis":"M6-2-u3-X04"},{"t":"0.022","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.08 ÷ 1.4는 30.8 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.2예요."],"variant_rule":{"alt":[{"stem":"2.55 ÷ 1.5의 몫은 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"0.17","mis":"M6-2-u3-X03"},{"t":"17","mis":"M6-2-u3-X04"},{"t":"0.017","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.55 ÷ 1.5는 25.5 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 1.7이에요."]},{"stem":"4.32 ÷ 1.8의 몫은 얼마인가요?","options":[{"t":"2.4","correct":true},{"t":"0.24","mis":"M6-2-u3-X03"},{"t":"24","mis":"M6-2-u3-X04"},{"t":"0.024","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.8이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.32 ÷ 1.8은 43.2 ÷ 18이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#3','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":3,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"5.4 ÷ 0.45","correct":true},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"2.55 ÷ 1.5","mis":"M6-2-u3-X19"},{"t":"18.3 ÷ 3","mis":"M6-2-u3-X19"}],"explanation":["5.4 ÷ 0.45 = 12, 8.64 ÷ 2.4 = 3.6이에요.","2.55 ÷ 1.5 = 1.7, 18.3 ÷ 3 = 6.1이에요.","그래서 5.4 ÷ 0.45가 가장 커요."],"variant_rule":{"alt":[{"stem":"몫이 가장 작은 것은 어느 것인가요?","options":[{"t":"2.55 ÷ 1.5","correct":true},{"t":"5.4 ÷ 0.45","mis":"M6-2-u3-X19"},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"3.08 ÷ 1.4","mis":"M6-2-u3-X19"}],"explanation":["5.4 ÷ 0.45 = 12, 8.64 ÷ 2.4 = 3.6이에요.","3.08 ÷ 1.4 = 2.2, 2.55 ÷ 1.5 = 1.7이에요.","그래서 2.55 ÷ 1.5가 가장 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#4','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','8.64 ÷ 2.4를 계산하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":4,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"8.64 ÷ 2.4를 계산하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"86.4 ÷ 2.4로 바꾸어 계산한다","correct":true},{"t":"86.4 ÷ 24로 바꾸어 계산한다","mis":"M6-2-u3-X19"},{"t":"864 ÷ 240으로 바꾸어 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨864/100⟩ ÷ ⟨240/100⟩으로 바꾸어 계산한다","mis":"M6-2-u3-X19"}],"explanation":["두 수를 똑같이 10배 하면 86.4 ÷ 24, 100배 하면 864 ÷ 240이에요.","분수로 바꾸어도 두 수에 같은 수를 곱한 것과 같아요.","86.4 ÷ 2.4는 나누어지는 수만 10배 한 다른 식이에요."],"variant_rule":{"alt":[{"stem":"5.76 ÷ 3.2를 계산하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"57.6 ÷ 3.2로 바꾸어 계산한다","correct":true},{"t":"57.6 ÷ 32로 바꾸어 계산한다","mis":"M6-2-u3-X19"},{"t":"576 ÷ 320으로 바꾸어 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨576/100⟩ ÷ ⟨320/100⟩으로 바꾸어 계산한다","mis":"M6-2-u3-X19"}],"explanation":["두 수를 똑같이 10배 하면 57.6 ÷ 32, 100배 하면 576 ÷ 320이에요.","분수로 바꾸어도 두 수에 같은 수를 곱한 것과 같아요.","57.6 ÷ 3.2는 나누어지는 수만 10배 한 다른 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#5','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','방울토마토 6.3 kg을 한 상자에 0.45 kg씩 담았어요. 상자는 몇 개 필요한가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X20']::text[],true,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"방울토마토 6.3 kg을 한 상자에 0.45 kg씩 담았어요. 상자는 몇 개 필요한가요?","options":[{"t":"14개","correct":true},{"t":"1.4개","mis":"M6-2-u3-X03"},{"t":"140개","mis":"M6-2-u3-X04"},{"t":"16개","mis":"M6-2-u3-X20"}],"explanation":["6.3 ÷ 0.45를 계산해요.","두 칸씩 옮기면 630 ÷ 45예요 — 빈 자리는 0으로.","630 ÷ 45 = 14 — 14개예요."],"variant_rule":{"alt":[{"stem":"방울토마토 9.6 kg을 한 상자에 0.32 kg씩 담았어요. 상자는 몇 개 필요한가요?","options":[{"t":"30개","correct":true},{"t":"3개","mis":"M6-2-u3-X03"},{"t":"300개","mis":"M6-2-u3-X04"},{"t":"32개","mis":"M6-2-u3-X20"}],"explanation":["9.6 ÷ 0.32를 계산해요.","두 칸씩 옮기면 960 ÷ 32예요 — 빈 자리는 0으로.","960 ÷ 32 = 30 — 30개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#6','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C5","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"5.4 ÷ 0.45","r":"12"},{"l":"8.64 ÷ 2.4","r":"3.6"},{"l":"2.55 ÷ 1.5","r":"1.7"}],"mis":"M6-2-u3-X07","explanation":["5.4 ÷ 0.45 = 540 ÷ 45 = 12예요.","8.64 ÷ 2.4 = 86.4 ÷ 24 = 3.6이에요.","2.55 ÷ 1.5 = 25.5 ÷ 15 = 1.7이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"8.4 ÷ 0.21","r":"40"},{"l":"3.08 ÷ 1.4","r":"2.2"},{"l":"18.3 ÷ 0.3","r":"61"}],"explanation":["8.4 ÷ 0.21 = 840 ÷ 21 = 40이에요.","3.08 ÷ 1.4 = 30.8 ÷ 14 = 2.2예요.","18.3 ÷ 0.3 = 183 ÷ 3 = 61이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#7','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','9.15 ÷ 0.5 = 18.3이에요. 이어서 18.3 ÷ 0.3을 계산하면 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"9.15 ÷ 0.5 = 18.3이에요. 이어서 18.3 ÷ 0.3을 계산하면 얼마인가요?","options":[{"t":"61","correct":true},{"t":"6.1","mis":"M6-2-u3-X03"},{"t":"610","mis":"M6-2-u3-X04"},{"t":"0.61","mis":"M6-2-u3-X03"}],"explanation":["18.3 ÷ 0.3은 한 칸씩 옮겨 183 ÷ 3이에요.","183 ÷ 3 = 61이에요.","어림해 봐도 18 ÷ 0.3은 60쯤이라 61이 맞아요."],"variant_rule":{"alt":[{"stem":"4.8 ÷ 0.4 = 12예요. 이어서 12 ÷ 0.15를 계산하면 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M6-2-u3-X03"},{"t":"800","mis":"M6-2-u3-X04"},{"t":"0.8","mis":"M6-2-u3-X03"}],"explanation":["12 ÷ 0.15는 두 칸씩 옮겨 1200 ÷ 15예요.","1200 ÷ 15 = 80이에요.","빈 자리 0을 채워 1200으로 바꾸었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#8','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',4,'mc','auto','□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X02']::text[],true,'{"seq":8,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"0.54","mis":"M6-2-u3-X03"},{"t":"54","mis":"M6-2-u3-X04"},{"t":"540","mis":"M6-2-u3-X02"}],"explanation":["□ = 12 × 0.45예요.","12 × 0.45 = 5.4예요.","5.4 ÷ 0.45 = 540 ÷ 45 = 12로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 2.4 = 3.6이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.64","correct":true},{"t":"0.864","mis":"M6-2-u3-X03"},{"t":"86.4","mis":"M6-2-u3-X04"},{"t":"864","mis":"M6-2-u3-X02"}],"explanation":["□ = 3.6 × 2.4예요.","3.6 × 2.4 = 8.64예요.","8.64 ÷ 2.4 = 86.4 ÷ 24 = 3.6으로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#9','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',4,'essay','teacher','주말농장에서 딴 방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담으려고 해요. 상자가 몇 개 필요한지 어림한 뒤 계산하고, 5.4의 소수점을 옮길 때 주의할 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"주말농장에서 딴 방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담으려고 해요. 상자가 몇 개 필요한지 어림한 뒤 계산하고, 5.4의 소수점을 옮길 때 주의할 점을 써 보세요.","answer_guide":{"answer":"예: 0.45의 10배는 4.5이고 5.4는 4.5보다 조금 크므로 10개쯤으로 어림한다. 0.45가 자연수가 되도록 두 칸 옮기면 5.4도 두 칸 옮겨 540이 되고 540 ÷ 45 = 12개이다. 5.4를 두 칸 옮길 때 빈 자리를 0으로 채워야 한다.","scoring_points":["10개쯤으로 어림했는가","540 ÷ 45 = 12개를 구했는가","빈 자리를 0으로 채운다는 주의점을 썼는가"]},"explanation":["0.45 × 10 = 4.5라서 10개쯤이에요.","두 칸씩 옮기면 540 ÷ 45 = 12예요.","5.4를 두 칸 옮길 때 빈 자리는 0으로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L05_challenge#10','math',6,2,'u3','L05','g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',4,'essay','teacher','8.64 ÷ 2.4를 한 칸만 옮기는 방법과 두 칸 옮기는 방법으로 각각 계산하고, 몫이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"8.64 ÷ 2.4를 한 칸만 옮기는 방법과 두 칸 옮기는 방법으로 각각 계산하고, 몫이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 한 칸 옮기면 86.4 ÷ 24 = 3.6, 두 칸 옮기면 864 ÷ 240 = 3.6이다. 두 방법 모두 두 수에 똑같이 10 또는 100을 곱했기 때문에 몫이 같다.","scoring_points":["86.4 ÷ 24 = 3.6을 구했는가","864 ÷ 240 = 3.6을 구했는가","두 수에 같은 수를 곱해서라는 까닭을 썼는가"]},"explanation":["한 칸이면 86.4 ÷ 24예요.","두 칸이면 864 ÷ 240이에요.","두 수에 똑같은 수를 곱했으니 몫은 3.6으로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#1','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'sa','auto','직사각형 모양 태양 전지판의 넓이는 8 m², 세로는 1.6 m예요. 태양 전지판의 가로는 몇 m인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"직사각형 모양 태양 전지판의 넓이는 8 m², 세로는 1.6 m예요. 태양 전지판의 가로는 몇 m인가요?","answer":["5"],"explanation":["나누어지는 수 8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."],"variant_rule":{"alt":[{"stem":"직사각형 모양 태양 전지판의 넓이는 9 m², 세로는 1.8 m예요. 태양 전지판의 가로는 몇 m인가요?","answer":["5"],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.8은 90 ÷ 18이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","90 ÷ 18 = 5예요."]},{"stem":"직사각형 모양 태양 전지판의 넓이는 6 m², 세로는 1.5 m예요. 태양 전지판의 가로는 몇 m인가요?","answer":["4"],"explanation":["나누어지는 수 6은 6.0과 같아요 — 나누는 수 1.5가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","6 ÷ 1.5는 60 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","60 ÷ 15 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#2','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'mc','auto','8 ÷ 1.6에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?',ARRAY['M6-2-u3-X08','M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":2,"concept":"M6-2-u3-C6","difficulty":1,"kind":"mc","stem":"8 ÷ 1.6에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"80 ÷ 16","correct":true},{"t":"8 ÷ 16","mis":"M6-2-u3-X08"},{"t":"80 ÷ 1.6","mis":"M6-2-u3-X01"},{"t":"800 ÷ 16","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 1.6이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 8도 똑같이 한 칸 옮겨요 — 빈 자리는 0으로.","그래서 80 ÷ 16이 돼요."],"variant_rule":{"alt":[{"stem":"7 ÷ 1.75에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"700 ÷ 175","correct":true},{"t":"7 ÷ 175","mis":"M6-2-u3-X08"},{"t":"700 ÷ 1.75","mis":"M6-2-u3-X01"},{"t":"7000 ÷ 175","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 1.75가 자연수가 되려면 두 칸 옮겨야 해요.","나누어지는 수 7도 똑같이 두 칸 옮겨요 — 빈 자리는 0으로.","그래서 700 ÷ 175가 돼요."]},{"stem":"9 ÷ 0.6에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"90 ÷ 6","correct":true},{"t":"9 ÷ 6","mis":"M6-2-u3-X08"},{"t":"90 ÷ 0.6","mis":"M6-2-u3-X01"},{"t":"900 ÷ 6","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 0.6이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 9도 똑같이 한 칸 옮겨요 — 빈 자리는 0으로.","그래서 90 ÷ 6이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#3','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'sa','auto','7 ÷ 1.75의 몫은 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["나누어지는 수 7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."],"variant_rule":{"alt":[{"stem":"16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["나누어지는 수 16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."]},{"stem":"18 ÷ 3.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 18은 18.0과 같아요 — 나누는 수 3.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","18 ÷ 3.6은 180 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","180 ÷ 36 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#4','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'sa','auto','12 ÷ 0.8의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"12 ÷ 0.8의 몫은 얼마인가요?","answer":["15"],"explanation":["나누어지는 수 12는 12.0과 같아요 — 나누는 수 0.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","12 ÷ 0.8은 120 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","120 ÷ 8 = 15예요."],"variant_rule":{"alt":[{"stem":"21 ÷ 1.4의 몫은 얼마인가요?","answer":["15"],"explanation":["나누어지는 수 21은 21.0과 같아요 — 나누는 수 1.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","21 ÷ 1.4는 210 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","210 ÷ 14 = 15예요."]},{"stem":"9 ÷ 0.6의 몫은 얼마인가요?","answer":["15"],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 0.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 0.6은 90 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","90 ÷ 6 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#5','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'mc','auto','5 ÷ 0.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":5,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"5 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"12.5","correct":true},{"t":"1.25","mis":"M6-2-u3-X03"},{"t":"125","mis":"M6-2-u3-X04"},{"t":"0.125","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 5는 5.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","5 ÷ 0.4는 50 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 12.5예요."],"variant_rule":{"alt":[{"stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.2가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.2는 90 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]},{"stem":"7 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"17.5","correct":true},{"t":"1.75","mis":"M6-2-u3-X03"},{"t":"175","mis":"M6-2-u3-X04"},{"t":"0.175","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 7은 7.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 0.4는 70 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 17.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#6','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'mc','auto','8 ÷ 1.6에서 나누는 수를 자연수로 만들려면 두 수에 무엇을 곱해야 하나요?',ARRAY['M6-2-u3-X02','M6-2-u3-X08','M6-2-u3-X20']::text[],true,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"8 ÷ 1.6에서 나누는 수를 자연수로 만들려면 두 수에 무엇을 곱해야 하나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M6-2-u3-X02"},{"t":"16","mis":"M6-2-u3-X08"},{"t":"2","mis":"M6-2-u3-X20"}],"explanation":["1.6이 자연수가 되려면 소수점을 한 칸 옮겨요.","한 칸 옮기는 것은 10을 곱하는 것과 같아요.","두 수에 똑같이 10을 곱하면 80 ÷ 16이에요."],"variant_rule":{"alt":[{"stem":"7 ÷ 1.75에서 나누는 수를 자연수로 만들려면 두 수에 무엇을 곱해야 하나요?","options":[{"t":"100","correct":true},{"t":"10","mis":"M6-2-u3-X02"},{"t":"175","mis":"M6-2-u3-X08"},{"t":"4","mis":"M6-2-u3-X20"}],"explanation":["1.75가 자연수가 되려면 소수점을 두 칸 옮겨요.","두 칸 옮기는 것은 100을 곱하는 것과 같아요.","두 수에 똑같이 100을 곱하면 700 ÷ 175예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#7','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'sa','auto','31 ÷ 0.62의 몫은 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"31 ÷ 0.62의 몫은 얼마인가요?","answer":["50"],"explanation":["나누어지는 수 31은 31.00과 같아요 — 나누는 수 0.62가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","31 ÷ 0.62는 3100 ÷ 62가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","3100 ÷ 62 = 50이에요."],"variant_rule":{"alt":[{"stem":"13 ÷ 0.25의 몫은 얼마인가요?","answer":["52"],"explanation":["나누어지는 수 13은 13.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","13 ÷ 0.25는 1300 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1300 ÷ 25 = 52예요."]},{"stem":"3 ÷ 0.12의 몫은 얼마인가요?","answer":["25"],"explanation":["나누어지는 수 3은 3.00과 같아요 — 나누는 수 0.12가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","3 ÷ 0.12는 300 ÷ 12가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","300 ÷ 12 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#8','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'mc','auto','8을 1보다 작은 수로 나누면 몫은 8과 견주어 어떻게 되나요?',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":8,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"8을 1보다 작은 수로 나누면 몫은 8과 견주어 어떻게 되나요?","options":[{"t":"8보다 커진다","correct":true},{"t":"8보다 작아진다","mis":"M6-2-u3-X09"},{"t":"언제나 8이다","mis":"M6-2-u3-X09"},{"t":"8과 같거나 작아진다","mis":"M6-2-u3-X09"}],"explanation":["8 ÷ 0.8 = 10, 8 ÷ 0.4 = 20이에요.","1보다 작은 수는 8 안에 8번보다 더 여러 번 들어가요.","그래서 몫은 8보다 커져요."],"variant_rule":{"alt":[{"stem":"12를 1보다 작은 수로 나누면 몫은 12와 견주어 어떻게 되나요?","options":[{"t":"12보다 커진다","correct":true},{"t":"12보다 작아진다","mis":"M6-2-u3-X09"},{"t":"언제나 12이다","mis":"M6-2-u3-X09"},{"t":"12와 같거나 작아진다","mis":"M6-2-u3-X09"}],"explanation":["12 ÷ 0.6 = 20, 12 ÷ 0.4 = 30이에요.","1보다 작은 수는 더 여러 번 들어가요.","그래서 몫은 12보다 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#9','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'ox','auto','7 ÷ 1.75를 계산할 때 7은 소수점이 없으니 그대로 두고 1.75만 175로 바꾸어 7 ÷ 175로 계산해요.',ARRAY['M6-2-u3-X08']::text[],true,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":2,"kind":"ox","stem":"7 ÷ 1.75를 계산할 때 7은 소수점이 없으니 그대로 두고 1.75만 175로 바꾸어 7 ÷ 175로 계산해요.","answer":"X","reason_options":[{"t":"7은 7.00과 같아서 함께 두 칸 옮겨 700 ÷ 175로 계산해야 하기 때문에","correct":true},{"t":"나누어지는 수가 자연수이면 옮기지 않기 때문에","mis":"M6-2-u3-X08"}],"mis":"M6-2-u3-X08","explanation":["7은 7.00과 같아요.","1.75를 두 칸 옮기면 7도 두 칸 옮겨 700이에요.","700 ÷ 175 = 4예요."],"variant_rule":{"alt":[{"stem":"9 ÷ 0.6을 계산할 때 9는 소수점이 없으니 그대로 두고 0.6만 6으로 바꾸어 9 ÷ 6으로 계산해요.","answer":"X","reason_options":[{"t":"9는 9.0과 같아서 함께 한 칸 옮겨 90 ÷ 6으로 계산해야 하기 때문에","correct":true},{"t":"나누어지는 수가 자연수이면 옮기지 않기 때문에","mis":"M6-2-u3-X08"}],"explanation":["9는 9.0과 같아요.","0.6을 한 칸 옮기면 9도 한 칸 옮겨 90이에요.","90 ÷ 6 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_basic#10','math',6,2,'u3','L06','g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":10,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"8 ÷ 0.4","correct":true},{"t":"8 ÷ 0.8","mis":"M6-2-u3-X09"},{"t":"8 ÷ 1.6","mis":"M6-2-u3-X09"},{"t":"8 ÷ 2","mis":"M6-2-u3-X09"}],"explanation":["8 ÷ 2 = 4, 8 ÷ 1.6 = 5예요.","8 ÷ 0.8 = 10, 8 ÷ 0.4 = 20이에요.","나누는 수가 작을수록 몫이 커요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"6 ÷ 0.25","correct":true},{"t":"6 ÷ 0.5","mis":"M6-2-u3-X09"},{"t":"6 ÷ 1.5","mis":"M6-2-u3-X09"},{"t":"6 ÷ 3","mis":"M6-2-u3-X09"}],"explanation":["6 ÷ 3 = 2, 6 ÷ 1.5 = 4예요.","6 ÷ 0.5 = 12, 6 ÷ 0.25 = 24예요.","나누는 수가 작을수록 몫이 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#1','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',2,'sa','auto','91 ÷ 3.5의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"91 ÷ 3.5의 몫은 얼마인가요?","answer":["26"],"explanation":["나누어지는 수 91은 91.0과 같아요 — 나누는 수 3.5가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","91 ÷ 3.5는 910 ÷ 35가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","910 ÷ 35 = 26이에요."],"variant_rule":{"alt":[{"stem":"54 ÷ 1.5의 몫은 얼마인가요?","answer":["36"],"explanation":["나누어지는 수 54는 54.0과 같아요 — 나누는 수 1.5가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","54 ÷ 1.5는 540 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","540 ÷ 15 = 36이에요."]},{"stem":"78 ÷ 2.6의 몫은 얼마인가요?","answer":["30"],"explanation":["나누어지는 수 78은 78.0과 같아요 — 나누는 수 2.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","78 ÷ 2.6은 780 ÷ 26이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","780 ÷ 26 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#2','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',2,'mc','auto','9 ÷ 1.2의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":2,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.2가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.2는 90 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."],"variant_rule":{"alt":[{"stem":"2 ÷ 0.8의 몫은 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"0.25","mis":"M6-2-u3-X03"},{"t":"25","mis":"M6-2-u3-X04"},{"t":"0.025","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 2는 2.0과 같아요 — 나누는 수 0.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","2 ÷ 0.8은 20 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.5예요."]},{"stem":"7 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"17.5","correct":true},{"t":"1.75","mis":"M6-2-u3-X03"},{"t":"175","mis":"M6-2-u3-X04"},{"t":"0.175","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 7은 7.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 0.4는 70 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 17.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#3','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','54 ÷ 1.5의 몫을 3.6이라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X02','M6-2-u3-X07','M6-2-u3-X11']::text[],true,'{"seq":3,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"54 ÷ 1.5의 몫을 3.6이라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 잘못 옮겨서","mis":"M6-2-u3-X02"},{"t":"0을 내리지 않아서","mis":"M6-2-u3-X07"},{"t":"반올림을 하지 않아서","mis":"M6-2-u3-X11"}],"explanation":["54 ÷ 1.5는 540 ÷ 15예요.","540 ÷ 15 = 36이에요.","3.6은 몫의 소수점을 옮기기 전 자리에서 찍은 거예요."],"variant_rule":{"alt":[{"stem":"91 ÷ 3.5의 몫을 2.6이라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 잘못 옮겨서","mis":"M6-2-u3-X02"},{"t":"0을 내리지 않아서","mis":"M6-2-u3-X07"},{"t":"반올림을 하지 않아서","mis":"M6-2-u3-X11"}],"explanation":["91 ÷ 3.5는 910 ÷ 35예요.","910 ÷ 35 = 26이에요.","2.6은 몫의 소수점을 옮기기 전 자리에서 찍은 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#4','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'ox','auto','16 ÷ 0.25의 몫은 16보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":4,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["16 ÷ 0.25 = 1600 ÷ 25예요.","1600 ÷ 25 = 64예요.","64는 16보다 커요 — 1보다 작은 수로 나누면 몫이 커져요."],"variant_rule":{"alt":[{"stem":"31 ÷ 0.62의 몫은 31보다 작아요.","answer":"X","reason_options":[{"t":"0.62는 1보다 작아서 31 안에 31번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["31 ÷ 0.62 = 3100 ÷ 62예요.","3100 ÷ 62 = 50이에요.","50은 31보다 커요 — 1보다 작은 수로 나누면 몫이 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#5','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','몫이 나누어지는 수보다 큰 것은 어느 것인가요?',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":5,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"몫이 나누어지는 수보다 큰 것은 어느 것인가요?","options":[{"t":"9 ÷ 0.6","correct":true},{"t":"9 ÷ 1.5","mis":"M6-2-u3-X09"},{"t":"9 ÷ 1.8","mis":"M6-2-u3-X09"},{"t":"9 ÷ 3.6","mis":"M6-2-u3-X09"}],"explanation":["나누는 수가 1보다 작으면 몫은 나누어지는 수보다 커요.","0.6만 1보다 작아요.","9 ÷ 0.6 = 15 — 9보다 커요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나누어지는 수보다 큰 것은 어느 것인가요?","options":[{"t":"12 ÷ 0.8","correct":true},{"t":"12 ÷ 1.2","mis":"M6-2-u3-X09"},{"t":"12 ÷ 2.4","mis":"M6-2-u3-X09"},{"t":"12 ÷ 1.5","mis":"M6-2-u3-X09"}],"explanation":["나누는 수가 1보다 작으면 몫은 나누어지는 수보다 커요.","0.8만 1보다 작아요.","12 ÷ 0.8 = 15 — 12보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#6','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','물 6 L를 한 병에 0.75 L씩 나누어 담으면 몇 병이 되나요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],true,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"물 6 L를 한 병에 0.75 L씩 나누어 담으면 몇 병이 되나요?","options":[{"t":"8병","correct":true},{"t":"0.8병","mis":"M6-2-u3-X03"},{"t":"80병","mis":"M6-2-u3-X04"},{"t":"4.5병","mis":"M6-2-u3-X16"}],"explanation":["6 ÷ 0.75를 계산해요.","6은 6.00 — 두 칸씩 옮기면 600 ÷ 75예요.","600 ÷ 75 = 8 — 8병이에요."],"variant_rule":{"alt":[{"stem":"끈 13 m를 0.25 m씩 자르면 몇 도막이 되나요?","options":[{"t":"52도막","correct":true},{"t":"5.2도막","mis":"M6-2-u3-X03"},{"t":"520도막","mis":"M6-2-u3-X04"},{"t":"3.25도막","mis":"M6-2-u3-X16"}],"explanation":["13 ÷ 0.25를 계산해요.","13은 13.00 — 두 칸씩 옮기면 1300 ÷ 25예요.","1300 ÷ 25 = 52 — 52도막이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#7','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','7 ÷ 0.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X17']::text[],true,'{"seq":7,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"7 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"17.5","correct":true},{"t":"1.75","mis":"M6-2-u3-X03"},{"t":"175","mis":"M6-2-u3-X04"},{"t":"2.8","mis":"M6-2-u3-X17"}],"explanation":["7은 7.0 — 한 칸씩 옮기면 70 ÷ 4예요.","70 ÷ 4는 나누어떨어지지 않아 0을 내려 계산해요.","70 ÷ 4 = 17.5예요."],"variant_rule":{"alt":[{"stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"10.8","mis":"M6-2-u3-X16"}],"explanation":["9는 9.0 — 한 칸씩 옮기면 90 ÷ 12예요.","90 ÷ 12는 나누어떨어지지 않아 0을 내려 계산해요.","90 ÷ 12 = 7.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#8','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',4,'mc','auto','수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X09','M6-2-u3-X19']::text[],true,'{"seq":8,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6.52","correct":true},{"t":"2.56","mis":"M6-2-u3-X09"},{"t":"5.26","mis":"M6-2-u3-X09"},{"t":"6.25","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","2, 5, 6으로 만들 수 있는 □.□□ 가운데 가장 큰 수는 6.52예요.","그래서 □는 6.52예요."],"variant_rule":{"alt":[{"stem":"수 카드 3, 7, 4를 한 번씩만 써서 20 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"3.47","correct":true},{"t":"7.43","mis":"M6-2-u3-X09"},{"t":"4.37","mis":"M6-2-u3-X09"},{"t":"3.74","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","3, 7, 4로 만들 수 있는 □.□□ 가운데 가장 작은 수는 3.47이에요.","그래서 □는 3.47이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#9','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',4,'essay','teacher','직사각형 모양 태양 전지판의 넓이는 8 m², 세로는 1.6 m예요. 가로가 몇 m인지 어림한 뒤 계산하고, 8의 소수점을 어떻게 옮겼는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":4,"kind":"essay","stem":"직사각형 모양 태양 전지판의 넓이는 8 m², 세로는 1.6 m예요. 가로가 몇 m인지 어림한 뒤 계산하고, 8의 소수점을 어떻게 옮겼는지 설명해 보세요.","answer_guide":{"answer":"예: 8을 2보다 작은 수로 나누므로 8 ÷ 2 = 4보다 클 것으로 어림한다. 8은 8.0과 같으므로 1.6과 함께 한 칸 옮겨 80 ÷ 16 = 5이다. 가로는 5 m이다.","scoring_points":["4보다 클 것으로(또는 5쯤으로) 어림했는가","8을 8.0으로 보고 80으로 옮겼는가","80 ÷ 16 = 5, 가로 5 m를 구했는가"]},"explanation":["8 ÷ 2 = 4이므로 가로는 4 m보다 길 거예요.","8은 8.0 — 한 칸 옮겨 80이에요.","80 ÷ 16 = 5 — 가로는 5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L06_challenge#10','math',6,2,'u3','L06','g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',4,'essay','teacher','8 ÷ 1.6 = 5, 8 ÷ 0.8 = 10, 8 ÷ 0.4 = 20이에요. 나누는 수가 작아질수록 몫이 어떻게 되는지 쓰고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C6","difficulty":4,"kind":"essay","stem":"8 ÷ 1.6 = 5, 8 ÷ 0.8 = 10, 8 ÷ 0.4 = 20이에요. 나누는 수가 작아질수록 몫이 어떻게 되는지 쓰고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 나누는 수가 작아질수록 몫은 커진다. 같은 양을 더 작은 양씩 덜어 내면 더 여러 번 덜어 낼 수 있기 때문이다. 특히 1보다 작은 수로 나누면 몫이 나누어지는 수 8보다 커진다.","scoring_points":["몫이 커진다고 썼는가","더 작은 양씩 덜어 내면 더 여러 번이라는 까닭을 썼는가","1보다 작은 수로 나누면 8보다 커짐을 밝혔는가"]},"explanation":["나누는 수가 반이 되면 몫은 두 배가 돼요.","작은 양씩 덜어 내면 더 여러 번 덜어 낼 수 있어요.","1보다 작은 수로 나누면 몫이 8보다 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#1','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'mc','auto','1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":1,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.17","correct":true},{"t":"0.16","mis":"M6-2-u3-X11"},{"t":"0.167","mis":"M6-2-u3-X12"},{"t":"0.2","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.29","correct":true},{"t":"0.28","mis":"M6-2-u3-X11"},{"t":"0.286","mis":"M6-2-u3-X12"},{"t":"0.3","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 0.29예요."]},{"stem":"5 ÷ 3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.67","correct":true},{"t":"1.66","mis":"M6-2-u3-X11"},{"t":"1.667","mis":"M6-2-u3-X12"},{"t":"1.7","mis":"M6-2-u3-X12"}],"explanation":["5 ÷ 3 = 1.6666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 1.67이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#2','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'sa','auto','3.7 ÷ 0.7의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C7","difficulty":1,"kind":"sa","stem":"3.7 ÷ 0.7의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["5"],"explanation":["3.7 ÷ 0.7 = 5.285…예요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 2이므로 버려요 — 5예요."],"variant_rule":{"alt":[{"stem":"11 ÷ 3의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["4"],"explanation":["11 ÷ 3 = 3.666…이에요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 6이므로 올려요 — 4예요."]},{"stem":"4.7 ÷ 0.3의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["16"],"explanation":["4.7 ÷ 0.3 = 15.666…이에요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 6이므로 올려요 — 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#3','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'mc','auto','3.7 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":3,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"3.7 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.3","correct":true},{"t":"5.2","mis":"M6-2-u3-X11"},{"t":"5.29","mis":"M6-2-u3-X12"},{"t":"5","mis":"M6-2-u3-X12"}],"explanation":["3.7 ÷ 0.7 = 5.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 8이므로 올려요 — 5.3이에요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.2","mis":"M6-2-u3-X11"},{"t":"0.29","mis":"M6-2-u3-X12"},{"t":"0","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 8이므로 올려요 — 0.3이에요."]},{"stem":"9.5 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"13.6","correct":true},{"t":"13.5","mis":"M6-2-u3-X11"},{"t":"13.57","mis":"M6-2-u3-X12"},{"t":"14","mis":"M6-2-u3-X12"}],"explanation":["9.5 ÷ 0.7 = 13.571…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 7이므로 올려요 — 13.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#4','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'sa','auto','몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C7","difficulty":1,"kind":"sa","stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["2"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 첫째 자리의 한 자리 아래는 소수 둘째 자리예요.","그래서 소수 둘째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 일의 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["1"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","일의 자리의 한 자리 아래는 소수 첫째 자리예요.","그래서 소수 첫째 자리 숫자를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#5','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":5,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.77","correct":true},{"t":"4.76","mis":"M6-2-u3-X11"},{"t":"4.769","mis":"M6-2-u3-X12"},{"t":"4.8","mis":"M6-2-u3-X12"}],"explanation":["6.2 ÷ 1.3 = 4.7692…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 4.77이에요."],"variant_rule":{"alt":[{"stem":"4.3 ÷ 1.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.53","correct":true},{"t":"2.52","mis":"M6-2-u3-X11"},{"t":"2.529","mis":"M6-2-u3-X12"},{"t":"2.5","mis":"M6-2-u3-X12"}],"explanation":["4.3 ÷ 1.7 = 2.5294…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 2.53이에요."]},{"stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#6','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','하천을 살리는 흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내면 몇 kg인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":6,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"하천을 살리는 흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.17 kg","correct":true},{"t":"0.16 kg","mis":"M6-2-u3-X11"},{"t":"0.167 kg","mis":"M6-2-u3-X12"},{"t":"0.2 kg","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."],"variant_rule":{"alt":[{"stem":"하천을 살리는 흙 공 7개의 무게가 2 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.29 kg","correct":true},{"t":"0.28 kg","mis":"M6-2-u3-X11"},{"t":"0.286 kg","mis":"M6-2-u3-X12"},{"t":"0.3 kg","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 0.29예요."]},{"stem":"하천을 살리는 흙 공 3개의 무게가 2 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.7 kg","correct":true},{"t":"0.6 kg","mis":"M6-2-u3-X11"},{"t":"0.67 kg","mis":"M6-2-u3-X12"},{"t":"1 kg","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 3 = 0.666…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 0.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#7','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','1 ÷ 6을 계산하면 어떻게 되나요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],true,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 ÷ 6을 계산하면 어떻게 되나요?","options":[{"t":"0.166…처럼 6이 끝없이 이어진다","correct":true},{"t":"0.16으로 나누어떨어진다","mis":"M6-2-u3-X11"},{"t":"0.2로 나누어떨어진다","mis":"M6-2-u3-X12"},{"t":"6으로 나누어떨어진다","mis":"M6-2-u3-X17"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","6이 끝없이 이어져 몫을 소수로 다 쓸 수 없어요.","이럴 때는 몫을 반올림하여 나타내요."],"variant_rule":{"alt":[{"stem":"2 ÷ 3을 계산하면 어떻게 되나요?","options":[{"t":"0.666…처럼 6이 끝없이 이어진다","correct":true},{"t":"0.66으로 나누어떨어진다","mis":"M6-2-u3-X11"},{"t":"0.7로 나누어떨어진다","mis":"M6-2-u3-X12"},{"t":"1.5로 나누어떨어진다","mis":"M6-2-u3-X17"}],"explanation":["2 ÷ 3 = 0.666…이에요.","6이 끝없이 이어져 몫을 소수로 다 쓸 수 없어요.","이럴 때는 몫을 반올림하여 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#8','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','11 ÷ 3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"11 ÷ 3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.7","correct":true},{"t":"3.6","mis":"M6-2-u3-X11"},{"t":"3.67","mis":"M6-2-u3-X12"},{"t":"4","mis":"M6-2-u3-X12"}],"explanation":["11 ÷ 3 = 3.666…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 3.7이에요."],"variant_rule":{"alt":[{"stem":"7.3 ÷ 0.6의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"12.2","correct":true},{"t":"12.1","mis":"M6-2-u3-X11"},{"t":"12.17","mis":"M6-2-u3-X12"},{"t":"12","mis":"M6-2-u3-X12"}],"explanation":["7.3 ÷ 0.6 = 12.166…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 12.2예요."]},{"stem":"5 ÷ 3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"1.6","mis":"M6-2-u3-X11"},{"t":"1.67","mis":"M6-2-u3-X12"},{"t":"2","mis":"M6-2-u3-X12"}],"explanation":["5 ÷ 3 = 1.666…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 1.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#9','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'ox','auto','3.7 ÷ 0.7 = 5.285…예요. 몫을 반올림하여 소수 첫째 자리까지 나타내면 5.29예요.',ARRAY['M6-2-u3-X12']::text[],true,'{"seq":9,"concept":"M6-2-u3-C7","difficulty":2,"kind":"ox","stem":"3.7 ÷ 0.7 = 5.285…예요. 몫을 반올림하여 소수 첫째 자리까지 나타내면 5.29예요.","answer":"X","reason_options":[{"t":"소수 첫째 자리까지는 둘째 자리 8을 보고 올려 5.3이고, 5.29는 둘째 자리까지 나타낸 수라서","correct":true},{"t":"소수 첫째 자리까지 나타낼 때는 소수 셋째 자리를 보기 때문에","mis":"M6-2-u3-X12"}],"mis":"M6-2-u3-X12","explanation":["소수 첫째 자리까지 나타내려면 둘째 자리 숫자 8을 봐요.","8은 5 이상이라 올려 5.3이에요.","5.29는 소수 둘째 자리까지 나타낸 수예요."],"variant_rule":{"alt":[{"stem":"6.2 ÷ 1.3 = 4.769…예요. 몫을 반올림하여 소수 첫째 자리까지 나타내면 4.77이에요.","answer":"X","reason_options":[{"t":"소수 첫째 자리까지는 둘째 자리 6을 보고 올려 4.8이고, 4.77은 둘째 자리까지 나타낸 수라서","correct":true},{"t":"소수 첫째 자리까지 나타낼 때는 소수 셋째 자리를 보기 때문에","mis":"M6-2-u3-X12"}],"explanation":["소수 첫째 자리까지 나타내려면 둘째 자리 숫자 6을 봐요.","6은 5 이상이라 올려 4.8이에요.","4.77은 소수 둘째 자리까지 나타낸 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_basic#10','math',6,2,'u3','L07','g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',3,'mc','auto','3.7 ÷ 0.7 = 5.285…예요. 반올림한 자리와 결과를 바르게 짝지은 것은 어느 것인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X10']::text[],true,'{"seq":10,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"3.7 ÷ 0.7 = 5.285…예요. 반올림한 자리와 결과를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"소수 둘째 자리까지 — 5.29","correct":true},{"t":"소수 첫째 자리까지 — 5.2","mis":"M6-2-u3-X11"},{"t":"일의 자리까지 — 6","mis":"M6-2-u3-X10"},{"t":"소수 둘째 자리까지 — 5.28","mis":"M6-2-u3-X11"}],"explanation":["일의 자리까지면 5, 소수 첫째 자리까지면 5.3이에요.","소수 둘째 자리까지면 셋째 자리 5를 보고 올려 5.29예요.","어느 자리까지 나타낼지에 따라 답이 달라져요."],"variant_rule":{"alt":[{"stem":"6.2 ÷ 1.3 = 4.769…예요. 반올림한 자리와 결과를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"소수 둘째 자리까지 — 4.77","correct":true},{"t":"소수 첫째 자리까지 — 4.7","mis":"M6-2-u3-X11"},{"t":"일의 자리까지 — 4","mis":"M6-2-u3-X11"},{"t":"소수 둘째 자리까지 — 4.76","mis":"M6-2-u3-X11"}],"explanation":["일의 자리까지면 5, 소수 첫째 자리까지면 4.8이에요.","소수 둘째 자리까지면 셋째 자리 9를 보고 올려 4.77이에요.","어느 자리까지 나타낼지에 따라 답이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#1','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',2,'mc','auto','3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":1,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."],"variant_rule":{"alt":[{"stem":"7.3 ÷ 0.6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"12.17","correct":true},{"t":"12.16","mis":"M6-2-u3-X11"},{"t":"12.167","mis":"M6-2-u3-X12"},{"t":"12.2","mis":"M6-2-u3-X12"}],"explanation":["7.3 ÷ 0.6 = 12.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 12.17이에요."]},{"stem":"4.3 ÷ 1.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.53","correct":true},{"t":"2.52","mis":"M6-2-u3-X11"},{"t":"2.529","mis":"M6-2-u3-X12"},{"t":"2.5","mis":"M6-2-u3-X12"}],"explanation":["4.3 ÷ 1.7 = 2.5294…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 2.53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#2','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',2,'mc','auto','9.5 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":2,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"9.5 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"13.6","correct":true},{"t":"13.5","mis":"M6-2-u3-X11"},{"t":"13.57","mis":"M6-2-u3-X12"},{"t":"14","mis":"M6-2-u3-X12"}],"explanation":["9.5 ÷ 0.7 = 13.571…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 7이므로 올려요 — 13.6이에요."],"variant_rule":{"alt":[{"stem":"8.6 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"12.2","mis":"M6-2-u3-X11"},{"t":"12.29","mis":"M6-2-u3-X12"},{"t":"12","mis":"M6-2-u3-X12"}],"explanation":["8.6 ÷ 0.7 = 12.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 8이므로 올려요 — 12.3이에요."]},{"stem":"7.9 ÷ 0.6의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"13.2","correct":true},{"t":"13.1","mis":"M6-2-u3-X11"},{"t":"13.17","mis":"M6-2-u3-X12"},{"t":"13","mis":"M6-2-u3-X12"}],"explanation":["7.9 ÷ 0.6 = 13.166…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 13.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#3','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":3,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자 6이 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 셋째 자리 6을 봐요.","6은 5 이상이라 올려 0.17이에요 — 0.16은 그냥 버린 수예요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자 8이 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 둘째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 둘째 자리 8을 봐요.","8은 5 이상이라 올려 0.3이에요 — 0.2는 그냥 버린 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#4','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','몫을 반올림하여 일의 자리까지 나타낸 값이 4인 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":4,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"몫을 반올림하여 일의 자리까지 나타낸 값이 4인 것은 어느 것인가요?","options":[{"t":"11 ÷ 3","correct":true},{"t":"4.7 ÷ 0.3","mis":"M6-2-u3-X19"},{"t":"3.7 ÷ 0.7","mis":"M6-2-u3-X19"},{"t":"10 ÷ 6","mis":"M6-2-u3-X19"}],"explanation":["11 ÷ 3 = 3.66…은 반올림하면 4예요.","4.7 ÷ 0.3 = 15.66… → 16, 3.7 ÷ 0.7 = 5.28… → 5예요.","10 ÷ 6 = 1.66… → 2예요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 일의 자리까지 나타낸 값이 2인 것은 어느 것인가요?","options":[{"t":"10 ÷ 6","correct":true},{"t":"11 ÷ 3","mis":"M6-2-u3-X19"},{"t":"3.7 ÷ 0.7","mis":"M6-2-u3-X19"},{"t":"2 ÷ 7","mis":"M6-2-u3-X19"}],"explanation":["10 ÷ 6 = 1.66…은 반올림하면 2예요.","11 ÷ 3 = 3.66… → 4, 3.7 ÷ 0.7 = 5.28… → 5예요.","2 ÷ 7 = 0.28… → 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#5','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'sa','auto','4.7 ÷ 0.3의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u3-C7","difficulty":3,"kind":"sa","stem":"4.7 ÷ 0.3의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["16"],"explanation":["4.7 ÷ 0.3 = 15.666…이에요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 6이므로 올려요 — 16이에요."],"variant_rule":{"alt":[{"stem":"10 ÷ 6의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["2"],"explanation":["10 ÷ 6 = 1.666…이에요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 6이므로 올려요 — 2예요."]},{"stem":"8.5 ÷ 0.9의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["9"],"explanation":["8.5 ÷ 0.9 = 9.444…예요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 4이므로 버려요 — 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#6','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'ox','auto','반올림하여 소수 둘째 자리까지 나타내면 0.17인 수는 1 ÷ 6뿐이에요.',ARRAY['M6-2-u3-X12']::text[],true,'{"seq":6,"concept":"M6-2-u3-C7","difficulty":3,"kind":"ox","stem":"반올림하여 소수 둘째 자리까지 나타내면 0.17인 수는 1 ÷ 6뿐이에요.","answer":"X","reason_options":[{"t":"1 ÷ 6 = 0.166…뿐 아니라 0.17로 반올림되는 몫은 여럿이라서(예: 0.17·0.174…)","correct":true},{"t":"반올림하면 나누는 식마다 결과가 꼭 다르기 때문에","mis":"M6-2-u3-X12"}],"mis":"M6-2-u3-X12","explanation":["1 ÷ 6 = 0.166…은 반올림하면 0.17이에요.","0.165부터 0.174…까지는 모두 0.17이 돼요.","그래서 0.17이 되는 몫은 1 ÷ 6만이 아니에요."],"variant_rule":{"alt":[{"stem":"반올림하여 소수 첫째 자리까지 나타내면 5.3인 수는 3.7 ÷ 0.7뿐이에요.","answer":"X","reason_options":[{"t":"5.25부터 5.34…까지 여러 몫이 모두 5.3이 되기 때문에","correct":true},{"t":"반올림하면 나누는 식마다 결과가 꼭 다르기 때문에","mis":"M6-2-u3-X12"}],"explanation":["3.7 ÷ 0.7 = 5.285…는 반올림하면 5.3이에요.","5.25부터 5.34…까지는 모두 5.3이 돼요.","그래서 5.3이 되는 몫은 여럿이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#7','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],true,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.2 kg","correct":true},{"t":"0.1 kg","mis":"M6-2-u3-X11"},{"t":"0.17 kg","mis":"M6-2-u3-X12"},{"t":"6 kg","mis":"M6-2-u3-X17"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 첫째 자리까지는 둘째 자리 6을 봐요.","6은 5 이상이라 올려 0.2 kg이에요."],"variant_rule":{"alt":[{"stem":"흙 공 7개의 무게가 2 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.3 kg","correct":true},{"t":"0.2 kg","mis":"M6-2-u3-X11"},{"t":"0.29 kg","mis":"M6-2-u3-X12"},{"t":"3.5 kg","mis":"M6-2-u3-X17"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지는 둘째 자리 8을 봐요.","8은 5 이상이라 올려 0.3 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#8','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',4,'mc','auto','□ ÷ 3의 몫을 반올림하여 일의 자리까지 나타내면 4예요. □에 들어갈 수 있는 자연수는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":4,"kind":"mc","stem":"□ ÷ 3의 몫을 반올림하여 일의 자리까지 나타내면 4예요. □에 들어갈 수 있는 자연수는 어느 것인가요?","options":[{"t":"13","correct":true},{"t":"9","mis":"M6-2-u3-X19"},{"t":"14","mis":"M6-2-u3-X19"},{"t":"15","mis":"M6-2-u3-X19"}],"explanation":["몫이 3.5 이상 4.5 미만이면 반올림하여 4예요.","9 ÷ 3 = 3, 13 ÷ 3 = 4.33…, 14 ÷ 3 = 4.66…, 15 ÷ 3 = 5예요.","그래서 13이에요."],"variant_rule":{"alt":[{"stem":"□ ÷ 6의 몫을 반올림하여 일의 자리까지 나타내면 2예요. □에 들어갈 수 있는 자연수는 어느 것인가요?","options":[{"t":"10","correct":true},{"t":"8","mis":"M6-2-u3-X19"},{"t":"15","mis":"M6-2-u3-X19"},{"t":"18","mis":"M6-2-u3-X19"}],"explanation":["몫이 1.5 이상 2.5 미만이면 반올림하여 2예요.","8 ÷ 6 = 1.33…, 10 ÷ 6 = 1.66…, 15 ÷ 6 = 2.5, 18 ÷ 6 = 3이에요.","그래서 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#9','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',4,'essay','teacher','3.7 ÷ 0.7의 몫을 반올림하여 일의 자리, 소수 첫째 자리, 소수 둘째 자리까지 각각 나타내고, 답이 달라지는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C7","difficulty":4,"kind":"essay","stem":"3.7 ÷ 0.7의 몫을 반올림하여 일의 자리, 소수 첫째 자리, 소수 둘째 자리까지 각각 나타내고, 답이 달라지는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 3.7 ÷ 0.7 = 5.285…이다. 일의 자리까지는 첫째 자리 2를 보고 버려 5, 소수 첫째 자리까지는 둘째 자리 8을 보고 올려 5.3, 소수 둘째 자리까지는 셋째 자리 5를 보고 올려 5.29이다. 나타낼 자리마다 보아야 하는 아랫자리 숫자가 달라서 답이 달라진다.","scoring_points":["5, 5.3, 5.29를 모두 바르게 구했는가","각 자리마다 한 자리 아래 숫자를 보았음을 썼는가","나타낼 자리에 따라 답이 달라진다는 까닭을 썼는가"]},"explanation":["3.7 ÷ 0.7 = 5.285…예요.","일의 자리 5 · 첫째 자리 5.3 · 둘째 자리 5.29예요.","보는 자리가 달라 답이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L07_challenge#10','math',6,2,'u3','L07','g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',4,'essay','teacher','하천을 살리는 흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내는 과정을 쓰고, 왜 반올림해야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C7","difficulty":4,"kind":"essay","stem":"하천을 살리는 흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내는 과정을 쓰고, 왜 반올림해야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 1 ÷ 6 = 0.166…으로 6이 끝없이 이어져 몫을 소수로 다 쓸 수 없으므로 반올림한다. 소수 둘째 자리까지 나타내려면 셋째 자리 6을 보고 올려 0.17 kg이다.","scoring_points":["1 ÷ 6 = 0.166…을 구했는가","나누어떨어지지 않아 반올림한다는 까닭을 썼는가","셋째 자리를 보고 올려 0.17 kg을 구했는가"]},"explanation":["1 ÷ 6 = 0.166…으로 끝나지 않아요.","그래서 반올림해서 나타내요.","셋째 자리 6을 보고 올려 0.17 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#1','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'sa','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L, 5번 주려면 9 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L, 8번 주려면 11.2 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["9.6 ÷ 1.5를 계산하면 6.4예요.","1.5 L씩 6번 주면 9 L, 7번 주려면 10.5 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#2','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'mc','auto','당근주스를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?',ARRAY['M6-2-u3-X15','M6-2-u3-X13','M6-2-u3-X20']::text[],true,'{"seq":2,"concept":"M6-2-u3-C8","difficulty":1,"kind":"mc","stem":"당근주스를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"7.2 L","correct":true},{"t":"7.8 L","mis":"M6-2-u3-X15"},{"t":"9 L","mis":"M6-2-u3-X13"},{"t":"6.2 L","mis":"M6-2-u3-X20"}],"explanation":["한 명에게 1.8 L씩 4명이에요.","나누어 준 양은 곱셈으로 구해요.","1.8 × 4 = 7.2 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"9.8 L","correct":true},{"t":"10.2 L","mis":"M6-2-u3-X15"},{"t":"11.2 L","mis":"M6-2-u3-X13"},{"t":"8.8 L","mis":"M6-2-u3-X20"}],"explanation":["한 명에게 1.4 L씩 7명이에요.","나누어 준 양은 곱셈으로 구해요.","1.4 × 7 = 9.8 (L)예요."]},{"stem":"당근주스를 한 명에게 2.4 L씩 6명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"14.4 L","correct":true},{"t":"15.2 L","mis":"M6-2-u3-X15"},{"t":"16.8 L","mis":"M6-2-u3-X13"},{"t":"13.4 L","mis":"M6-2-u3-X20"}],"explanation":["한 명에게 2.4 L씩 6명이에요.","나누어 준 양은 곱셈으로 구해요.","2.4 × 6 = 14.4 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#3','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":3,"concept":"M6-2-u3-C8","difficulty":1,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]},{"stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.9 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"12.8 L","mis":"M6-2-u3-X15"},{"t":"1.6 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.6 × 8 = 12.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","13.7 − 12.8 = 0.9 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#4','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'sa','auto','당근주스 12.5 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 12.5 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["8"],"explanation":["12.5 ÷ 1.5를 계산하면 8.333…이에요.","1.5 L씩 8번 주면 12 L, 9번 주려면 13.5 L가 있어야 해요.","그래서 8명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 8.5 L를 한 명에게 1.2 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["8.5 ÷ 1.2를 계산하면 7.083…이에요.","1.2 L씩 7번 주면 8.4 L, 8번 주려면 9.6 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 6.4 L를 한 명에게 1.2 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["5"],"explanation":["6.4 ÷ 1.2를 계산하면 5.333…이에요.","1.2 L씩 5번 주면 6 L, 6번 주려면 7.2 L가 있어야 해요.","그래서 5명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#5','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스 9.6 L를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":5,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.4 L","mis":"M6-2-u3-X14"},{"t":"9 L","mis":"M6-2-u3-X15"},{"t":"1.5 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.5 × 6 = 9 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","9.6 − 9 = 0.6 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 12.5 L를 한 명에게 1.5 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.5 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"12 L","mis":"M6-2-u3-X15"},{"t":"1.5 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.5 × 8 = 12 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","12.5 − 12 = 0.5 (L)예요."]},{"stem":"당근주스 9.3 L를 한 명에게 2.2 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.5 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"8.8 L","mis":"M6-2-u3-X15"},{"t":"2.2 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 2.2 × 4 = 8.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","9.3 − 8.8 = 0.5 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#6','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','7.8 ÷ 1.8을 계산기로 계산하면 4.333…이 나와요. 나누어 줄 수 있는 사람 수를 4.333…명이라고 쓰지 않는 까닭은 무엇인가요?',ARRAY['M6-2-u3-X13','M6-2-u3-X20','M6-2-u3-X14']::text[],true,'{"seq":6,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"7.8 ÷ 1.8을 계산기로 계산하면 4.333…이 나와요. 나누어 줄 수 있는 사람 수를 4.333…명이라고 쓰지 않는 까닭은 무엇인가요?","options":[{"t":"나누어 줄 사람 수는 자연수여야 하기 때문에","correct":true},{"t":"몫을 반올림해야 하기 때문에","mis":"M6-2-u3-X13"},{"t":"계산기가 틀렸기 때문에","mis":"M6-2-u3-X20"},{"t":"주스의 양이 소수이기 때문에","mis":"M6-2-u3-X14"}],"explanation":["사람 수는 1명, 2명처럼 자연수로 세요.","1.8 L씩 4번은 줄 수 있지만 5번은 줄 수 없어요.","그래서 4명이에요."],"variant_rule":{"alt":[{"stem":"10.2 ÷ 1.4를 계산기로 계산하면 7.285…가 나와요. 나누어 줄 수 있는 사람 수를 7.285…명이라고 쓰지 않는 까닭은 무엇인가요?","options":[{"t":"나누어 줄 사람 수는 자연수여야 하기 때문에","correct":true},{"t":"몫을 반올림해야 하기 때문에","mis":"M6-2-u3-X13"},{"t":"계산기가 틀렸기 때문에","mis":"M6-2-u3-X20"},{"t":"주스의 양이 소수이기 때문에","mis":"M6-2-u3-X14"}],"explanation":["사람 수는 자연수로 세요.","1.4 L씩 7번은 줄 수 있지만 8번은 줄 수 없어요.","그래서 7명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#7','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주고 남는 양을 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X15']::text[],true,'{"seq":7,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주고 남는 양을 구하는 식은 어느 것인가요?","options":[{"t":"7.8 − 1.8 × 4","correct":true},{"t":"7.8 ÷ 1.8","mis":"M6-2-u3-X15"},{"t":"1.8 × 4","mis":"M6-2-u3-X15"},{"t":"7.8 − 1.8","mis":"M6-2-u3-X15"}],"explanation":["1.8 L씩 4명에게 나누어 줄 수 있어요.","나누어 준 양은 1.8 × 4예요.","남는 양은 전체에서 빼서 7.8 − 1.8 × 4예요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주고 남는 양을 구하는 식은 어느 것인가요?","options":[{"t":"10.2 − 1.4 × 7","correct":true},{"t":"10.2 ÷ 1.4","mis":"M6-2-u3-X15"},{"t":"1.4 × 7","mis":"M6-2-u3-X15"},{"t":"10.2 − 1.4","mis":"M6-2-u3-X15"}],"explanation":["1.4 L씩 7명에게 나누어 줄 수 있어요.","나누어 준 양은 1.4 × 7이에요.","남는 양은 전체에서 빼서 10.2 − 1.4 × 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#8','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?',ARRAY['M6-2-u3-X15','M6-2-u3-X13','M6-2-u3-X20']::text[],true,'{"seq":8,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"9 L","correct":true},{"t":"9.6 L","mis":"M6-2-u3-X15"},{"t":"10.5 L","mis":"M6-2-u3-X13"},{"t":"8 L","mis":"M6-2-u3-X20"}],"explanation":["한 명에게 1.5 L씩 6명이에요.","나누어 준 양은 곱셈으로 구해요.","1.5 × 6 = 9 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스를 한 명에게 1.5 L씩 8명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"12 L","correct":true},{"t":"12.5 L","mis":"M6-2-u3-X15"},{"t":"13.5 L","mis":"M6-2-u3-X13"},{"t":"11 L","mis":"M6-2-u3-X20"}],"explanation":["한 명에게 1.5 L씩 8명이에요.","나누어 준 양은 곱셈으로 구해요.","1.5 × 8 = 12 (L)예요."]},{"stem":"당근주스를 한 명에게 2.2 L씩 4명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"8.8 L","correct":true},{"t":"9.3 L","mis":"M6-2-u3-X15"},{"t":"11 L","mis":"M6-2-u3-X13"},{"t":"7.8 L","mis":"M6-2-u3-X20"}],"explanation":["한 명에게 2.2 L씩 4명이에요.","나누어 준 양은 곱셈으로 구해요.","2.2 × 4 = 8.8 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#9','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'sa','auto','당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["15.2 ÷ 2.4를 계산하면 6.333…이에요.","2.4 L씩 6번 주면 14.4 L, 7번 주려면 16.8 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["8"],"explanation":["13.7 ÷ 1.6을 계산하면 8.562…예요.","1.6 L씩 8번 주면 12.8 L, 9번 주려면 14.4 L가 있어야 해요.","그래서 8명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 20.5 L를 한 명에게 3.2 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["20.5 ÷ 3.2를 계산하면 6.406…이에요.","3.2 L씩 6번 주면 19.2 L, 7번 주려면 22.4 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_basic#10','math',6,2,'u3','L08','g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',3,'mc','auto','당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 양을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X15']::text[],true,'{"seq":10,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 양을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"7명, 0.4 L","correct":true},{"t":"7명, 0.2 L","mis":"M6-2-u3-X14"},{"t":"8명, 1 L","mis":"M6-2-u3-X13"},{"t":"7명, 9.8 L","mis":"M6-2-u3-X15"}],"explanation":["10.2 ÷ 1.4 = 7.285…이므로 7명에게 줄 수 있어요.","나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 10.2 − 9.8 = 0.4 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 양을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"6명, 0.6 L","correct":true},{"t":"6명, 0.4 L","mis":"M6-2-u3-X14"},{"t":"7명, 1.5 L","mis":"M6-2-u3-X13"},{"t":"6명, 9 L","mis":"M6-2-u3-X15"}],"explanation":["9.6 ÷ 1.5 = 6.4이므로 6명에게 줄 수 있어요.","나누어 준 양은 1.5 × 6 = 9 (L)예요.","남는 양은 9.6 − 9 = 0.6 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#1','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',2,'sa','auto','당근주스 11.3 L를 한 명에게 2.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"당근주스 11.3 L를 한 명에게 2.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["11.3 ÷ 2.5를 계산하면 4.52예요.","2.5 L씩 4번 주면 10 L, 5번 주려면 12.5 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 7.4 L를 한 명에게 0.9 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["8"],"explanation":["7.4 ÷ 0.9를 계산하면 8.222…예요.","0.9 L씩 8번 주면 7.2 L, 9번 주려면 8.1 L가 있어야 해요.","그래서 8명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 20.5 L를 한 명에게 3.2 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["20.5 ÷ 3.2를 계산하면 6.406…이에요.","3.2 L씩 6번 주면 19.2 L, 7번 주려면 22.4 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#2','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',2,'mc','auto','당근주스 11.3 L를 한 명에게 2.5 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":2,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 11.3 L를 한 명에게 2.5 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"1.3 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"10 L","mis":"M6-2-u3-X15"},{"t":"2.5 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 2.5 × 4 = 10 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","11.3 − 10 = 1.3 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 7.4 L를 한 명에게 0.9 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.2 L","correct":true},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"0.9 L","mis":"M6-2-u3-X15"},{"t":"7.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 0.9 × 8 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.4 − 7.2 = 0.2 (L)예요."]},{"stem":"당근주스 20.5 L를 한 명에게 3.2 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"1.3 L","correct":true},{"t":"0.4 L","mis":"M6-2-u3-X14"},{"t":"19.2 L","mis":"M6-2-u3-X15"},{"t":"3.2 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 3.2 × 6 = 19.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","20.5 − 19.2 = 1.3 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#3','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'ox','auto','주스 11.3 L를 한 명에게 2.5 L씩 나누어 주어요. 11.3 ÷ 2.5 = 4.52이고 반올림하면 5이므로 5명에게 나누어 줄 수 있어요.',ARRAY['M6-2-u3-X13']::text[],true,'{"seq":3,"concept":"M6-2-u3-C8","difficulty":3,"kind":"ox","stem":"주스 11.3 L를 한 명에게 2.5 L씩 나누어 주어요. 11.3 ÷ 2.5 = 4.52이고 반올림하면 5이므로 5명에게 나누어 줄 수 있어요.","answer":"X","reason_options":[{"t":"5명에게 주려면 12.5 L가 있어야 하는데 11.3 L뿐이라서 4명에게만 줄 수 있기 때문에","correct":true},{"t":"사람 수는 몫을 반올림하여 정하기 때문에","mis":"M6-2-u3-X13"}],"mis":"M6-2-u3-X13","explanation":["2.5 L씩 5명에게 주려면 2.5 × 5 = 12.5 (L)가 필요해요.","주스는 11.3 L뿐이라 모자라요.","그래서 4명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"주스 13.7 L를 한 명에게 1.6 L씩 나누어 주어요. 13.7 ÷ 1.6 = 8.5625이고 반올림하면 9이므로 9명에게 나누어 줄 수 있어요.","answer":"X","reason_options":[{"t":"9명에게 주려면 14.4 L가 있어야 하는데 13.7 L뿐이라서 8명에게만 줄 수 있기 때문에","correct":true},{"t":"사람 수는 몫을 반올림하여 정하기 때문에","mis":"M6-2-u3-X13"}],"explanation":["1.6 L씩 9명에게 주려면 1.6 × 9 = 14.4 (L)가 필요해요.","주스는 13.7 L뿐이라 모자라요.","그래서 8명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#4','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','7.8 ÷ 1.8 = 4.333…이에요. 남는 주스를 0.3 L라고 답한 친구가 있어요. 무엇을 잘못했나요?',ARRAY['M6-2-u3-X13','M6-2-u3-X15','M6-2-u3-X02']::text[],true,'{"seq":4,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"7.8 ÷ 1.8 = 4.333…이에요. 남는 주스를 0.3 L라고 답한 친구가 있어요. 무엇을 잘못했나요?","options":[{"t":"몫의 소수 부분을 남는 양으로 읽었다","correct":true},{"t":"나누어 줄 사람 수를 반올림했다","mis":"M6-2-u3-X13"},{"t":"나누어 준 양을 답으로 썼다","mis":"M6-2-u3-X15"},{"t":"두 수의 소수점을 다르게 옮겼다","mis":"M6-2-u3-X02"}],"explanation":["몫 4.333…의 소수 부분은 남는 양이 아니에요.","나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 7.8 − 7.2 = 0.6 (L)예요."],"variant_rule":{"alt":[{"stem":"10.2 ÷ 1.4 = 7.285…예요. 남는 주스를 0.2 L라고 답한 친구가 있어요. 무엇을 잘못했나요?","options":[{"t":"몫의 소수 부분을 남는 양으로 읽었다","correct":true},{"t":"나누어 줄 사람 수를 반올림했다","mis":"M6-2-u3-X13"},{"t":"나누어 준 양을 답으로 썼다","mis":"M6-2-u3-X15"},{"t":"두 수의 소수점을 다르게 옮겼다","mis":"M6-2-u3-X02"}],"explanation":["몫 7.285…의 소수 부분은 남는 양이 아니에요.","나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 10.2 − 9.8 = 0.4 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#5','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','리본 9.3 m를 한 사람에게 2.2 m씩 나누어 주었어요. 몇 명에게 나누어 주고 몇 m가 남나요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X15']::text[],true,'{"seq":5,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"리본 9.3 m를 한 사람에게 2.2 m씩 나누어 주었어요. 몇 명에게 나누어 주고 몇 m가 남나요?","options":[{"t":"4명, 0.5 m","correct":true},{"t":"4명, 0.2 m","mis":"M6-2-u3-X14"},{"t":"5명, 1.7 m","mis":"M6-2-u3-X13"},{"t":"4명, 8.8 m","mis":"M6-2-u3-X15"}],"explanation":["9.3 ÷ 2.2 = 4.22…이므로 4명에게 줄 수 있어요.","나누어 준 리본은 2.2 × 4 = 8.8 (m)예요.","남는 리본은 9.3 − 8.8 = 0.5 (m)예요."],"variant_rule":{"alt":[{"stem":"리본 15.2 m를 한 사람에게 2.4 m씩 나누어 주었어요. 몇 명에게 나누어 주고 몇 m가 남나요?","options":[{"t":"6명, 0.8 m","correct":true},{"t":"6명, 0.3 m","mis":"M6-2-u3-X14"},{"t":"7명, 1.6 m","mis":"M6-2-u3-X13"},{"t":"6명, 14.4 m","mis":"M6-2-u3-X15"}],"explanation":["15.2 ÷ 2.4 = 6.33…이므로 6명에게 줄 수 있어요.","나누어 준 리본은 2.4 × 6 = 14.4 (m)예요.","남는 리본은 15.2 − 14.4 = 0.8 (m)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#6','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','쌀 8.5 kg을 한 봉지에 1.2 kg씩 담았어요. 가득 찬 봉지는 몇 봉지이고 남는 쌀은 몇 kg인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X15']::text[],true,'{"seq":6,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"쌀 8.5 kg을 한 봉지에 1.2 kg씩 담았어요. 가득 찬 봉지는 몇 봉지이고 남는 쌀은 몇 kg인가요?","options":[{"t":"7봉지, 0.1 kg","correct":true},{"t":"7봉지, 0.08 kg","mis":"M6-2-u3-X14"},{"t":"8봉지, 1.1 kg","mis":"M6-2-u3-X13"},{"t":"7봉지, 8.4 kg","mis":"M6-2-u3-X15"}],"explanation":["8.5 ÷ 1.2 = 7.08…이므로 가득 찬 봉지는 7봉지예요.","담은 쌀은 1.2 × 7 = 8.4 (kg)이에요.","남는 쌀은 8.5 − 8.4 = 0.1 (kg)이에요."],"variant_rule":{"alt":[{"stem":"쌀 6.4 kg을 한 봉지에 1.2 kg씩 담았어요. 가득 찬 봉지는 몇 봉지이고 남는 쌀은 몇 kg인가요?","options":[{"t":"5봉지, 0.4 kg","correct":true},{"t":"5봉지, 0.3 kg","mis":"M6-2-u3-X14"},{"t":"6봉지, 0.8 kg","mis":"M6-2-u3-X13"},{"t":"5봉지, 6 kg","mis":"M6-2-u3-X15"}],"explanation":["6.4 ÷ 1.2 = 5.33…이므로 가득 찬 봉지는 5봉지예요.","담은 쌀은 1.2 × 5 = 6 (kg)이에요.","남는 쌀은 6.4 − 6 = 0.4 (kg)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#7','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주고 남은 주스를 모두 한 명에게 더 주려고 해요. 그 사람은 주스를 몇 L 받게 되나요?',ARRAY['M6-2-u3-X15','M6-2-u3-X14','M6-2-u3-X20']::text[],true,'{"seq":7,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주고 남은 주스를 모두 한 명에게 더 주려고 해요. 그 사람은 주스를 몇 L 받게 되나요?","options":[{"t":"0.6 L","correct":true},{"t":"1.8 L","mis":"M6-2-u3-X15"},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"2.4 L","mis":"M6-2-u3-X20"}],"explanation":["1.8 L씩 4명에게 주면 7.2 L를 나누어 줘요.","남는 주스는 7.8 − 7.2 = 0.6 (L)예요.","그래서 다섯째 사람은 0.6 L를 받아요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주고 남은 주스를 모두 한 명에게 더 주려고 해요. 그 사람은 주스를 몇 L 받게 되나요?","options":[{"t":"0.4 L","correct":true},{"t":"1.4 L","mis":"M6-2-u3-X15"},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"1.8 L","mis":"M6-2-u3-X20"}],"explanation":["1.4 L씩 7명에게 주면 9.8 L를 나누어 줘요.","남는 주스는 10.2 − 9.8 = 0.4 (L)예요.","그래서 여덟째 사람은 0.4 L를 받아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#8','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',4,'mc','auto','주스를 한 명에게 1.5 L씩 6명에게 나누어 주었더니 0.6 L가 남았어요. 처음 주스는 몇 L였나요?',ARRAY['M6-2-u3-X15','M6-2-u3-X20']::text[],true,'{"seq":8,"concept":"M6-2-u3-C8","difficulty":4,"kind":"mc","stem":"주스를 한 명에게 1.5 L씩 6명에게 나누어 주었더니 0.6 L가 남았어요. 처음 주스는 몇 L였나요?","options":[{"t":"9.6 L","correct":true},{"t":"9 L","mis":"M6-2-u3-X15"},{"t":"8.4 L","mis":"M6-2-u3-X20"},{"t":"10.5 L","mis":"M6-2-u3-X20"}],"explanation":["나누어 준 주스는 1.5 × 6 = 9 (L)예요.","남은 0.6 L를 더해요.","9 + 0.6 = 9.6 (L)예요."],"variant_rule":{"alt":[{"stem":"주스를 한 명에게 1.4 L씩 7명에게 나누어 주었더니 0.4 L가 남았어요. 처음 주스는 몇 L였나요?","options":[{"t":"10.2 L","correct":true},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"9.4 L","mis":"M6-2-u3-X20"},{"t":"11.2 L","mis":"M6-2-u3-X20"}],"explanation":["나누어 준 주스는 1.4 × 7 = 9.8 (L)예요.","남은 0.4 L를 더해요.","9.8 + 0.4 = 10.2 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#9','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',4,'essay','teacher','지역 먹거리 매장에서 당근주스 7.8 L를 사 왔어요. 친구들에게 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"지역 먹거리 매장에서 당근주스 7.8 L를 사 왔어요. 친구들에게 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 7.8 ÷ 1.8 = 4.333…이므로 4명에게 나누어 줄 수 있다(5명에게 주려면 9 L가 필요하다). 나누어 준 주스는 1.8 × 4 = 7.2 L이고 남는 주스는 7.8 − 7.2 = 0.6 L이다.","scoring_points":["4명을 구하고 자연수로 정한 까닭을 썼는가","1.8 × 4 = 7.2 L를 구했는가","7.8 − 7.2 = 0.6 L를 구했는가"]},"explanation":["7.8 ÷ 1.8 = 4.333… — 4명이에요.","나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 7.8 − 7.2 = 0.6 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_L08_challenge#10','math',6,2,'u3','L08','g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',4,'essay','teacher','당근주스가 10.2 L이고 한 명에게 1.4 L씩 나누어 줘요. 조건을 바꾼 이 문제에서 나누어 줄 수 있는 사람 수와 남는 양을 구하고, 남는 양을 몫의 소수 부분으로 읽으면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"당근주스가 10.2 L이고 한 명에게 1.4 L씩 나누어 줘요. 조건을 바꾼 이 문제에서 나누어 줄 수 있는 사람 수와 남는 양을 구하고, 남는 양을 몫의 소수 부분으로 읽으면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 10.2 ÷ 1.4 = 7.285…이므로 7명에게 나누어 줄 수 있고, 1.4 × 7 = 9.8 L를 나누어 주어 10.2 − 9.8 = 0.4 L가 남는다. 몫의 소수 부분 0.285…는 한 사람 몫(1.4 L)의 얼마인지를 뜻할 뿐 남는 양이 아니다.","scoring_points":["7명을 구했는가","0.4 L를 구했는가","몫의 소수 부분은 남는 양이 아니라는 까닭을 썼는가"]},"explanation":["10.2 ÷ 1.4 = 7.285… — 7명이에요.","남는 양은 10.2 − 9.8 = 0.4 (L)예요.","0.285…는 한 사람 몫의 얼마일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#1','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C1',1,'sa','auto','12 ÷ 3의 몫은 4예요. 두 수에 똑같이 10을 곱한 120 ÷ 30의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"12 ÷ 3의 몫은 4예요. 두 수에 똑같이 10을 곱한 120 ÷ 30의 몫은 얼마인가요?","answer":["4"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","120 ÷ 30은 12 ÷ 3의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 4예요."],"variant_rule":{"alt":[{"stem":"18 ÷ 6의 몫은 3이에요. 두 수에 똑같이 10을 곱한 180 ÷ 60의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","180 ÷ 60은 18 ÷ 6의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 3이에요."]},{"stem":"24 ÷ 8의 몫은 3이에요. 두 수에 똑같이 100을 곱한 2400 ÷ 800의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","2400 ÷ 800은 24 ÷ 8의 두 수에 100을 곱한 식이에요.","그래서 몫은 그대로 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#2','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C1',2,'mc','auto','빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":2,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 8","correct":true},{"t":"24 ÷ 0.8","mis":"M6-2-u3-X18"},{"t":"2.4 ÷ 8","mis":"M6-2-u3-X18"},{"t":"8 ÷ 24","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","2.4 cm는 24 mm, 0.8 cm는 8 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 24 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"824 ÷ 412","correct":true},{"t":"824 ÷ 4.12","mis":"M6-2-u3-X18"},{"t":"8.24 ÷ 412","mis":"M6-2-u3-X18"},{"t":"412 ÷ 824","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","8.24 m는 824 cm, 4.12 m는 412 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 824 ÷ 412예요."]},{"stem":"빨간 화분의 강낭콩 싹은 3.6 cm, 노란 화분의 강낭콩 싹은 1.2 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"36 ÷ 12","correct":true},{"t":"36 ÷ 1.2","mis":"M6-2-u3-X18"},{"t":"3.6 ÷ 12","mis":"M6-2-u3-X18"},{"t":"12 ÷ 36","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","3.6 cm는 36 mm, 1.2 cm는 12 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 36 ÷ 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#3','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C2',1,'mc','auto','8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":1,"kind":"mc","stem":"8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ ÷ ⟨21/10⟩","correct":true},{"t":"⟨84/10⟩ ÷ 2.1","mis":"M6-2-u3-X06"},{"t":"⟨84/10⟩ ÷ ⟨21/100⟩","mis":"M6-2-u3-X05"},{"t":"8.4 ÷ ⟨21/10⟩","mis":"M6-2-u3-X06"}],"explanation":["8.4는 ⟨84/10⟩, 2.1은 ⟨21/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨84/10⟩ ÷ ⟨21/10⟩이에요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨49/10⟩ ÷ ⟨7/10⟩","correct":true},{"t":"⟨49/10⟩ ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"⟨49/10⟩ ÷ ⟨7/100⟩","mis":"M6-2-u3-X05"},{"t":"4.9 ÷ ⟨7/10⟩","mis":"M6-2-u3-X06"}],"explanation":["4.9는 ⟨49/10⟩, 0.7은 ⟨7/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨49/10⟩ ÷ ⟨7/10⟩이에요."]},{"stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#4','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C2',2,'mc','auto','4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":4,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"49 ÷ 7","correct":true},{"t":"49 ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"4.9 ÷ 7","mis":"M6-2-u3-X01"},{"t":"49 ÷ 70","mis":"M6-2-u3-X05"}],"explanation":["4.9 = ⟨49/10⟩, 0.7 = ⟨7/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 49 ÷ 7이에요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"72 ÷ 6","correct":true},{"t":"72 ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"7.2 ÷ 6","mis":"M6-2-u3-X01"},{"t":"72 ÷ 60","mis":"M6-2-u3-X05"}],"explanation":["7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 72 ÷ 6이에요."]},{"stem":"2.24 ÷ 0.08을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"224 ÷ 8","correct":true},{"t":"224 ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"2.24 ÷ 8","mis":"M6-2-u3-X01"},{"t":"224 ÷ 80","mis":"M6-2-u3-X05"}],"explanation":["2.24 = ⟨224/100⟩, 0.08 = ⟨8/100⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 224 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#5','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C2',3,'ox','auto','8.4 ÷ 2.1을 계산할 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.',ARRAY['M6-2-u3-X06']::text[],true,'{"seq":5,"concept":"M6-2-u3-C2","difficulty":3,"kind":"ox","stem":"8.4 ÷ 2.1을 계산할 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"mis":"M6-2-u3-X06","explanation":["⟨84/10⟩ ÷ 2.1은 분자끼리 나눌 수 없어요.","2.1도 ⟨21/10⟩로 바꾸어야 해요.","⟨84/10⟩ ÷ ⟨21/10⟩로 분자끼리 나눠요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7을 계산할 때 4.9만 ⟨49/10⟩로 바꾸고 0.7은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨49/10⟩ ÷ 0.7은 분자끼리 나눌 수 없어요.","0.7도 ⟨7/10⟩로 바꾸어야 해요.","⟨49/10⟩ ÷ ⟨7/10⟩로 분자끼리 나눠요."]},{"stem":"2.24 ÷ 0.08을 계산할 때 2.24만 ⟨224/100⟩로 바꾸고 0.08은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨224/100⟩ ÷ 0.08은 분자끼리 나눌 수 없어요.","0.08도 ⟨8/100⟩로 바꾸어야 해요.","⟨224/100⟩ ÷ ⟨8/100⟩로 분자끼리 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#6','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',1,'sa','auto','8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.1이 정해요.","2.1이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.5가 정해요.","0.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"4.9 ÷ 0.7을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.7이 정해요.","0.7이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#7','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5의 몫은 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"},{"t":"0.072","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.6 ÷ 0.5는 36 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."],"variant_rule":{"alt":[{"stem":"4.5 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.5 ÷ 0.6은 45 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]},{"stem":"6.3 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 1.4는 63 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#8','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',3,'mc','auto','3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02','M6-2-u3-X04']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5는 36 ÷ 5 = 7.2예요.","0.72는 7.2보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."],"variant_rule":{"alt":[{"stem":"4.5 ÷ 0.6의 몫을 0.75라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["4.5 ÷ 0.6은 45 ÷ 6 = 7.5예요.","0.75는 7.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]},{"stem":"6.3 ÷ 1.4의 몫을 0.45라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["6.3 ÷ 1.4는 63 ÷ 14 = 4.5예요.","0.45는 4.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#9','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C4',1,'sa','auto','2.24 ÷ 0.08을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"2.24 ÷ 0.08을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.08이 정해요.","0.08이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.16을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.16이 정해요.","0.16이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]},{"stem":"6.54 ÷ 0.06을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.06이 정해요.","0.06이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#10','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C4',2,'mc','auto','0.56 ÷ 0.16의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":10,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"0.56 ÷ 0.16의 몫은 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"0.35","mis":"M6-2-u3-X03"},{"t":"35","mis":"M6-2-u3-X04"},{"t":"0.035","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.16이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.56 ÷ 0.16은 56 ÷ 16이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 3.5예요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14의 몫은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"0.55","mis":"M6-2-u3-X03"},{"t":"55","mis":"M6-2-u3-X04"},{"t":"0.055","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.14가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.77 ÷ 0.14는 77 ÷ 14가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 5.5예요."]},{"stem":"6.54 ÷ 0.06의 몫은 얼마인가요?","options":[{"t":"109","correct":true},{"t":"10.9","mis":"M6-2-u3-X03"},{"t":"1090","mis":"M6-2-u3-X04"},{"t":"1.09","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.54 ÷ 0.06은 654 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","654 ÷ 6 = 109예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#11','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C4',3,'mc','auto','0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":11,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/100⟩ ÷ ⟨14/100⟩","correct":true},{"t":"⟨77/100⟩ ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"⟨77/100⟩ ÷ ⟨14/10⟩","mis":"M6-2-u3-X05"},{"t":"0.77 ÷ ⟨14/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.77은 ⟨77/100⟩, 0.14는 ⟨14/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/100⟩ ÷ ⟨14/100⟩예요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."]},{"stem":"6.54 ÷ 0.06을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨654/100⟩ ÷ ⟨6/100⟩","correct":true},{"t":"⟨654/100⟩ ÷ 0.06","mis":"M6-2-u3-X06"},{"t":"⟨654/100⟩ ÷ ⟨6/10⟩","mis":"M6-2-u3-X05"},{"t":"6.54 ÷ ⟨6/100⟩","mis":"M6-2-u3-X06"}],"explanation":["6.54는 ⟨654/100⟩, 0.06은 ⟨6/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨654/100⟩ ÷ ⟨6/100⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#12','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',1,'mc','auto','5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":12,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"540","correct":true},{"t":"54","mis":"M6-2-u3-X07"},{"t":"5.40","mis":"M6-2-u3-X07"},{"t":"5400","mis":"M6-2-u3-X02"}],"explanation":["5.4의 소수점을 한 칸 옮기면 54예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 540이 돼요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.21에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"840","correct":true},{"t":"84","mis":"M6-2-u3-X07"},{"t":"8.40","mis":"M6-2-u3-X07"},{"t":"8400","mis":"M6-2-u3-X02"}],"explanation":["8.4의 소수점을 한 칸 옮기면 84예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 840이 돼요."]},{"stem":"6.3 ÷ 0.42에서 6.3의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"630","correct":true},{"t":"63","mis":"M6-2-u3-X07"},{"t":"6.30","mis":"M6-2-u3-X07"},{"t":"6300","mis":"M6-2-u3-X02"}],"explanation":["6.3의 소수점을 한 칸 옮기면 63이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 630이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#13','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',2,'sa','auto','5.4 ÷ 0.45의 몫은 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"5.4 ÷ 0.45의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."]},{"stem":"18.3 ÷ 0.3의 몫은 얼마인가요?","answer":["61"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","18.3 ÷ 0.3은 183 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","183 ÷ 3 = 61이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#14','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',4,'mc','auto','□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X02']::text[],true,'{"seq":14,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"0.54","mis":"M6-2-u3-X03"},{"t":"54","mis":"M6-2-u3-X04"},{"t":"540","mis":"M6-2-u3-X02"}],"explanation":["□ = 12 × 0.45예요.","12 × 0.45 = 5.4예요.","5.4 ÷ 0.45 = 12로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 2.4 = 3.6이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.64","correct":true},{"t":"0.864","mis":"M6-2-u3-X03"},{"t":"86.4","mis":"M6-2-u3-X04"},{"t":"864","mis":"M6-2-u3-X02"}],"explanation":["□ = 3.6 × 2.4예요.","3.6 × 2.4 = 8.64예요.","8.64 ÷ 2.4 = 3.6으로 맞아요."]},{"stem":"□ ÷ 0.21 = 40이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.4","correct":true},{"t":"0.84","mis":"M6-2-u3-X03"},{"t":"84","mis":"M6-2-u3-X04"},{"t":"840","mis":"M6-2-u3-X02"}],"explanation":["□ = 40 × 0.21이에요.","40 × 0.21 = 8.4예요.","8.4 ÷ 0.21 = 40으로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#15','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":15,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 한 수만 바뀌어 몫이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"8.64 ÷ 0.24","correct":true},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"86.4 ÷ 24","mis":"M6-2-u3-X19"},{"t":"864 ÷ 240","mis":"M6-2-u3-X19"}],"explanation":["8.64 ÷ 2.4, 86.4 ÷ 24, 864 ÷ 240은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.6이에요.","8.64 ÷ 0.24는 한 수만 바뀌어 몫이 달라요."]},{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"5.4 ÷ 4.5","correct":true},{"t":"5.4 ÷ 0.45","mis":"M6-2-u3-X19"},{"t":"540 ÷ 45","mis":"M6-2-u3-X19"},{"t":"54 ÷ 4.5","mis":"M6-2-u3-X19"}],"explanation":["5.4 ÷ 0.45, 540 ÷ 45, 54 ÷ 4.5는 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 12예요.","5.4 ÷ 4.5는 한 수만 바뀌어 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#16','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',1,'sa','auto','8 ÷ 1.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"8 ÷ 1.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."],"variant_rule":{"alt":[{"stem":"16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["나누어지는 수 16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."]},{"stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["나누어지는 수 7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#17','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',2,'mc','auto','5 ÷ 0.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":17,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"5 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"12.5","correct":true},{"t":"1.25","mis":"M6-2-u3-X03"},{"t":"125","mis":"M6-2-u3-X04"},{"t":"0.125","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 5는 5.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","5 ÷ 0.4는 50 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 12.5예요."],"variant_rule":{"alt":[{"stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.2가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.2는 90 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]},{"stem":"7 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"17.5","correct":true},{"t":"1.75","mis":"M6-2-u3-X03"},{"t":"175","mis":"M6-2-u3-X04"},{"t":"0.175","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 7은 7.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 0.4는 70 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 17.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#18','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',3,'ox','auto','16 ÷ 0.25의 몫은 16보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":18,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["16 ÷ 0.25 = 64예요.","64는 16보다 커요.","1보다 작은 수로 나누면 몫이 커져요."],"variant_rule":{"alt":[{"stem":"31 ÷ 0.62의 몫은 31보다 작아요.","answer":"X","reason_options":[{"t":"0.62는 1보다 작아서 31 안에 31번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["31 ÷ 0.62 = 50이에요.","50은 31보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]},{"stem":"9 ÷ 0.6의 몫은 9보다 작아요.","answer":"X","reason_options":[{"t":"0.6은 1보다 작아서 9 안에 9번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["9 ÷ 0.6 = 15예요.","15는 9보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#19','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',4,'mc','auto','수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X09','M6-2-u3-X19']::text[],true,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6.52","correct":true},{"t":"2.56","mis":"M6-2-u3-X09"},{"t":"5.26","mis":"M6-2-u3-X09"},{"t":"6.25","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 6.52예요.","그래서 □는 6.52예요."],"variant_rule":{"alt":[{"stem":"수 카드 3, 7, 4를 한 번씩만 써서 20 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"3.47","correct":true},{"t":"7.43","mis":"M6-2-u3-X09"},{"t":"4.37","mis":"M6-2-u3-X09"},{"t":"3.74","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 3.47이에요.","그래서 □는 3.47이에요."]},{"stem":"수 카드 1, 8, 3을 한 번씩만 써서 12.6 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"8.31","correct":true},{"t":"1.38","mis":"M6-2-u3-X09"},{"t":"3.18","mis":"M6-2-u3-X09"},{"t":"8.13","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 8.31이에요.","그래서 □는 8.31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#20','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C7',1,'mc','auto','1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":20,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.17","correct":true},{"t":"0.16","mis":"M6-2-u3-X11"},{"t":"0.167","mis":"M6-2-u3-X12"},{"t":"0.2","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.29","correct":true},{"t":"0.28","mis":"M6-2-u3-X11"},{"t":"0.286","mis":"M6-2-u3-X12"},{"t":"0.3","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 0.29예요."]},{"stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.77","correct":true},{"t":"4.76","mis":"M6-2-u3-X11"},{"t":"4.769","mis":"M6-2-u3-X12"},{"t":"4.8","mis":"M6-2-u3-X12"}],"explanation":["6.2 ÷ 1.3 = 4.7692…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 4.77이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#21','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["2"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 첫째 자리의 한 자리 아래는 소수 둘째 자리예요.","그래서 소수 둘째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 일의 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["1"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","일의 자리의 한 자리 아래는 소수 첫째 자리예요.","그래서 소수 첫째 자리 숫자를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#22','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C7',3,'mc','auto','1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":22,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 0.17이에요."],"variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 0.3이에요."]},{"stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 4.76이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["6.2 ÷ 1.3 = 4.769…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 4.77이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#23','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',1,'sa','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L, 5번 주려면 9 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L, 8번 주려면 11.2 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["9.6 ÷ 1.5를 계산하면 6.4예요.","1.5 L씩 6번 주면 9 L, 7번 주려면 10.5 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#24','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]},{"stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.4 L","mis":"M6-2-u3-X14"},{"t":"9 L","mis":"M6-2-u3-X15"},{"t":"1.5 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.5 × 6 = 9 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","9.6 − 9 = 0.6 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_a#25','math',6,2,'u3','','g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',4,'essay','teacher','주스 11.3 L를 한 명에게 2.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"주스 11.3 L를 한 명에게 2.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 11.3 ÷ 2.5 = 4.52이므로 4명에게 나누어 줄 수 있다. 나누어 준 주스는 2.5 × 4 = 10 L이고 남는 주스는 11.3 − 10 = 1.3 L이다. 몫을 반올림해 5명으로 하면 12.5 L가 있어야 하는데 모자라므로 반올림하면 안 된다.","scoring_points":["4명을 구했는가","남는 주스 1.3 L를 구했는가","반올림하면 주스가 모자란다는 까닭을 썼는가"]},"explanation":["11.3 ÷ 2.5 = 4.52 — 4명이에요.","남는 양은 11.3 − 10 = 1.3 (L)예요.","5명이면 12.5 L가 필요해 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#1','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C1',1,'sa','auto','18 ÷ 6의 몫은 3이에요. 두 수에 똑같이 10을 곱한 180 ÷ 60의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"18 ÷ 6의 몫은 3이에요. 두 수에 똑같이 10을 곱한 180 ÷ 60의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","180 ÷ 60은 18 ÷ 6의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 3이에요."],"variant_rule":{"alt":[{"stem":"24 ÷ 8의 몫은 3이에요. 두 수에 똑같이 100을 곱한 2400 ÷ 800의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","2400 ÷ 800은 24 ÷ 8의 두 수에 100을 곱한 식이에요.","그래서 몫은 그대로 3이에요."]},{"stem":"35 ÷ 7의 몫은 5예요. 두 수에 똑같이 10을 곱한 350 ÷ 70의 몫은 얼마인가요?","answer":["5"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","350 ÷ 70은 35 ÷ 7의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#2','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C1',2,'mc','auto','엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":2,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"824 ÷ 412","correct":true},{"t":"824 ÷ 4.12","mis":"M6-2-u3-X18"},{"t":"8.24 ÷ 412","mis":"M6-2-u3-X18"},{"t":"412 ÷ 824","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","8.24 m는 824 cm, 4.12 m는 412 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 824 ÷ 412예요."],"variant_rule":{"alt":[{"stem":"빨간 화분의 강낭콩 싹은 3.6 cm, 노란 화분의 강낭콩 싹은 1.2 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"36 ÷ 12","correct":true},{"t":"36 ÷ 1.2","mis":"M6-2-u3-X18"},{"t":"3.6 ÷ 12","mis":"M6-2-u3-X18"},{"t":"12 ÷ 36","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","3.6 cm는 36 mm, 1.2 cm는 12 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 36 ÷ 12예요."]},{"stem":"큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"135 ÷ 45","correct":true},{"t":"135 ÷ 0.45","mis":"M6-2-u3-X18"},{"t":"1.35 ÷ 45","mis":"M6-2-u3-X18"},{"t":"45 ÷ 135","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","1.35 m는 135 cm, 0.45 m는 45 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 135 ÷ 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#3','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C2',1,'mc','auto','4.9 ÷ 0.7을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":1,"kind":"mc","stem":"4.9 ÷ 0.7을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨49/10⟩ ÷ ⟨7/10⟩","correct":true},{"t":"⟨49/10⟩ ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"⟨49/10⟩ ÷ ⟨7/100⟩","mis":"M6-2-u3-X05"},{"t":"4.9 ÷ ⟨7/10⟩","mis":"M6-2-u3-X06"}],"explanation":["4.9는 ⟨49/10⟩, 0.7은 ⟨7/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨49/10⟩ ÷ ⟨7/10⟩이에요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."]},{"stem":"7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨72/10⟩ ÷ ⟨6/10⟩","correct":true},{"t":"⟨72/10⟩ ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"⟨72/10⟩ ÷ ⟨6/100⟩","mis":"M6-2-u3-X05"},{"t":"7.2 ÷ ⟨6/10⟩","mis":"M6-2-u3-X06"}],"explanation":["7.2는 ⟨72/10⟩, 0.6은 ⟨6/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨72/10⟩ ÷ ⟨6/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#4','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C2',2,'mc','auto','7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":4,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"72 ÷ 6","correct":true},{"t":"72 ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"7.2 ÷ 6","mis":"M6-2-u3-X01"},{"t":"72 ÷ 60","mis":"M6-2-u3-X05"}],"explanation":["7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 72 ÷ 6이에요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"224 ÷ 8","correct":true},{"t":"224 ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"2.24 ÷ 8","mis":"M6-2-u3-X01"},{"t":"224 ÷ 80","mis":"M6-2-u3-X05"}],"explanation":["2.24 = ⟨224/100⟩, 0.08 = ⟨8/100⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 224 ÷ 8이에요."]},{"stem":"0.56 ÷ 0.14를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"56 ÷ 14","correct":true},{"t":"56 ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"0.56 ÷ 14","mis":"M6-2-u3-X01"},{"t":"56 ÷ 140","mis":"M6-2-u3-X05"}],"explanation":["0.56 = ⟨56/100⟩, 0.14 = ⟨14/100⟩예요.","분모가 같으니 분자끼리 나눠요.","그래서 56 ÷ 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#5','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C2',3,'ox','auto','4.9 ÷ 0.7을 계산할 때 4.9만 ⟨49/10⟩로 바꾸고 0.7은 소수 그대로 두어도 분자끼리 나눌 수 있어요.',ARRAY['M6-2-u3-X06']::text[],true,'{"seq":5,"concept":"M6-2-u3-C2","difficulty":3,"kind":"ox","stem":"4.9 ÷ 0.7을 계산할 때 4.9만 ⟨49/10⟩로 바꾸고 0.7은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"mis":"M6-2-u3-X06","explanation":["⟨49/10⟩ ÷ 0.7은 분자끼리 나눌 수 없어요.","0.7도 ⟨7/10⟩로 바꾸어야 해요.","⟨49/10⟩ ÷ ⟨7/10⟩로 분자끼리 나눠요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 계산할 때 2.24만 ⟨224/100⟩로 바꾸고 0.08은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨224/100⟩ ÷ 0.08은 분자끼리 나눌 수 없어요.","0.08도 ⟨8/100⟩로 바꾸어야 해요.","⟨224/100⟩ ÷ ⟨8/100⟩로 분자끼리 나눠요."]},{"stem":"7.2 ÷ 0.6을 계산할 때 7.2만 ⟨72/10⟩로 바꾸고 0.6은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨72/10⟩ ÷ 0.6은 분자끼리 나눌 수 없어요.","0.6도 ⟨6/10⟩으로 바꾸어야 해요.","⟨72/10⟩ ÷ ⟨6/10⟩으로 분자끼리 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#6','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',1,'sa','auto','3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.5가 정해요.","0.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.7이 정해요.","0.7이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"7.2 ÷ 0.6을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.6이 정해요.","0.6이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#7','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',2,'mc','auto','4.5 ÷ 0.6의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"4.5 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.5 ÷ 0.6은 45 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."],"variant_rule":{"alt":[{"stem":"6.3 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 1.4는 63 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]},{"stem":"5.1 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"8.5","correct":true},{"t":"0.85","mis":"M6-2-u3-X03"},{"t":"85","mis":"M6-2-u3-X04"},{"t":"0.085","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.1 ÷ 0.6은 51 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 8.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#8','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',3,'mc','auto','4.5 ÷ 0.6의 몫을 0.75라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02','M6-2-u3-X04']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"4.5 ÷ 0.6의 몫을 0.75라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["4.5 ÷ 0.6은 45 ÷ 6 = 7.5예요.","0.75는 7.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."],"variant_rule":{"alt":[{"stem":"6.3 ÷ 1.4의 몫을 0.45라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["6.3 ÷ 1.4는 63 ÷ 14 = 4.5예요.","0.45는 4.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]},{"stem":"5.1 ÷ 0.6의 몫을 0.85라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["5.1 ÷ 0.6은 51 ÷ 6 = 8.5예요.","0.85는 8.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#9','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C4',1,'sa','auto','0.56 ÷ 0.16을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"0.56 ÷ 0.16을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.16이 정해요.","0.16이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"6.54 ÷ 0.06을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.06이 정해요.","0.06이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]},{"stem":"0.77 ÷ 0.14를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.14가 정해요.","0.14가 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#10','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C4',2,'mc','auto','0.77 ÷ 0.14의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":10,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"0.77 ÷ 0.14의 몫은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"0.55","mis":"M6-2-u3-X03"},{"t":"55","mis":"M6-2-u3-X04"},{"t":"0.055","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.14가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.77 ÷ 0.14는 77 ÷ 14가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 5.5예요."],"variant_rule":{"alt":[{"stem":"6.54 ÷ 0.06의 몫은 얼마인가요?","options":[{"t":"109","correct":true},{"t":"10.9","mis":"M6-2-u3-X03"},{"t":"1090","mis":"M6-2-u3-X04"},{"t":"1.09","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.54 ÷ 0.06은 654 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","654 ÷ 6 = 109예요."]},{"stem":"1.17 ÷ 0.26의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.26이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.17 ÷ 0.26은 117 ÷ 26이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#11','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C4',3,'mc','auto','2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":11,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."],"variant_rule":{"alt":[{"stem":"6.54 ÷ 0.06을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨654/100⟩ ÷ ⟨6/100⟩","correct":true},{"t":"⟨654/100⟩ ÷ 0.06","mis":"M6-2-u3-X06"},{"t":"⟨654/100⟩ ÷ ⟨6/10⟩","mis":"M6-2-u3-X05"},{"t":"6.54 ÷ ⟨6/100⟩","mis":"M6-2-u3-X06"}],"explanation":["6.54는 ⟨654/100⟩, 0.06은 ⟨6/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨654/100⟩ ÷ ⟨6/100⟩이에요."]},{"stem":"0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨56/100⟩ ÷ ⟨16/100⟩","correct":true},{"t":"⟨56/100⟩ ÷ 0.16","mis":"M6-2-u3-X06"},{"t":"⟨56/100⟩ ÷ ⟨16/10⟩","mis":"M6-2-u3-X05"},{"t":"0.56 ÷ ⟨16/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.56은 ⟨56/100⟩, 0.16은 ⟨16/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨56/100⟩ ÷ ⟨16/100⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#12','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',1,'mc','auto','8.4 ÷ 0.21에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":12,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"8.4 ÷ 0.21에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"840","correct":true},{"t":"84","mis":"M6-2-u3-X07"},{"t":"8.40","mis":"M6-2-u3-X07"},{"t":"8400","mis":"M6-2-u3-X02"}],"explanation":["8.4의 소수점을 한 칸 옮기면 84예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 840이 돼요."],"variant_rule":{"alt":[{"stem":"6.3 ÷ 0.42에서 6.3의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"630","correct":true},{"t":"63","mis":"M6-2-u3-X07"},{"t":"6.30","mis":"M6-2-u3-X07"},{"t":"6300","mis":"M6-2-u3-X02"}],"explanation":["6.3의 소수점을 한 칸 옮기면 63이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 630이 돼요."]},{"stem":"9.6 ÷ 0.32에서 9.6의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"960","correct":true},{"t":"96","mis":"M6-2-u3-X07"},{"t":"9.60","mis":"M6-2-u3-X07"},{"t":"9600","mis":"M6-2-u3-X02"}],"explanation":["9.6의 소수점을 한 칸 옮기면 96이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 960이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#13','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',2,'sa','auto','8.4 ÷ 0.21의 몫은 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."],"variant_rule":{"alt":[{"stem":"18.3 ÷ 0.3의 몫은 얼마인가요?","answer":["61"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","18.3 ÷ 0.3은 183 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","183 ÷ 3 = 61이에요."]},{"stem":"6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#14','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',4,'mc','auto','□ ÷ 2.4 = 3.6이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X02']::text[],true,'{"seq":14,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"□ ÷ 2.4 = 3.6이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.64","correct":true},{"t":"0.864","mis":"M6-2-u3-X03"},{"t":"86.4","mis":"M6-2-u3-X04"},{"t":"864","mis":"M6-2-u3-X02"}],"explanation":["□ = 3.6 × 2.4예요.","3.6 × 2.4 = 8.64예요.","8.64 ÷ 2.4 = 3.6으로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.21 = 40이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.4","correct":true},{"t":"0.84","mis":"M6-2-u3-X03"},{"t":"84","mis":"M6-2-u3-X04"},{"t":"840","mis":"M6-2-u3-X02"}],"explanation":["□ = 40 × 0.21이에요.","40 × 0.21 = 8.4예요.","8.4 ÷ 0.21 = 40으로 맞아요."]},{"stem":"□ ÷ 1.5 = 1.7이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2.55","correct":true},{"t":"0.255","mis":"M6-2-u3-X03"},{"t":"25.5","mis":"M6-2-u3-X04"},{"t":"255","mis":"M6-2-u3-X02"}],"explanation":["□ = 1.7 × 1.5예요.","1.7 × 1.5 = 2.55예요.","2.55 ÷ 1.5 = 1.7로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#15','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":15,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"8.64 ÷ 0.24","correct":true},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"86.4 ÷ 24","mis":"M6-2-u3-X19"},{"t":"864 ÷ 240","mis":"M6-2-u3-X19"}],"explanation":["8.64 ÷ 2.4, 86.4 ÷ 24, 864 ÷ 240은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.6이에요.","8.64 ÷ 0.24는 한 수만 바뀌어 몫이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"5.4 ÷ 4.5","correct":true},{"t":"5.4 ÷ 0.45","mis":"M6-2-u3-X19"},{"t":"540 ÷ 45","mis":"M6-2-u3-X19"},{"t":"54 ÷ 4.5","mis":"M6-2-u3-X19"}],"explanation":["5.4 ÷ 0.45, 540 ÷ 45, 54 ÷ 4.5는 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 12예요.","5.4 ÷ 4.5는 한 수만 바뀌어 몫이 달라요."]},{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"2.55 ÷ 0.15","correct":true},{"t":"2.55 ÷ 1.5","mis":"M6-2-u3-X19"},{"t":"25.5 ÷ 15","mis":"M6-2-u3-X19"},{"t":"255 ÷ 150","mis":"M6-2-u3-X19"}],"explanation":["2.55 ÷ 1.5, 25.5 ÷ 15, 255 ÷ 150은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 1.7이에요.","2.55 ÷ 0.15는 한 수만 바뀌어 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#16','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',1,'sa','auto','16 ÷ 0.25의 몫은 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["나누어지는 수 16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["나누어지는 수 7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."]},{"stem":"18 ÷ 3.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 18은 18.0과 같아요 — 나누는 수 3.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","18 ÷ 3.6은 180 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","180 ÷ 36 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#17','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',2,'mc','auto','9 ÷ 1.2의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":17,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.2가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.2는 90 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"17.5","correct":true},{"t":"1.75","mis":"M6-2-u3-X03"},{"t":"175","mis":"M6-2-u3-X04"},{"t":"0.175","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 7은 7.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 0.4는 70 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 17.5예요."]},{"stem":"2 ÷ 0.8의 몫은 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"0.25","mis":"M6-2-u3-X03"},{"t":"25","mis":"M6-2-u3-X04"},{"t":"0.025","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 2는 2.0과 같아요 — 나누는 수 0.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","2 ÷ 0.8은 20 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#18','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',3,'ox','auto','31 ÷ 0.62의 몫은 31보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":18,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"31 ÷ 0.62의 몫은 31보다 작아요.","answer":"X","reason_options":[{"t":"0.62는 1보다 작아서 31 안에 31번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["31 ÷ 0.62 = 50이에요.","50은 31보다 커요.","1보다 작은 수로 나누면 몫이 커져요."],"variant_rule":{"alt":[{"stem":"9 ÷ 0.6의 몫은 9보다 작아요.","answer":"X","reason_options":[{"t":"0.6은 1보다 작아서 9 안에 9번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["9 ÷ 0.6 = 15예요.","15는 9보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]},{"stem":"12 ÷ 0.8의 몫은 12보다 작아요.","answer":"X","reason_options":[{"t":"0.8은 1보다 작아서 12 안에 12번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["12 ÷ 0.8 = 15예요.","15는 12보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#19','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',4,'mc','auto','수 카드 3, 7, 4를 한 번씩만 써서 20 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X09','M6-2-u3-X19']::text[],true,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"수 카드 3, 7, 4를 한 번씩만 써서 20 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"3.47","correct":true},{"t":"7.43","mis":"M6-2-u3-X09"},{"t":"4.37","mis":"M6-2-u3-X09"},{"t":"3.74","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 3.47이에요.","그래서 □는 3.47이에요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 8, 3을 한 번씩만 써서 12.6 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"8.31","correct":true},{"t":"1.38","mis":"M6-2-u3-X09"},{"t":"3.18","mis":"M6-2-u3-X09"},{"t":"8.13","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 8.31이에요.","그래서 □는 8.31이에요."]},{"stem":"수 카드 5, 2, 9를 한 번씩만 써서 30 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"2.59","correct":true},{"t":"9.52","mis":"M6-2-u3-X09"},{"t":"5.29","mis":"M6-2-u3-X09"},{"t":"2.95","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 2.59예요.","그래서 □는 2.59예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#20','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C7',1,'mc','auto','2 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":20,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"2 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.29","correct":true},{"t":"0.28","mis":"M6-2-u3-X11"},{"t":"0.286","mis":"M6-2-u3-X12"},{"t":"0.3","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 0.29예요."],"variant_rule":{"alt":[{"stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.77","correct":true},{"t":"4.76","mis":"M6-2-u3-X11"},{"t":"4.769","mis":"M6-2-u3-X12"},{"t":"4.8","mis":"M6-2-u3-X12"}],"explanation":["6.2 ÷ 1.3 = 4.7692…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 4.77이에요."]},{"stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#21','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["2"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 첫째 자리의 한 자리 아래는 소수 둘째 자리예요.","그래서 소수 둘째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 일의 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["1"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","일의 자리의 한 자리 아래는 소수 첫째 자리예요.","그래서 소수 첫째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#22','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C7',3,'mc','auto','2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":22,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 0.3이에요."],"variant_rule":{"alt":[{"stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 4.76이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["6.2 ÷ 1.3 = 4.769…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 4.77이에요."]},{"stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["3.38 ÷ 0.9 = 3.755…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 3.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#23','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',1,'sa','auto','당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L, 8번 주려면 11.2 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["9.6 ÷ 1.5를 계산하면 6.4예요.","1.5 L씩 6번 주면 9 L, 7번 주려면 10.5 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["15.2 ÷ 2.4를 계산하면 6.333…이에요.","2.4 L씩 6번 주면 14.4 L, 7번 주려면 16.8 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#24','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.4 L","mis":"M6-2-u3-X14"},{"t":"9 L","mis":"M6-2-u3-X15"},{"t":"1.5 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.5 × 6 = 9 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","9.6 − 9 = 0.6 (L)예요."]},{"stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.9 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"12.8 L","mis":"M6-2-u3-X15"},{"t":"1.6 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.6 × 8 = 12.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","13.7 − 12.8 = 0.9 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_b#25','math',6,2,'u3','','g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',4,'essay','teacher','주스 13.7 L를 한 명에게 1.6 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"주스 13.7 L를 한 명에게 1.6 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 13.7 ÷ 1.6 = 8.56…이므로 8명에게 나누어 줄 수 있다. 나누어 준 주스는 1.6 × 8 = 12.8 L이고 남는 주스는 13.7 − 12.8 = 0.9 L이다. 몫을 반올림해 9명으로 하면 14.4 L가 있어야 하는데 모자라므로 반올림하면 안 된다.","scoring_points":["8명을 구했는가","남는 주스 0.9 L를 구했는가","반올림하면 주스가 모자란다는 까닭을 썼는가"]},"explanation":["13.7 ÷ 1.6 = 8.56… — 8명이에요.","남는 양은 13.7 − 12.8 = 0.9 (L)예요.","9명이면 14.4 L가 필요해 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#1','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C1',1,'sa','auto','24 ÷ 8의 몫은 3이에요. 두 수에 똑같이 100을 곱한 2400 ÷ 800의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"24 ÷ 8의 몫은 3이에요. 두 수에 똑같이 100을 곱한 2400 ÷ 800의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","2400 ÷ 800은 24 ÷ 8의 두 수에 100을 곱한 식이에요.","그래서 몫은 그대로 3이에요."],"variant_rule":{"alt":[{"stem":"35 ÷ 7의 몫은 5예요. 두 수에 똑같이 10을 곱한 350 ÷ 70의 몫은 얼마인가요?","answer":["5"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","350 ÷ 70은 35 ÷ 7의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 5예요."]},{"stem":"12 ÷ 3의 몫은 4예요. 두 수에 똑같이 10을 곱한 120 ÷ 30의 몫은 얼마인가요?","answer":["4"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","120 ÷ 30은 12 ÷ 3의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#2','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C1',2,'mc','auto','빨간 화분의 강낭콩 싹은 3.6 cm, 노란 화분의 강낭콩 싹은 1.2 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":2,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"빨간 화분의 강낭콩 싹은 3.6 cm, 노란 화분의 강낭콩 싹은 1.2 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"36 ÷ 12","correct":true},{"t":"36 ÷ 1.2","mis":"M6-2-u3-X18"},{"t":"3.6 ÷ 12","mis":"M6-2-u3-X18"},{"t":"12 ÷ 36","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","3.6 cm는 36 mm, 1.2 cm는 12 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 36 ÷ 12예요."],"variant_rule":{"alt":[{"stem":"큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"135 ÷ 45","correct":true},{"t":"135 ÷ 0.45","mis":"M6-2-u3-X18"},{"t":"1.35 ÷ 45","mis":"M6-2-u3-X18"},{"t":"45 ÷ 135","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","1.35 m는 135 cm, 0.45 m는 45 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 135 ÷ 45예요."]},{"stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 8","correct":true},{"t":"24 ÷ 0.8","mis":"M6-2-u3-X18"},{"t":"2.4 ÷ 8","mis":"M6-2-u3-X18"},{"t":"8 ÷ 24","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","2.4 cm는 24 mm, 0.8 cm는 8 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 24 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#3','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C2',1,'mc','auto','2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":1,"kind":"mc","stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨72/10⟩ ÷ ⟨6/10⟩","correct":true},{"t":"⟨72/10⟩ ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"⟨72/10⟩ ÷ ⟨6/100⟩","mis":"M6-2-u3-X05"},{"t":"7.2 ÷ ⟨6/10⟩","mis":"M6-2-u3-X06"}],"explanation":["7.2는 ⟨72/10⟩, 0.6은 ⟨6/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨72/10⟩ ÷ ⟨6/10⟩이에요."]},{"stem":"8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ ÷ ⟨21/10⟩","correct":true},{"t":"⟨84/10⟩ ÷ 2.1","mis":"M6-2-u3-X06"},{"t":"⟨84/10⟩ ÷ ⟨21/100⟩","mis":"M6-2-u3-X05"},{"t":"8.4 ÷ ⟨21/10⟩","mis":"M6-2-u3-X06"}],"explanation":["8.4는 ⟨84/10⟩, 2.1은 ⟨21/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨84/10⟩ ÷ ⟨21/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#4','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C2',2,'mc','auto','2.24 ÷ 0.08을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":4,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"2.24 ÷ 0.08을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"224 ÷ 8","correct":true},{"t":"224 ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"2.24 ÷ 8","mis":"M6-2-u3-X01"},{"t":"224 ÷ 80","mis":"M6-2-u3-X05"}],"explanation":["2.24 = ⟨224/100⟩, 0.08 = ⟨8/100⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 224 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.14를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"56 ÷ 14","correct":true},{"t":"56 ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"0.56 ÷ 14","mis":"M6-2-u3-X01"},{"t":"56 ÷ 140","mis":"M6-2-u3-X05"}],"explanation":["0.56 = ⟨56/100⟩, 0.14 = ⟨14/100⟩예요.","분모가 같으니 분자끼리 나눠요.","그래서 56 ÷ 14예요."]},{"stem":"4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"49 ÷ 7","correct":true},{"t":"49 ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"4.9 ÷ 7","mis":"M6-2-u3-X01"},{"t":"49 ÷ 70","mis":"M6-2-u3-X05"}],"explanation":["4.9 = ⟨49/10⟩, 0.7 = ⟨7/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 49 ÷ 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#5','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C2',3,'ox','auto','2.24 ÷ 0.08을 계산할 때 2.24만 ⟨224/100⟩로 바꾸고 0.08은 소수 그대로 두어도 분자끼리 나눌 수 있어요.',ARRAY['M6-2-u3-X06']::text[],true,'{"seq":5,"concept":"M6-2-u3-C2","difficulty":3,"kind":"ox","stem":"2.24 ÷ 0.08을 계산할 때 2.24만 ⟨224/100⟩로 바꾸고 0.08은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"mis":"M6-2-u3-X06","explanation":["⟨224/100⟩ ÷ 0.08은 분자끼리 나눌 수 없어요.","0.08도 ⟨8/100⟩로 바꾸어야 해요.","⟨224/100⟩ ÷ ⟨8/100⟩로 분자끼리 나눠요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 계산할 때 7.2만 ⟨72/10⟩로 바꾸고 0.6은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨72/10⟩ ÷ 0.6은 분자끼리 나눌 수 없어요.","0.6도 ⟨6/10⟩으로 바꾸어야 해요.","⟨72/10⟩ ÷ ⟨6/10⟩으로 분자끼리 나눠요."]},{"stem":"8.4 ÷ 2.1을 계산할 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨84/10⟩ ÷ 2.1은 분자끼리 나눌 수 없어요.","2.1도 ⟨21/10⟩로 바꾸어야 해요.","⟨84/10⟩ ÷ ⟨21/10⟩로 분자끼리 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#6','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C3',1,'sa','auto','4.9 ÷ 0.7을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"4.9 ÷ 0.7을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.7이 정해요.","0.7이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.6이 정해요.","0.6이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.1이 정해요.","2.1이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#7','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C3',2,'mc','auto','6.3 ÷ 1.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"6.3 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.3 ÷ 1.4는 63 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."],"variant_rule":{"alt":[{"stem":"5.1 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"8.5","correct":true},{"t":"0.85","mis":"M6-2-u3-X03"},{"t":"85","mis":"M6-2-u3-X04"},{"t":"0.085","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.1 ÷ 0.6은 51 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 8.5예요."]},{"stem":"3.6 ÷ 0.5의 몫은 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"},{"t":"0.072","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.6 ÷ 0.5는 36 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#8','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C3',3,'mc','auto','6.3 ÷ 1.4의 몫을 0.45라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02','M6-2-u3-X04']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"6.3 ÷ 1.4의 몫을 0.45라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["6.3 ÷ 1.4는 63 ÷ 14 = 4.5예요.","0.45는 4.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."],"variant_rule":{"alt":[{"stem":"5.1 ÷ 0.6의 몫을 0.85라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["5.1 ÷ 0.6은 51 ÷ 6 = 8.5예요.","0.85는 8.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]},{"stem":"3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5는 36 ÷ 5 = 7.2예요.","0.72는 7.2보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
