INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#10','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',2,'mc','auto','6.54 ÷ 0.06의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":10,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"6.54 ÷ 0.06의 몫은 얼마인가요?","options":[{"t":"109","correct":true},{"t":"10.9","mis":"M6-2-u3-X03"},{"t":"1090","mis":"M6-2-u3-X04"},{"t":"1.09","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.54 ÷ 0.06은 654 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","654 ÷ 6 = 109예요."],"variant_rule":{"alt":[{"stem":"1.17 ÷ 0.26의 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.045","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.26이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.17 ÷ 0.26은 117 ÷ 26이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 4.5예요."]},{"stem":"0.56 ÷ 0.16의 몫은 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"0.35","mis":"M6-2-u3-X03"},{"t":"35","mis":"M6-2-u3-X04"},{"t":"0.035","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.16이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.56 ÷ 0.16은 56 ÷ 16이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 3.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#11','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',3,'mc','auto','6.54 ÷ 0.06을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":11,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"6.54 ÷ 0.06을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨654/100⟩ ÷ ⟨6/100⟩","correct":true},{"t":"⟨654/100⟩ ÷ 0.06","mis":"M6-2-u3-X06"},{"t":"⟨654/100⟩ ÷ ⟨6/10⟩","mis":"M6-2-u3-X05"},{"t":"6.54 ÷ ⟨6/100⟩","mis":"M6-2-u3-X06"}],"explanation":["6.54는 ⟨654/100⟩, 0.06은 ⟨6/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨654/100⟩ ÷ ⟨6/100⟩이에요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨56/100⟩ ÷ ⟨16/100⟩","correct":true},{"t":"⟨56/100⟩ ÷ 0.16","mis":"M6-2-u3-X06"},{"t":"⟨56/100⟩ ÷ ⟨16/10⟩","mis":"M6-2-u3-X05"},{"t":"0.56 ÷ ⟨16/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.56은 ⟨56/100⟩, 0.16은 ⟨16/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨56/100⟩ ÷ ⟨16/100⟩이에요."]},{"stem":"0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/100⟩ ÷ ⟨14/100⟩","correct":true},{"t":"⟨77/100⟩ ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"⟨77/100⟩ ÷ ⟨14/10⟩","mis":"M6-2-u3-X05"},{"t":"0.77 ÷ ⟨14/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.77은 ⟨77/100⟩, 0.14는 ⟨14/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/100⟩ ÷ ⟨14/100⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#12','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',1,'mc','auto','6.3 ÷ 0.42에서 6.3의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":12,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"6.3 ÷ 0.42에서 6.3의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"630","correct":true},{"t":"63","mis":"M6-2-u3-X07"},{"t":"6.30","mis":"M6-2-u3-X07"},{"t":"6300","mis":"M6-2-u3-X02"}],"explanation":["6.3의 소수점을 한 칸 옮기면 63이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 630이 돼요."],"variant_rule":{"alt":[{"stem":"9.6 ÷ 0.32에서 9.6의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"960","correct":true},{"t":"96","mis":"M6-2-u3-X07"},{"t":"9.60","mis":"M6-2-u3-X07"},{"t":"9600","mis":"M6-2-u3-X02"}],"explanation":["9.6의 소수점을 한 칸 옮기면 96이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 960이 돼요."]},{"stem":"5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"540","correct":true},{"t":"54","mis":"M6-2-u3-X07"},{"t":"5.40","mis":"M6-2-u3-X07"},{"t":"5400","mis":"M6-2-u3-X02"}],"explanation":["5.4의 소수점을 한 칸 옮기면 54예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 540이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#13','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',2,'sa','auto','18.3 ÷ 0.3의 몫은 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"18.3 ÷ 0.3의 몫은 얼마인가요?","answer":["61"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","18.3 ÷ 0.3은 183 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","183 ÷ 3 = 61이에요."],"variant_rule":{"alt":[{"stem":"6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."]},{"stem":"5.4 ÷ 0.45의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#14','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',4,'mc','auto','□ ÷ 0.21 = 40이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X02']::text[],true,'{"seq":14,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"□ ÷ 0.21 = 40이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.4","correct":true},{"t":"0.84","mis":"M6-2-u3-X03"},{"t":"84","mis":"M6-2-u3-X04"},{"t":"840","mis":"M6-2-u3-X02"}],"explanation":["□ = 40 × 0.21이에요.","40 × 0.21 = 8.4예요.","8.4 ÷ 0.21 = 40으로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 1.5 = 1.7이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2.55","correct":true},{"t":"0.255","mis":"M6-2-u3-X03"},{"t":"25.5","mis":"M6-2-u3-X04"},{"t":"255","mis":"M6-2-u3-X02"}],"explanation":["□ = 1.7 × 1.5예요.","1.7 × 1.5 = 2.55예요.","2.55 ÷ 1.5 = 1.7로 맞아요."]},{"stem":"□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"0.54","mis":"M6-2-u3-X03"},{"t":"54","mis":"M6-2-u3-X04"},{"t":"540","mis":"M6-2-u3-X02"}],"explanation":["□ = 12 × 0.45예요.","12 × 0.45 = 5.4예요.","5.4 ÷ 0.45 = 12로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#15','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":15,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"5.4 ÷ 4.5","correct":true},{"t":"5.4 ÷ 0.45","mis":"M6-2-u3-X19"},{"t":"540 ÷ 45","mis":"M6-2-u3-X19"},{"t":"54 ÷ 4.5","mis":"M6-2-u3-X19"}],"explanation":["5.4 ÷ 0.45, 540 ÷ 45, 54 ÷ 4.5는 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 12예요.","5.4 ÷ 4.5는 한 수만 바뀌어 몫이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"2.55 ÷ 0.15","correct":true},{"t":"2.55 ÷ 1.5","mis":"M6-2-u3-X19"},{"t":"25.5 ÷ 15","mis":"M6-2-u3-X19"},{"t":"255 ÷ 150","mis":"M6-2-u3-X19"}],"explanation":["2.55 ÷ 1.5, 25.5 ÷ 15, 255 ÷ 150은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 1.7이에요.","2.55 ÷ 0.15는 한 수만 바뀌어 몫이 달라요."]},{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 한 수만 바뀌어 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#16','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',1,'sa','auto','7 ÷ 1.75의 몫은 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["나누어지는 수 7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."],"variant_rule":{"alt":[{"stem":"18 ÷ 3.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 18은 18.0과 같아요 — 나누는 수 3.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","18 ÷ 3.6은 180 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","180 ÷ 36 = 5예요."]},{"stem":"8 ÷ 1.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#17','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',2,'mc','auto','7 ÷ 0.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":17,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"7 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"17.5","correct":true},{"t":"1.75","mis":"M6-2-u3-X03"},{"t":"175","mis":"M6-2-u3-X04"},{"t":"0.175","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 7은 7.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 0.4는 70 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 17.5예요."],"variant_rule":{"alt":[{"stem":"2 ÷ 0.8의 몫은 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"0.25","mis":"M6-2-u3-X03"},{"t":"25","mis":"M6-2-u3-X04"},{"t":"0.025","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 2는 2.0과 같아요 — 나누는 수 0.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","2 ÷ 0.8은 20 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.5예요."]},{"stem":"5 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"12.5","correct":true},{"t":"1.25","mis":"M6-2-u3-X03"},{"t":"125","mis":"M6-2-u3-X04"},{"t":"0.125","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 5는 5.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","5 ÷ 0.4는 50 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 12.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#18','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',3,'ox','auto','9 ÷ 0.6의 몫은 9보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":18,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"9 ÷ 0.6의 몫은 9보다 작아요.","answer":"X","reason_options":[{"t":"0.6은 1보다 작아서 9 안에 9번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["9 ÷ 0.6 = 15예요.","15는 9보다 커요.","1보다 작은 수로 나누면 몫이 커져요."],"variant_rule":{"alt":[{"stem":"12 ÷ 0.8의 몫은 12보다 작아요.","answer":"X","reason_options":[{"t":"0.8은 1보다 작아서 12 안에 12번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["12 ÷ 0.8 = 15예요.","15는 12보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]},{"stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["16 ÷ 0.25 = 64예요.","64는 16보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#19','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',4,'mc','auto','수 카드 1, 8, 3을 한 번씩만 써서 12.6 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X09','M6-2-u3-X19']::text[],true,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"수 카드 1, 8, 3을 한 번씩만 써서 12.6 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"8.31","correct":true},{"t":"1.38","mis":"M6-2-u3-X09"},{"t":"3.18","mis":"M6-2-u3-X09"},{"t":"8.13","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 8.31이에요.","그래서 □는 8.31이에요."],"variant_rule":{"alt":[{"stem":"수 카드 5, 2, 9를 한 번씩만 써서 30 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"2.59","correct":true},{"t":"9.52","mis":"M6-2-u3-X09"},{"t":"5.29","mis":"M6-2-u3-X09"},{"t":"2.95","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 2.59예요.","그래서 □는 2.59예요."]},{"stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6.52","correct":true},{"t":"2.56","mis":"M6-2-u3-X09"},{"t":"5.26","mis":"M6-2-u3-X09"},{"t":"6.25","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 6.52예요.","그래서 □는 6.52예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#20','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C7',1,'mc','auto','6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":20,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.77","correct":true},{"t":"4.76","mis":"M6-2-u3-X11"},{"t":"4.769","mis":"M6-2-u3-X12"},{"t":"4.8","mis":"M6-2-u3-X12"}],"explanation":["6.2 ÷ 1.3 = 4.7692…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 4.77이에요."],"variant_rule":{"alt":[{"stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."]},{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.17","correct":true},{"t":"0.16","mis":"M6-2-u3-X11"},{"t":"0.167","mis":"M6-2-u3-X12"},{"t":"0.2","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#21','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 일의 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 일의 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["1"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","일의 자리의 한 자리 아래는 소수 첫째 자리예요.","그래서 소수 첫째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#22','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C7',3,'mc','auto','6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 4.76이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":22,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 4.76이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["6.2 ÷ 1.3 = 4.769…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 4.77이에요."],"variant_rule":{"alt":[{"stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["3.38 ÷ 0.9 = 3.755…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 3.8이에요."]},{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 0.17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#23','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',1,'sa','auto','당근주스 9.6 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["9.6 ÷ 1.5를 계산하면 6.4예요.","1.5 L씩 6번 주면 9 L, 7번 주려면 10.5 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["15.2 ÷ 2.4를 계산하면 6.333…이에요.","2.4 L씩 6번 주면 14.4 L, 7번 주려면 16.8 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L, 5번 주려면 9 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#24','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 9.6 L를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 9.6 L를 한 명에게 1.5 L씩 6명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.4 L","mis":"M6-2-u3-X14"},{"t":"9 L","mis":"M6-2-u3-X15"},{"t":"1.5 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.5 × 6 = 9 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","9.6 − 9 = 0.6 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.9 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"12.8 L","mis":"M6-2-u3-X15"},{"t":"1.6 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.6 × 8 = 12.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","13.7 − 12.8 = 0.9 (L)예요."]},{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_c#25','math',6,2,'u3','','g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',4,'essay','teacher','주스 8.5 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"주스 8.5 L를 한 명에게 1.5 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 8.5 ÷ 1.5 = 5.66…이므로 5명에게 나누어 줄 수 있다. 나누어 준 주스는 1.5 × 5 = 7.5 L이고 남는 주스는 8.5 − 7.5 = 1 L이다. 몫을 반올림해 6명으로 하면 9 L가 있어야 하는데 모자라므로 반올림하면 안 된다.","scoring_points":["5명을 구했는가","남는 주스 1 L를 구했는가","반올림하면 주스가 모자란다는 까닭을 썼는가"]},"explanation":["8.5 ÷ 1.5 = 5.66… — 5명이에요.","남는 양은 8.5 − 7.5 = 1 (L)예요.","6명이면 9 L가 필요해 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#1','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C1',1,'sa','auto','35 ÷ 7의 몫은 5예요. 두 수에 똑같이 10을 곱한 350 ÷ 70의 몫은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"35 ÷ 7의 몫은 5예요. 두 수에 똑같이 10을 곱한 350 ÷ 70의 몫은 얼마인가요?","answer":["5"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","350 ÷ 70은 35 ÷ 7의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 5예요."],"variant_rule":{"alt":[{"stem":"12 ÷ 3의 몫은 4예요. 두 수에 똑같이 10을 곱한 120 ÷ 30의 몫은 얼마인가요?","answer":["4"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","120 ÷ 30은 12 ÷ 3의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 4예요."]},{"stem":"18 ÷ 6의 몫은 3이에요. 두 수에 똑같이 10을 곱한 180 ÷ 60의 몫은 얼마인가요?","answer":["3"],"explanation":["두 수에 똑같은 수를 곱하면 몫은 그대로예요.","180 ÷ 60은 18 ÷ 6의 두 수에 10을 곱한 식이에요.","그래서 몫은 그대로 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#2','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C1',2,'mc','auto','큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":2,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"큰 상자의 높이는 1.35 m, 작은 상자의 높이는 0.45 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"135 ÷ 45","correct":true},{"t":"135 ÷ 0.45","mis":"M6-2-u3-X18"},{"t":"1.35 ÷ 45","mis":"M6-2-u3-X18"},{"t":"45 ÷ 135","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","1.35 m는 135 cm, 0.45 m는 45 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 135 ÷ 45예요."],"variant_rule":{"alt":[{"stem":"빨간 화분의 강낭콩 싹은 2.4 cm, 노란 화분의 강낭콩 싹은 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 8","correct":true},{"t":"24 ÷ 0.8","mis":"M6-2-u3-X18"},{"t":"2.4 ÷ 8","mis":"M6-2-u3-X18"},{"t":"8 ÷ 24","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","2.4 cm는 24 mm, 0.8 cm는 8 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 24 ÷ 8이에요."]},{"stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"824 ÷ 412","correct":true},{"t":"824 ÷ 4.12","mis":"M6-2-u3-X18"},{"t":"8.24 ÷ 412","mis":"M6-2-u3-X18"},{"t":"412 ÷ 824","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","8.24 m는 824 cm, 4.12 m는 412 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 824 ÷ 412예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#3','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C2',1,'mc','auto','7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":1,"kind":"mc","stem":"7.2 ÷ 0.6을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨72/10⟩ ÷ ⟨6/10⟩","correct":true},{"t":"⟨72/10⟩ ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"⟨72/10⟩ ÷ ⟨6/100⟩","mis":"M6-2-u3-X05"},{"t":"7.2 ÷ ⟨6/10⟩","mis":"M6-2-u3-X06"}],"explanation":["7.2는 ⟨72/10⟩, 0.6은 ⟨6/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨72/10⟩ ÷ ⟨6/10⟩이에요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ ÷ ⟨21/10⟩","correct":true},{"t":"⟨84/10⟩ ÷ 2.1","mis":"M6-2-u3-X06"},{"t":"⟨84/10⟩ ÷ ⟨21/100⟩","mis":"M6-2-u3-X05"},{"t":"8.4 ÷ ⟨21/10⟩","mis":"M6-2-u3-X06"}],"explanation":["8.4는 ⟨84/10⟩, 2.1은 ⟨21/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨84/10⟩ ÷ ⟨21/10⟩이에요."]},{"stem":"4.9 ÷ 0.7을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨49/10⟩ ÷ ⟨7/10⟩","correct":true},{"t":"⟨49/10⟩ ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"⟨49/10⟩ ÷ ⟨7/100⟩","mis":"M6-2-u3-X05"},{"t":"4.9 ÷ ⟨7/10⟩","mis":"M6-2-u3-X06"}],"explanation":["4.9는 ⟨49/10⟩, 0.7은 ⟨7/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨49/10⟩ ÷ ⟨7/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#4','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C2',2,'mc','auto','0.56 ÷ 0.14를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":4,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"0.56 ÷ 0.14를 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"56 ÷ 14","correct":true},{"t":"56 ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"0.56 ÷ 14","mis":"M6-2-u3-X01"},{"t":"56 ÷ 140","mis":"M6-2-u3-X05"}],"explanation":["0.56 = ⟨56/100⟩, 0.14 = ⟨14/100⟩예요.","분모가 같으니 분자끼리 나눠요.","그래서 56 ÷ 14예요."],"variant_rule":{"alt":[{"stem":"4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"49 ÷ 7","correct":true},{"t":"49 ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"4.9 ÷ 7","mis":"M6-2-u3-X01"},{"t":"49 ÷ 70","mis":"M6-2-u3-X05"}],"explanation":["4.9 = ⟨49/10⟩, 0.7 = ⟨7/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 49 ÷ 7이에요."]},{"stem":"7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"72 ÷ 6","correct":true},{"t":"72 ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"7.2 ÷ 6","mis":"M6-2-u3-X01"},{"t":"72 ÷ 60","mis":"M6-2-u3-X05"}],"explanation":["7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 72 ÷ 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#5','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C2',3,'ox','auto','7.2 ÷ 0.6을 계산할 때 7.2만 ⟨72/10⟩로 바꾸고 0.6은 소수 그대로 두어도 분자끼리 나눌 수 있어요.',ARRAY['M6-2-u3-X06']::text[],true,'{"seq":5,"concept":"M6-2-u3-C2","difficulty":3,"kind":"ox","stem":"7.2 ÷ 0.6을 계산할 때 7.2만 ⟨72/10⟩로 바꾸고 0.6은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"mis":"M6-2-u3-X06","explanation":["⟨72/10⟩ ÷ 0.6은 분자끼리 나눌 수 없어요.","0.6도 ⟨6/10⟩으로 바꾸어야 해요.","⟨72/10⟩ ÷ ⟨6/10⟩으로 분자끼리 나눠요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 2.1을 계산할 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨84/10⟩ ÷ 2.1은 분자끼리 나눌 수 없어요.","2.1도 ⟨21/10⟩로 바꾸어야 해요.","⟨84/10⟩ ÷ ⟨21/10⟩로 분자끼리 나눠요."]},{"stem":"4.9 ÷ 0.7을 계산할 때 4.9만 ⟨49/10⟩로 바꾸고 0.7은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"explanation":["⟨49/10⟩ ÷ 0.7은 분자끼리 나눌 수 없어요.","0.7도 ⟨7/10⟩로 바꾸어야 해요.","⟨49/10⟩ ÷ ⟨7/10⟩로 분자끼리 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#6','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C3',1,'sa','auto','7.2 ÷ 0.6을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"7.2 ÷ 0.6을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.6이 정해요.","0.6이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.1이 정해요.","2.1이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.5가 정해요.","0.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#7','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C3',2,'mc','auto','5.1 ÷ 0.6의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"5.1 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"8.5","correct":true},{"t":"0.85","mis":"M6-2-u3-X03"},{"t":"85","mis":"M6-2-u3-X04"},{"t":"0.085","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.1 ÷ 0.6은 51 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 8.5예요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5의 몫은 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"},{"t":"0.072","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.6 ÷ 0.5는 36 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.2예요."]},{"stem":"4.5 ÷ 0.6의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.5 ÷ 0.6은 45 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#8','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C3',3,'mc','auto','5.1 ÷ 0.6의 몫을 0.85라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02','M6-2-u3-X04']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"5.1 ÷ 0.6의 몫을 0.85라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["5.1 ÷ 0.6은 51 ÷ 6 = 8.5예요.","0.85는 8.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5는 36 ÷ 5 = 7.2예요.","0.72는 7.2보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]},{"stem":"4.5 ÷ 0.6의 몫을 0.75라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["4.5 ÷ 0.6은 45 ÷ 6 = 7.5예요.","0.75는 7.5보다 10배 작은 수예요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
