INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#11','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C4',3,'mc','auto','0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":11,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.56 ÷ 0.16을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨56/100⟩ ÷ ⟨16/100⟩","correct":true},{"t":"⟨56/100⟩ ÷ 0.16","mis":"M6-2-u3-X06"},{"t":"⟨56/100⟩ ÷ ⟨16/10⟩","mis":"M6-2-u3-X05"},{"t":"0.56 ÷ ⟨16/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.56은 ⟨56/100⟩, 0.16은 ⟨16/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨56/100⟩ ÷ ⟨16/100⟩이에요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/100⟩ ÷ ⟨14/100⟩","correct":true},{"t":"⟨77/100⟩ ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"⟨77/100⟩ ÷ ⟨14/10⟩","mis":"M6-2-u3-X05"},{"t":"0.77 ÷ ⟨14/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.77은 ⟨77/100⟩, 0.14는 ⟨14/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/100⟩ ÷ ⟨14/100⟩예요."]},{"stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨8/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#12','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',1,'mc','auto','9.6 ÷ 0.32에서 9.6의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":12,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"9.6 ÷ 0.32에서 9.6의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"960","correct":true},{"t":"96","mis":"M6-2-u3-X07"},{"t":"9.60","mis":"M6-2-u3-X07"},{"t":"9600","mis":"M6-2-u3-X02"}],"explanation":["9.6의 소수점을 한 칸 옮기면 96이에요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 960이 돼요."],"variant_rule":{"alt":[{"stem":"5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"540","correct":true},{"t":"54","mis":"M6-2-u3-X07"},{"t":"5.40","mis":"M6-2-u3-X07"},{"t":"5400","mis":"M6-2-u3-X02"}],"explanation":["5.4의 소수점을 한 칸 옮기면 54예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 540이 돼요."]},{"stem":"8.4 ÷ 0.21에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 어떤 수가 되나요?","options":[{"t":"840","correct":true},{"t":"84","mis":"M6-2-u3-X07"},{"t":"8.40","mis":"M6-2-u3-X07"},{"t":"8400","mis":"M6-2-u3-X02"}],"explanation":["8.4의 소수점을 한 칸 옮기면 84예요.","한 칸 더 옮길 자리가 비어 있어요.","빈 자리는 0으로 채워 840이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#13','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',2,'sa','auto','6.3 ÷ 0.42의 몫은 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."],"variant_rule":{"alt":[{"stem":"5.4 ÷ 0.45의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."]},{"stem":"8.4 ÷ 0.21의 몫은 얼마인가요?","answer":["40"],"explanation":["나누는 수 0.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.4 ÷ 0.21은 840 ÷ 21이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 21 = 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#14','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',4,'mc','auto','□ ÷ 1.5 = 1.7이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X02']::text[],true,'{"seq":14,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"□ ÷ 1.5 = 1.7이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2.55","correct":true},{"t":"0.255","mis":"M6-2-u3-X03"},{"t":"25.5","mis":"M6-2-u3-X04"},{"t":"255","mis":"M6-2-u3-X02"}],"explanation":["□ = 1.7 × 1.5예요.","1.7 × 1.5 = 2.55예요.","2.55 ÷ 1.5 = 1.7로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.45 = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"0.54","mis":"M6-2-u3-X03"},{"t":"54","mis":"M6-2-u3-X04"},{"t":"540","mis":"M6-2-u3-X02"}],"explanation":["□ = 12 × 0.45예요.","12 × 0.45 = 5.4예요.","5.4 ÷ 0.45 = 12로 맞아요."]},{"stem":"□ ÷ 2.4 = 3.6이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8.64","correct":true},{"t":"0.864","mis":"M6-2-u3-X03"},{"t":"86.4","mis":"M6-2-u3-X04"},{"t":"864","mis":"M6-2-u3-X02"}],"explanation":["□ = 3.6 × 2.4예요.","3.6 × 2.4 = 8.64예요.","8.64 ÷ 2.4 = 3.6으로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#15','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":15,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"2.55 ÷ 0.15","correct":true},{"t":"2.55 ÷ 1.5","mis":"M6-2-u3-X19"},{"t":"25.5 ÷ 15","mis":"M6-2-u3-X19"},{"t":"255 ÷ 150","mis":"M6-2-u3-X19"}],"explanation":["2.55 ÷ 1.5, 25.5 ÷ 15, 255 ÷ 150은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 1.7이에요.","2.55 ÷ 0.15는 한 수만 바뀌어 몫이 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"4.86 ÷ 0.6","correct":true},{"t":"48.6 ÷ 0.6","mis":"M6-2-u3-X19"},{"t":"486 ÷ 6","mis":"M6-2-u3-X19"},{"t":"4.86 ÷ 0.06","mis":"M6-2-u3-X19"}],"explanation":["48.6 ÷ 0.6, 486 ÷ 6, 4.86 ÷ 0.06은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 81이에요.","4.86 ÷ 0.6은 한 수만 바뀌어 몫이 달라요."]},{"stem":"이번에는 다른 보기예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"8.64 ÷ 0.24","correct":true},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"86.4 ÷ 24","mis":"M6-2-u3-X19"},{"t":"864 ÷ 240","mis":"M6-2-u3-X19"}],"explanation":["8.64 ÷ 2.4, 86.4 ÷ 24, 864 ÷ 240은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.6이에요.","8.64 ÷ 0.24는 한 수만 바뀌어 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#16','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',1,'sa','auto','18 ÷ 3.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"18 ÷ 3.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 18은 18.0과 같아요 — 나누는 수 3.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","18 ÷ 3.6은 180 ÷ 36이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","180 ÷ 36 = 5예요."],"variant_rule":{"alt":[{"stem":"8 ÷ 1.6의 몫은 얼마인가요?","answer":["5"],"explanation":["나누어지는 수 8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."]},{"stem":"16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["나누어지는 수 16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수를 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#17','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',2,'mc','auto','2 ÷ 0.8의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":17,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"2 ÷ 0.8의 몫은 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"0.25","mis":"M6-2-u3-X03"},{"t":"25","mis":"M6-2-u3-X04"},{"t":"0.025","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 2는 2.0과 같아요 — 나누는 수 0.8이 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","2 ÷ 0.8은 20 ÷ 8이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 2.5예요."],"variant_rule":{"alt":[{"stem":"5 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"12.5","correct":true},{"t":"1.25","mis":"M6-2-u3-X03"},{"t":"125","mis":"M6-2-u3-X04"},{"t":"0.125","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 5는 5.0과 같아요 — 나누는 수 0.4가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","5 ÷ 0.4는 50 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 12.5예요."]},{"stem":"9 ÷ 1.2의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"0.75","mis":"M6-2-u3-X03"},{"t":"75","mis":"M6-2-u3-X04"},{"t":"0.075","mis":"M6-2-u3-X03"}],"explanation":["나누어지는 수 9는 9.0과 같아요 — 나누는 수 1.2가 자연수가 되도록 두 수를 한 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 1.2는 90 ÷ 12가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","몫의 소수점은 옮긴 자리에서 올려 찍어 7.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#18','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',3,'ox','auto','12 ÷ 0.8의 몫은 12보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":18,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"12 ÷ 0.8의 몫은 12보다 작아요.","answer":"X","reason_options":[{"t":"0.8은 1보다 작아서 12 안에 12번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["12 ÷ 0.8 = 15예요.","15는 12보다 커요.","1보다 작은 수로 나누면 몫이 커져요."],"variant_rule":{"alt":[{"stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["16 ÷ 0.25 = 64예요.","64는 16보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]},{"stem":"31 ÷ 0.62의 몫은 31보다 작아요.","answer":"X","reason_options":[{"t":"0.62는 1보다 작아서 31 안에 31번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["31 ÷ 0.62 = 50이에요.","50은 31보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#19','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',4,'mc','auto','수 카드 5, 2, 9를 한 번씩만 써서 30 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X09','M6-2-u3-X19']::text[],true,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"수 카드 5, 2, 9를 한 번씩만 써서 30 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"2.59","correct":true},{"t":"9.52","mis":"M6-2-u3-X09"},{"t":"5.29","mis":"M6-2-u3-X09"},{"t":"2.95","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 2.59예요.","그래서 □는 2.59예요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □의 몫을 가장 작게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6.52","correct":true},{"t":"2.56","mis":"M6-2-u3-X09"},{"t":"5.26","mis":"M6-2-u3-X09"},{"t":"6.25","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 6.52예요.","그래서 □는 6.52예요."]},{"stem":"수 카드 3, 7, 4를 한 번씩만 써서 20 ÷ □의 몫을 가장 크게 만들려고 해요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"3.47","correct":true},{"t":"7.43","mis":"M6-2-u3-X09"},{"t":"4.37","mis":"M6-2-u3-X09"},{"t":"3.74","mis":"M6-2-u3-X19"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","만들 수 있는 □.□□ 가운데 가장 작은 수는 3.47이에요.","그래서 □는 3.47이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#20','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',1,'mc','auto','3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":20,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."],"variant_rule":{"alt":[{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.17","correct":true},{"t":"0.16","mis":"M6-2-u3-X11"},{"t":"0.167","mis":"M6-2-u3-X12"},{"t":"0.2","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."]},{"stem":"2 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.29","correct":true},{"t":"0.28","mis":"M6-2-u3-X11"},{"t":"0.286","mis":"M6-2-u3-X12"},{"t":"0.3","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 7 = 0.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 0.29예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#21','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 소수 둘째 자리까지 나타내요. 올릴지 버릴지 정하려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 둘째 자리의 한 자리 아래는 소수 셋째 자리예요.","그래서 소수 셋째 자리 숫자를 봐요."]},{"stem":"몫을 반올림하여 소수 첫째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["2"],"explanation":["반올림은 나타낼 자리의 바로 한 자리 아래 숫자를 봐요.","소수 첫째 자리의 한 자리 아래는 소수 둘째 자리예요.","그래서 소수 둘째 자리 숫자를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#22','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',3,'mc','auto','3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":22,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 3.7이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["3.38 ÷ 0.9 = 3.755…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 3.8이에요."],"variant_rule":{"alt":[{"stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","5 이상이라 올려 0.17이에요."]},{"stem":"2 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 친구가 0.2라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 둘째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 첫째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"일의 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["2 ÷ 7 = 0.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","5 이상이라 올려 0.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#23','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',1,'sa','auto','당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 15.2 L를 한 명에게 2.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["6"],"explanation":["15.2 ÷ 2.4를 계산하면 6.333…이에요.","2.4 L씩 6번 주면 14.4 L, 7번 주려면 16.8 L가 있어야 해요.","그래서 6명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L, 5번 주려면 9 L가 있어야 해요.","그래서 4명에게 나누어 줄 수 있어요."]},{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L, 8번 주려면 11.2 L가 있어야 해요.","그래서 7명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#24','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 13.7 L를 한 명에게 1.6 L씩 8명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.9 L","correct":true},{"t":"0.5 L","mis":"M6-2-u3-X14"},{"t":"12.8 L","mis":"M6-2-u3-X15"},{"t":"1.6 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.6 × 8 = 12.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","13.7 − 12.8 = 0.9 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."]},{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u3_review_d#25','math',6,2,'u3','','g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',4,'essay','teacher','주스 10.2 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"주스 10.2 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있고 남는 주스는 몇 L인지 구하는 과정을 쓰고, 몫을 반올림하여 사람 수를 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 10.2 ÷ 1.8 = 5.66…이므로 5명에게 나누어 줄 수 있다. 나누어 준 주스는 1.8 × 5 = 9 L이고 남는 주스는 10.2 − 9 = 1.2 L이다. 몫을 반올림해 6명으로 하면 10.8 L가 있어야 하는데 모자라므로 반올림하면 안 된다.","scoring_points":["5명을 구했는가","남는 주스 1.2 L를 구했는가","반올림하면 주스가 모자란다는 까닭을 썼는가"]},"explanation":["10.2 ÷ 1.8 = 5.66… — 5명이에요.","남는 양은 10.2 − 9 = 1.2 (L)예요.","6명이면 10.8 L가 필요해 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
